window.BANCO = window.BANCO || [];
window.BANCO.push({"id":"trebep","nombre":"TREBEP, Estatuto Básico del Empleado Público","bloques":[{"id":"ambito","nombre":"Ámbito de aplicación (arts. 1 a 7)"},{"id":"clases","nombre":"Clases de personal (arts. 8 a 13)"},{"id":"derechos","nombre":"Derechos y deberes (arts. 14 a 20)"},{"id":"retribuciones","nombre":"Retribuciones (arts. 21 a 30)"},{"id":"negociacion","nombre":"Negociación colectiva (arts. 31 a 38)"},{"id":"representacion","nombre":"Representación y derecho de reunión (arts. 39 a 46)"},{"id":"jornada","nombre":"Jornada, permisos y vacaciones (arts. 47 a 51)"},{"id":"deberes","nombre":"Deberes y código de conducta (arts. 52 a 54)"},{"id":"acceso","nombre":"Acceso al empleo público (arts. 55 a 62)"},{"id":"adquisicion","nombre":"Adquisición y pérdida de la relación de servicio (arts. 63 a 68)"},{"id":"provision","nombre":"Ordenación de la actividad profesional y provisión (arts. 69 a 84)"},{"id":"situaciones","nombre":"Situaciones administrativas (arts. 85 a 92)"},{"id":"disciplina","nombre":"Régimen disciplinario (arts. 93 a 98)"},{"id":"otros","nombre":"Otras normas relacionadas"}],"calendarios":{},"casos":[],"preguntas":[{"id":"au-01-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":1,"enunciado":"El Estatuto Básico del Empleado Público tiene por objeto:","opciones":["Establecer las bases del régimen estatutario de todos los funcionarios públicos.","Establecer las bases del régimen estatutario de los funcionarios públicos incluidos en su ámbito de aplicación.","Establecer las bases del régimen estatutario de todos los empleados públicos.","Establecer las bases del régimen estatutario del personal laboral incluido en su ámbito de aplicación."],"bloque":"ambito","precepto":"Art. 1.1 del TREBEP","correcta":1,"justificaciones":["No. El Estatuto no regula a todos los funcionarios, solo a los incluidos en su ámbito de aplicación. Hay funcionarios (jueces, militares, Cortes...) que se rigen por su propia ley.","Es esta. El **art. 1.1** dice que el Estatuto fija las bases del régimen estatutario de los funcionarios públicos incluidos en su ámbito de aplicación.","No. Te han cambiado “funcionarios” por “empleados públicos” y “incluidos en su ámbito” por “todos”. Las bases estatutarias son para funcionarios; el personal laboral se trata aparte (art. 1.2).","No. El personal laboral solo aparece en el **art. 1.2**, para determinar las normas que se le aplican. El objeto principal (art. 1.1) es el régimen estatutario de los funcionarios."]},{"id":"au-01-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":2,"enunciado":"Señale la opción incorrecta. El TREBEP se aplica directamente a:","opciones":["El personal laboral de las Universidades Públicas.","El personal laboral de la Administración General del Estado.","El personal funcionario de las Administraciones de las Comunidades Autónomas.","El personal funcionario de los órganos constitucionales del Estado."],"bloque":"ambito","precepto":"Arts. 2 y 4 del TREBEP","correcta":3,"justificaciones":["Es verdadera, así que no se marca. Las Universidades Públicas están en el ámbito del **art. 2.1.e**, y su personal laboral se rige por el Estatuto en lo que proceda.","Es verdadera, así que no se marca. La Administración General del Estado es la primera del **art. 2.1.a**.","Es verdadera, así que no se marca. Las Administraciones de las comunidades autónomas están en el **art. 2.1.b**.","Esta es la falsa, y por eso es la que hay que marcar. El personal funcionario de los demás órganos constitucionales del Estado está en el **art. 4.b**: el Estatuto solo se le aplica directamente si su legislación específica lo dispone."]},{"id":"au-01-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":3,"enunciado":"Según lo establecido en el artículo 3.2 del TREBEP, los Cuerpos de Policía Local se rigen por este Estatuto y por la legislación de las comunidades autónomas:","opciones":["Exclusivamente.","Solo cuando así lo disponga su legislación específica.","Excepto en lo establecido para ellos en la Ley Orgánica de Fuerzas y Cuerpos de Seguridad.","Excepto en lo establecido para ellos en la Ley Reguladoras de las Bases del Régimen Local."],"bloque":"ambito","precepto":"Art. 3.2 del TREBEP","correcta":2,"justificaciones":["No. El **art. 3.2** dice que se rigen “también” por el Estatuto y por la legislación autonómica, pero con una excepción, así que no es “exclusivamente”.","No. No depende de lo que diga su legislación específica. Se rigen por el Estatuto directamente, salvo lo que la ley de fuerzas y cuerpos de seguridad regule para ellos.","Es esta. Excepto en lo establecido para ellos en la **Ley Orgánica 2/1986** de Fuerzas y Cuerpos de Seguridad (art. 3.2).","No. La excepción no es la ley de bases de régimen local, sino la Ley Orgánica 2/1986, de Fuerzas y Cuerpos de Seguridad."]},{"id":"au-01-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":4,"enunciado":"Señale la respuesta correcta en relación con el ámbito de aplicación del TREBEP:","opciones":["No será de aplicación al personal investigador al servicio de las Administraciones Públicas.","El personal docente y el personal estatutario de los Servicios de Salud se regirán únicamente por su legislación específica.","Cada vez que este Estatuto haga mención al personal funcionario de carrera se entenderá comprendido el personal estatutario de los Servicios de Salud.","El presente Estatuto se aplicará directamente a todo el personal de las Administraciones Públicas."],"bloque":"ambito","precepto":"Art. 2.4 del TREBEP","correcta":2,"justificaciones":["No. El **art. 2.2** permite dictar normas singulares para el personal de investigación, pero el Estatuto sí se les aplica.","No. El personal docente y el estatutario se rigen por su legislación específica y además por lo previsto en el Estatuto (con algunas excepciones), no “únicamente” por la específica (**art. 2.3**).","Es esta. El **art. 2.4** dice que cada vez que el Estatuto menciona al personal funcionario de carrera se entiende comprendido el personal estatutario de los Servicios de Salud.","No. No se aplica directamente a todo el personal. Hay personal con legislación específica propia (**art. 4**) y el personal laboral solo en lo que proceda."]},{"id":"au-01-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":5,"enunciado":"Según el artículo 3 del TREBEP, el personal funcionario de las entidades locales se rige, con respeto a la autonomía local, por:","opciones":["La legislación estatal que resulte de aplicación, de la que no forma parte este Estatuto, y por la de las comunidades autónomas.","La legislación estatal que resulte de aplicación, de la que forma parte este Estatuto, y por la de las comunidades autónomas.","Exclusivamente por este Estatuto.","Exclusivamente por la legislación de las comunidades autónomas."],"bloque":"ambito","precepto":"Art. 3.1 del TREBEP","correcta":1,"justificaciones":["No. Te han dicho que el Estatuto no forma parte de la legislación estatal aplicable. Sí forma parte.","Es esta. El **art. 3.1** dice que se rigen por la legislación estatal que resulte de aplicación, de la que forma parte este Estatuto, y por la de las comunidades autónomas, con respeto a la autonomía local.","No. No es “exclusivamente” el Estatuto: también cuenta la legislación autonómica.","No. No es solo la legislación autonómica: también se aplica la estatal, y el Estatuto es parte de ella."]},{"id":"au-01-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":6,"enunciado":"El TREBEP se aplica directamente al personal del Banco de España:","opciones":["En todos los aspectos que la Ley regula.","Cuando así lo disponga su legislación específica.","No se les aplica en ningún supuesto.","En su totalidad, a excepción del régimen sancionador."],"bloque":"ambito","precepto":"Art. 4.h del TREBEP","correcta":1,"justificaciones":["No. El personal del Banco de España está en la lista del **art. 4**, así que el Estatuto no se le aplica en todos los aspectos.","Es esta. El **art. 4.h** incluye al personal del Banco de España y del Fondo de Garantía de Depósitos entre quienes solo se rigen directamente por el Estatuto cuando lo disponga su legislación específica.","No. No es “en ningún supuesto”: si su legislación específica lo dispone, se aplica.","No. No hay una excepción solo para el régimen sancionador. Todo depende de lo que disponga su legislación específica."]},{"id":"au-01-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":7,"enunciado":"De acuerdo con lo establecido en su artículo 2, el TREBEP será de aplicación directa:","opciones":["Al personal funcionario de las Cortes Generales.","Al personal laboral al servicio de las Administraciones Públicas de las ciudades de Ceuta y Melilla.","Al Personal de las Fuerzas y Cuerpos de Seguridad del Estado.","Al personal laboral de entidades de derecho privado dependientes de cualquiera de las Administraciones Públicas."],"bloque":"ambito","precepto":"Art. 2.1.b del TREBEP","correcta":1,"justificaciones":["No. El personal funcionario de las Cortes Generales está en el **art. 4.a**: solo se le aplica el Estatuto si su legislación específica lo dispone.","Es esta. El **art. 2.1.b** incluye a las Administraciones de las comunidades autónomas y de las ciudades de Ceuta y Melilla, y se aplica a su personal laboral en lo que proceda.","No. El personal de las Fuerzas y Cuerpos de Seguridad del Estado está en el **art. 4.e**.","No. El **art. 2.1.d** habla de entidades de derecho público. Las entidades de derecho privado no están en esa lista."]},{"id":"au-01-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":8,"enunciado":"Conforme al artículo 4 del TREBEP, las disposiciones de este Estatuto solo se aplicarán directamente cuando así lo disponga su legislación específica al siguiente personal:","opciones":["Personal retribuido por arancel.","Personal docente.","Personal investigador.","Personal estatutario de los Servicios de Salud."],"bloque":"ambito","precepto":"Art. 4.f del TREBEP","correcta":0,"justificaciones":["Es esta. El personal retribuido por arancel está en la lista del **art. 4.f**: el Estatuto solo se le aplica directamente si su legislación específica lo dispone.","No. El personal docente no está en el art. 4. Se rige por su legislación específica y por el Estatuto, salvo algunos preceptos (**art. 2.3**).","No. Para el personal de investigación el **art. 2.2** solo permite dictar normas singulares. No está en el art. 4.","No. El personal estatutario de los Servicios de Salud está en el **art. 2.3**, no en el art. 4."]},{"id":"au-01-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":9,"enunciado":"Las disposiciones del TREBEP sólo se aplicarán directamente cuando así lo disponga su legislación específica a:","opciones":["El personal estatutario de los servicios de salud.","El personal militar de las Fuerzas Armadas.","El personal de las Universidades Públicas.","Los Cuerpos de Policía Local."],"bloque":"ambito","precepto":"Art. 4.d del TREBEP","correcta":1,"justificaciones":["No. El personal estatutario de los servicios de salud se rige por su legislación específica y por el Estatuto (**art. 2.3**). No está en la lista del art. 4.","Es esta. El personal militar de las Fuerzas Armadas está en el **art. 4.d**: solo se le aplica el Estatuto directamente cuando lo disponga su legislación específica.","No. Las Universidades Públicas están en el ámbito de aplicación directa (**art. 2.1.e**).","No. Los Cuerpos de Policía Local se rigen también por el Estatuto (**art. 3.2**), con la excepción de la ley orgánica de fuerzas y cuerpos de seguridad."]},{"id":"au-01-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":10,"enunciado":"Señale la respuesta incorrecta. Según el TREBEP, las disposiciones del Estatuto Básico del Empleado Público solo se aplicarán directamente cuando así lo disponga su legislación específica al siguiente personal:","opciones":["Personal de las Fuerzas y Cuerpos de Seguridad.","Personal funcionario de las asambleas legislativas de las comunidades autónomas.","Personal del Banco de España.","Personal de los organismos públicos vinculados o dependientes de cualquiera de las Administraciones Públicas."],"bloque":"ambito","precepto":"Arts. 2.1.d y 4 del TREBEP","correcta":3,"justificaciones":["Es verdadera, así que no se marca. El personal de las Fuerzas y Cuerpos de Seguridad está en el **art. 4.e**.","Es verdadera, así que no se marca. El personal funcionario de las asambleas legislativas autonómicas está en el **art. 4.a**.","Es verdadera, así que no se marca. El personal del Banco de España está en el **art. 4.h**.","Esta es la falsa, y por eso es la que hay que marcar. Los organismos públicos y entidades de derecho público vinculados o dependientes de las Administraciones Públicas están en el **art. 2.1.d**: el Estatuto se les aplica directamente."]},{"id":"au-01-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":11,"enunciado":"Conforme a su artículo 2, las disposiciones del TREBEP no se aplican directamente al personal funcionario al servicio de:","opciones":["La Administración General del Estado.","Las Cortes Generales.","Las Administraciones de las Comunidades autónomas.","Las Universidades Públicas."],"bloque":"ambito","precepto":"Arts. 2.1 y 4.a del TREBEP","correcta":1,"justificaciones":["No. La Administración General del Estado es el primer supuesto del **art. 2.1.a**: el Estatuto se aplica directamente.","Es esta. El personal funcionario de las Cortes Generales está en el **art. 4.a**: solo se aplica directamente si su legislación específica lo dispone.","No. Las Administraciones de las comunidades autónomas están en el **art. 2.1.b**: aplicación directa.","No. Las Universidades Públicas están en el **art. 2.1.e**: aplicación directa."]},{"id":"au-01-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":12,"enunciado":"Señale la respuesta correcta. Las disposiciones del Estatuto Básico del Empleado Público se aplicarán directamente al personal funcionario al servicio de la Administración de Justicia:","opciones":["Solo cuando así lo disponga su legislación específica.","En todo caso.","En ningún caso.","Salvo cuando así lo disponga su legislación específica."],"bloque":"ambito","precepto":"Art. 4.c del TREBEP","correcta":0,"justificaciones":["Es esta. Jueces, Magistrados, Fiscales y demás personal funcionario al servicio de la Administración de Justicia están en el **art. 4.c**: el Estatuto solo se les aplica directamente cuando lo disponga su legislación específica.","No. “En todo caso” contradice el **art. 4**, que condiciona la aplicación a lo que diga su legislación específica.","No. No es “en ningún caso”: si su legislación específica lo dispone, se aplica.","No. No se aplica salvo cuando lo disponga su legislación, sino al revés: solo se aplica cuando lo disponga."]},{"id":"au-01-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":13,"enunciado":"Conforme al artículo 5 del TREBEP, ¿por que normativa se rige el personal funcionario de Correos y Telégrafos?","opciones":["Por lo dispuesto en este Estatuto y supletoriamente por sus normas específicas.","Por sus normas específicas y supletoriamente por lo dispuesto en este Estatuto.","Por la legislación laboral y demás normas convencionalmente aplicables.","Por sus normas específicas, exclusivamente."],"bloque":"ambito","precepto":"Art. 5 del TREBEP","correcta":1,"justificaciones":["No. Has invertido el orden. El Estatuto es supletorio, no la norma principal.","Es esta. El **art. 5** dice que el personal funcionario de Correos y Telégrafos se rige por sus normas específicas y supletoriamente por el Estatuto.","No. La legislación laboral es para su personal laboral, no para el funcionario.","No. No es “exclusivamente” por sus normas específicas: el Estatuto se aplica de forma supletoria."]},{"id":"au-01-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":14,"enunciado":"En materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica y lactancia, el personal laboral al servicio de las Administraciones públicas se rige por:","opciones":["La legislación laboral y por las demás normas convencionalmente aplicables.","Lo previsto en el Estatuto Básico del Empleado Público.","Las previsiones del texto refundido de la Ley del Estatuto de los Trabajadores.","Lo previsto en el convenio colectivo que le resulte de aplicación, exclusivamente."],"bloque":"ambito","precepto":"Art. 7 del TREBEP","correcta":1,"justificaciones":["No. La legislación laboral rige al personal laboral con carácter general, pero en estos permisos el **art. 7** manda aplicar el Estatuto.","Es esta. Desde el Real Decreto-ley 9/2025, el **art. 7** dice que en materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica, lactancia y parental, el personal laboral se rige por el Estatuto.","No. El **art. 7** dice expresamente que no se le aplican las previsiones del Estatuto de los Trabajadores sobre las suspensiones de contrato por esos supuestos.","No. No es “exclusivamente” el convenio: manda el Estatuto Básico para esos permisos."]},{"id":"au-01-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":15,"enunciado":"Según el artículo 6 del TREBEP, en desarrollo de este Estatuto aprobarán, en el ámbito de sus competencias, leyes reguladoras de la Función Pública:","opciones":["Las Cortes Generales y las asambleas legislativas de las comunidades autónomas.","Las Cortes Generales, las asambleas legislativas de las comunidades autónomas y las entidades locales.","Las Cortes Generales, únicamente.","El TREBEP no precisa de legislación que lo desarrolle."],"bloque":"ambito","precepto":"Art. 6 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 6** dice que las Cortes Generales y las asambleas legislativas de las comunidades autónomas aprobarán, en el ámbito de sus competencias, las leyes de Función Pública.","No. Las entidades locales no aprueban leyes. El **art. 6** solo habla de las Cortes Generales y de las asambleas autonómicas.","No. No son “únicamente” las Cortes: también las asambleas legislativas de las comunidades autónomas.","No. El Estatuto sí necesita leyes de desarrollo, como dice su **art. 6**."]},{"id":"au-02-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":1,"enunciado":"Conforme al artículo 8.2 del TREBEP, los empleados públicos se clasifican en:","opciones":["Funcionarios de carrera, funcionarios interinos, personal laboral, personal eventual y personal estatutario.","Funcionarios de carrera, funcionarios interinos y personal estatutario.","Funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual.","Funcionarios de carrera, personal laboral y personal estatutario."],"bloque":"clases","precepto":"Art. 8.2 del TREBEP","correcta":2,"justificaciones":["No. El personal estatutario no es una clase del art. 8.2. El Estatuto lo trata aparte (art. 2.3).","No. Faltan el personal laboral y el eventual, y sobra el personal estatutario.","Es esta. El **art. 8.2** clasifica a los empleados públicos en funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual.","No. Faltan los interinos y los eventuales, y sobra el estatutario."]},{"id":"au-02-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":2,"enunciado":"Según el artículo 9.2 del TREBEP, el ejercicio de funciones que impliquen participación directa o indirecta en el ejercicio de las potestades públicas de las administraciones públicas corresponde:","opciones":["A todos los empleados públicos.","A todos los empleados públicos, excepto al personal con vinculación de carácter temporal.","A los funcionarios públicos, exclusivamente.","A los funcionarios públicos y al personal laboral."],"bloque":"clases","precepto":"Art. 9.2 del TREBEP","correcta":2,"justificaciones":["No. No todos los empleados públicos pueden ejercer potestades públicas.","No. El personal temporal no es el criterio. Lo es la condición de funcionario.","Es esta. El **art. 9.2** reserva exclusivamente a los funcionarios públicos las funciones de participación directa o indirecta en el ejercicio de potestades públicas.","No. El personal laboral no puede ejercer esas funciones (art. 9.2, y art. 11.2 que lo recuerda)."]},{"id":"au-02-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":3,"enunciado":"Conforme al artículo 10 del TREBEP, podrá nombrarse personal interino para la ejecución de programas de carácter temporal, que no podrán tener una duración superior a:","opciones":["Dos años, ampliable hasta doce meses más por las leyes de función pública que se dicten en desarrollo del Estatuto.","Tres años, ampliable hasta seis meses más por las leyes de función pública que se dicten en desarrollo del Estatuto.","Tres años, ampliable hasta doce meses más por las leyes de función pública que se dicten en desarrollo del Estatuto.","Dos años, ampliable hasta seis meses más por las leyes de función pública que se dicten en desarrollo del Estatuto."],"bloque":"clases","precepto":"Art. 10.1.c del TREBEP","correcta":2,"justificaciones":["No. El plazo es de tres años, no de dos.","No. La ampliación es de doce meses, no de seis.","Es esta. El **art. 10.1.c** dice que los programas temporales no pueden durar más de tres años, ampliable hasta doce meses más.","No. Ni dos años ni seis meses: son tres años y doce meses."]},{"id":"au-02-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":4,"enunciado":"A los funcionarios interinos les será aplicable, en cuanto sea adecuado a su naturaleza, el régimen general de:","opciones":["El personal laboral.","El personal eventual.","Los funcionarios en prácticas.","Los funcionarios de carrera."],"bloque":"clases","precepto":"Art. 10.5 del TREBEP","correcta":3,"justificaciones":["No. El personal laboral se rige por la legislación laboral, no es el régimen supletorio de los interinos.","No. El personal eventual tiene su propio régimen (art. 12).","No. Los funcionarios en prácticas no son el régimen de referencia de los interinos.","Es esta. El **art. 10.5** dice que se les aplica el régimen general de los funcionarios de carrera, en cuanto sea adecuado a su naturaleza temporal."]},{"id":"au-02-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":5,"enunciado":"Conforme al artículo 13 del TREBEP, cuando reúna la condición de personal laboral, el personal directivo:","opciones":["Estará sometido al régimen general de los funcionarios de carrera.","Estará sometido al régimen general del personal laboral.","Estará sometido a la relación laboral de carácter especial de alta dirección.","Estará sometido al régimen general del personal eventual."],"bloque":"clases","precepto":"Art. 13.4 del TREBEP","correcta":2,"justificaciones":["No. Cuando el directivo es personal laboral no se le aplica el régimen de los funcionarios.","No. No es el régimen general del personal laboral, sino uno especial.","Es esta. El **art. 13.4** dice que, cuando reúna la condición de personal laboral, estará sometido a la relación laboral de carácter especial de alta dirección.","No. El personal eventual es otra clase de empleado público."]},{"id":"au-02-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":6,"enunciado":"Señale la respuesta correcta en relación con el personal directivo, conforme a lo previsto en el artículo 13 del TREBEP:","opciones":["Su designación no precisará de publicidad ni concurrencia.","No estará sujeto a evaluación, ni responsabilidad por su gestión.","La determinación de sus condiciones de empleo no tendrá la consideración de materia objeto de negociación colectiva.","Estará sometido, en todo caso, a una relación laboral de carácter especial de alta dirección."],"bloque":"clases","precepto":"Art. 13 del TREBEP","correcta":2,"justificaciones":["No. Su designación atiende a mérito, capacidad e idoneidad y debe garantizar publicidad y concurrencia (**art. 13.2**).","No. Está sujeto a evaluación y responde por su gestión (**art. 13.3**).","Es esta. El **art. 13.4** dice que la determinación de sus condiciones de empleo no es materia de negociación colectiva.","No. Solo se le aplica la relación laboral de alta dirección cuando reúna la condición de personal laboral, no “en todo caso”."]},{"id":"au-02-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":7,"enunciado":"En relación con el personal directivo, el TREBEP determina que en su designación se atenderá a los principios de:","opciones":["Mérito y capacidad.","Mérito, capacidad y profesionalidad.","Profesionalidad, igualdad y mérito.","Capacidad e idoneidad."],"bloque":"clases","precepto":"Art. 13.2 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 13.2** dice que su designación atenderá a principios de mérito y capacidad y a criterios de idoneidad.","No. La profesionalidad no aparece como principio en el art. 13.2.","No. Ni profesionalidad ni igualdad aparecen en ese apartado.","No. Falta el mérito y la idoneidad es un criterio, no un principio."]},{"id":"au-02-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":8,"enunciado":"De conformidad con el TREBEP, el personal directivo estará sujeto a evaluación con arreglo a los criterios de:","opciones":["Eficacia y eficiencia.","Mérito y capacidad.","Idoneidad.","Publicidad y concurrencia."],"bloque":"clases","precepto":"Art. 13.3 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 13.3** dice que estará sujeto a evaluación con arreglo a los criterios de eficacia y eficiencia, responsabilidad por su gestión y control de resultados.","No. Mérito y capacidad son los principios de su designación, no de su evaluación.","No. La idoneidad es un criterio de designación, no de evaluación.","No. Publicidad y concurrencia son las garantías del procedimiento de designación."]},{"id":"au-02-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":9,"enunciado":"El personal que, en virtud de nombramiento y con carácter no permanente, solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, siendo retribuido con cargo a créditos consignados para este fin se denomina:","opciones":["Personal funcionario interino.","Personal directivo profesional.","Personal eventual.","Personal laboral."],"bloque":"clases","precepto":"Art. 12.1 del TREBEP","correcta":2,"justificaciones":["No. El interino sustituye o desempeña funciones propias de funcionarios de carrera.","No. El directivo desarrolla funciones directivas profesionales.","Es esta. El **art. 12.1** define al personal eventual así: nombramiento, carácter no permanente, funciones de confianza o asesoramiento especial y retribución con cargo a créditos presupuestarios para ese fin.","No. El personal laboral lo es por contrato de trabajo, no por nombramiento."]},{"id":"au-02-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":10,"enunciado":"Conforme al TREBEP, no tendrán la consideración de materia objeto de negociación colectiva a los efectos de este Estatuto, la determinación de las condiciones de empleo de:","opciones":["El personal eventual.","El personal laboral.","El personal directivo profesional.","a) y c) son correctas."],"bloque":"clases","precepto":"Art. 13.4 del TREBEP","correcta":2,"justificaciones":["No. Para el personal eventual el art. 13.4 no dice nada.","No. Las condiciones del personal laboral sí se negocian.","Es esta. El **art. 13.4** excluye de la negociación colectiva la determinación de las condiciones de empleo del personal directivo.","No. Solo es correcta la c), no la a): el personal eventual no está en esa exclusión."]},{"id":"au-02-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":11,"enunciado":"Señale la respuesta incorrecta en relación con el personal eventual, conforme a lo dispuesto en el artículo 12 del TREBEP:","opciones":["Sus condiciones retributivas no serán públicas.","La condición de personal eventual no podrá constituir mérito para el acceso a la Función Pública o para la promoción interna.","Su nombramiento y cese serán libres.","El número máximo se establecerá por los respectivos órganos de gobierno."],"bloque":"clases","precepto":"Art. 12 del TREBEP","correcta":0,"justificaciones":["Esta es la falsa, y por eso es la que hay que marcar. El **art. 12.2** dice que el número máximo y las condiciones retributivas serán públicas.","Es verdadera, así que no se marca. Es el **art. 12.4**.","Es verdadera, así que no se marca. Lo dice el **art. 12.3**.","Es verdadera, así que no se marca. El número máximo lo fijan los respectivos órganos de gobierno (**art. 12.2**)."]},{"id":"au-02-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":12,"enunciado":"El personal laboral al servicio de las Administraciones Públicas:","opciones":["En función de la duración del contrato podrá ser fijo o temporal.","En función de la duración del contrato podrá ser fijo, por tiempo indefinido o temporal.","No podrá ser temporal en ningún caso.","Tendrá siempre la consideración de personal fijo."],"bloque":"clases","precepto":"Art. 11.1 del TREBEP","correcta":1,"justificaciones":["No. Falta la categoría “por tiempo indefinido”: son tres, no dos.","Es esta. El **art. 11.1** dice que, en función de la duración del contrato, el personal laboral puede ser fijo, por tiempo indefinido o temporal.","No. Sí puede ser temporal.","No. No es siempre fijo: puede ser fijo, indefinido o temporal."]},{"id":"au-02-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":13,"enunciado":"Señale la respuesta incorrecta respecto al personal eventual al servicio de la Administración Pública:","opciones":["Su nombramiento y cese serán libres.","Le será aplicable, en lo que sea adecuado a la naturaleza de su condición, el régimen general de los funcionarios de carrera.","La condición de personal eventual podrá constituir mérito para el acceso a la Función Pública.","Cesará, en todo caso, cuando cese la autoridad a la que se preste la función de confianza o asesoramiento."],"bloque":"clases","precepto":"Art. 12 del TREBEP","correcta":2,"justificaciones":["Es verdadera, así que no se marca. **Art. 12.3**.","Es verdadera, así que no se marca. **Art. 12.5**.","Esta es la falsa, y por eso es la que hay que marcar. El **art. 12.4** dice justo lo contrario: no podrá constituir mérito para el acceso ni para la promoción interna.","Es verdadera, así que no se marca. **Art. 12.3**."]},{"id":"au-02-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":14,"enunciado":"De acuerdo con el TREBEP, ¿cuál es el número máximo de personal eventual de que podrán disponer los órganos de gobierno de las Administraciones Públicas?","opciones":["El que se establezca por sus respectivos órganos de gobierno.","El que se establezca en la Ley de Presupuestos Generales del Estado.","Un número que no supere el diez por ciento del total de la plantilla.","No se establecerá número máximo, pero sí un límite de créditos presupuestarios para la retribución de este personal."],"bloque":"clases","precepto":"Art. 12.2 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 12.2** dice que el número máximo se establecerá por los respectivos órganos de gobierno.","No. No lo fija la Ley de Presupuestos Generales del Estado.","No. El Estatuto no pone un tope del diez por ciento.","No. Sí hay un máximo: lo fijan los órganos de gobierno. Los créditos presupuestarios son el origen de la retribución, no el límite del número."]},{"id":"au-02-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":15,"enunciado":"De acuerdo con el TREBEP, señale la respuesta correcta relación con los funcionarios interinos:","opciones":["Les será aplicable, en cuanto sea adecuado a la naturaleza de su condición, el régimen general de los funcionarios de carrera.","Son nombrados por razones de necesidad, no así de urgencia.","Sus funciones son diferentes a las que desempeña un funcionario de carrera.","Dada la necesidad, su selección se realizará por procedimientos ágiles sin sujeción a los principios de mérito y publicidad."],"bloque":"clases","precepto":"Art. 10.5 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 10.5** les aplica el régimen general de los funcionarios de carrera en cuanto sea adecuado a su naturaleza temporal.","No. Se nombran por razones de necesidad y urgencia (**art. 10.1**).","No. Desempeñan funciones propias de funcionarios de carrera (**art. 10.1**).","No. Su selección sí respeta los principios de igualdad, mérito, capacidad, publicidad y celeridad (**art. 10.2**)."]},{"id":"au-02-016","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":16,"enunciado":"Podrán nombrarse funcionarios interinos por exceso o acumulación de tareas:","opciones":["Por plazo máximo de doce meses, dentro de un periodo de dieciocho meses.","Por plazo máximo de nueve meses, dentro de un periodo de dieciocho meses.","Por plazo máximo de seis meses, dentro de un periodo de doce meses.","Por plazo máximo de doce meses, dentro de un periodo de veinticuatro meses."],"bloque":"clases","precepto":"Art. 10.1.d del TREBEP","correcta":1,"justificaciones":["No. No son doce meses dentro de dieciocho.","Es esta. El **art. 10.1.d** vigente dice por plazo máximo de nueve meses, dentro de un periodo de dieciocho meses.","No. Seis meses dentro de doce era la redacción anterior. Hoy es nueve dentro de dieciocho.","No. No son doce meses dentro de veinticuatro."],"ojo":"La redacción antigua del art. 10.1.d decía seis meses dentro de doce. Se cambió a nueve dentro de dieciocho.","revisar":"Respondida con el texto vigente. Si el profesor corrige con la redacción antigua (seis y doce), la clave sería la opción 3."},{"id":"au-02-017","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":17,"enunciado":"Según lo establecido en el artículo 8 del TREBEP, son empleados públicos quienes desempeñan:","opciones":["Funciones retribuidas en cualquier organización o entidad participada por una Administración Pública.","Funciones retribuidas o no, en las Administraciones Publicas, al servicio de los intereses generales.","Funciones retribuidas en las Administraciones Públicas al servicio de los intereses generales.","Funciones, retribuidas o no, en las Administraciones General del Estado, al servicio de los intereses generales."],"bloque":"clases","precepto":"Art. 8.1 del TREBEP","correcta":2,"justificaciones":["No. Son las funciones en las Administraciones Públicas, no en cualquier entidad participada.","No. Las funciones han de ser retribuidas: “retribuidas o no” es falso.","Es esta. El **art. 8.1** dice: quienes desempeñan funciones retribuidas en las Administraciones Públicas al servicio de los intereses generales.","No. No solo la Administración General del Estado, y además las funciones son retribuidas."]},{"id":"au-02-018","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":18,"enunciado":"Según el Texto Refundido de la Ley del Estatuto Básico del Empleado Público, son funcionarios de carrera quienes, en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria:","opciones":["Regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente.","Regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter no permanente.","Regulada por el Derecho Administrativo para el desempeño de servicios profesionales no retribuidos de carácter permanente.","Regulada por el Derecho laboral para el desempeño de servicios profesionales retribuidos de carácter permanente."],"bloque":"clases","precepto":"Art. 9.1 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 9.1** habla de relación estatutaria regulada por el Derecho Administrativo para servicios profesionales retribuidos de carácter permanente.","No. El carácter es permanente, no “no permanente”.","No. Los servicios son retribuidos.","No. La relación es estatutaria, regulada por el Derecho Administrativo, no por el laboral."]},{"id":"au-02-019","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":19,"enunciado":"Conforme al TREBEP, la selección de funcionarios interinos habrá de realizarse mediante procedimientos ágiles que respetarán, en todo caso, los principios de:","opciones":["Proporcionalidad, transparencia, publicidad e integridad.","Igualdad, capacidad, seguridad jurídica y necesidad.","Igualdad, mérito, capacidad, publicidad y celeridad.","Igualdad, mérito, eficacia y eficiencia."],"bloque":"clases","precepto":"Art. 10.2 del TREBEP","correcta":2,"justificaciones":["No. Esos no son los principios del art. 10.2.","No. Capacidad sí, pero seguridad jurídica y necesidad no son los principios.","Es esta. El **art. 10.2** dice que los procedimientos serán públicos y se rigen por los principios de igualdad, mérito, capacidad, publicidad y celeridad.","No. Eficacia y eficiencia son los criterios de evaluación del personal directivo, no de selección de interinos."]},{"id":"au-02-020","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":20,"enunciado":"Señale la respuesta correcta, de conformidad con lo establecido en el TREBEP:","opciones":["Son funcionarios interinos los nombrados como tales para desempeñar funciones propias del personal eventual.","El personal eventual cesará, en todo caso, cuando se produzca el cese de la autoridad que lo nombró.","Las funciones que impliquen ejercicio de potestades públicas corresponden exclusivamente a los funcionarios de carrera.","En función de la duración del contrato, el personal laboral podrá ser fijo, por tiempo indefinido o temporal."],"bloque":"clases","precepto":"Arts. 9, 11 y 12 del TREBEP","correcta":3,"justificaciones":["No. Los interinos desempeñan funciones propias de funcionarios de carrera, no del personal eventual.","No. El **art. 12.3** dice que cesa cuando se produzca el cese de la autoridad “a la que se preste la función de confianza o asesoramiento”, no de la que lo nombró.","No. Las funciones con potestades públicas son de los funcionarios públicos (**art. 9.2**), no solo de los de carrera.","Es esta. Es el **art. 11.1**: fijo, por tiempo indefinido o temporal."],"revisar":"La opción 1 (eventual) se parece mucho al art. 12.3. Le he dado por falsa por decir “que lo nombró” en lugar de “a la que se preste la función”. Si el profesor la da por buena, hay dos correctas."},{"id":"au-03-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":1,"enunciado":"El artículo 14 del TREBEP reconoce el derecho a la inamovilidad en la condición de una clase de personal. Señale cuál:","opciones":["Funcionarios de carrera.","Funcionarios de carrera y personal laboral fijo.","Personal laboral fijo.","No se reconoce el derecho a la inamovilidad de ninguna clase de personal."],"bloque":"derechos","precepto":"Art. 14.a del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 14.a** reconoce la inamovilidad en la condición de funcionario de carrera.","No. El personal laboral no tiene ese derecho en el Estatuto.","No. El personal laboral fijo no tiene reconocida la inamovilidad.","No. Sí se reconoce, a los funcionarios de carrera."]},{"id":"au-03-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":2,"enunciado":"Conforme al artículo 15 del TREBEP, los empleados públicos tienen, entre otros, el siguiente derecho individual que se ejerce de forma colectiva:","opciones":["A la inamovilidad en la condición de funcionario de carrera.","Al ejercicio de la huelga, con la garantía del mantenimiento de los servicios esenciales de la comunidad.","A la libre asociación profesional.","A la jubilación."],"bloque":"derechos","precepto":"Art. 15.c del TREBEP","correcta":1,"justificaciones":["No. La inamovilidad es un derecho individual de ejercicio individual (**art. 14.a**).","Es esta. El **art. 15.c** incluye el ejercicio de la huelga, con la garantía de los servicios esenciales, entre los derechos individuales que se ejercen colectivamente.","No. La libre asociación profesional está en el **art. 14.p**, entre los derechos individuales.","No. La jubilación está en el **art. 14.n**."]},{"id":"au-03-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":3,"enunciado":"¿Cuál de los siguientes derechos de los empleados públicos es un derecho individual de ejercicio colectivo de acuerdo con el Texto Refundido de la Ley del Estatuto Básico del Empleado Público?","opciones":["Derecho a la libre asociación profesional.","Derecho a la libertad de expresión.","Derecho de reunión.","Derecho a recibir protección eficaz en materia de seguridad y salud en el trabajo."],"bloque":"derechos","precepto":"Art. 15.e del TREBEP","correcta":2,"justificaciones":["No. La libre asociación profesional es un derecho individual (**art. 14.p**).","No. La libertad de expresión es individual (**art. 14.k**).","Es esta. El derecho de reunión es el **art. 15.e**, de ejercicio colectivo.","No. La seguridad y salud es un derecho individual (**art. 14.l**)."]},{"id":"au-03-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":4,"enunciado":"Según el artículo 15 del TREBEP, ¿cuál de los siguientes NO es un derecho individual que se ejerce de forma colectiva?","opciones":["La libre asociación profesional.","El de reunión.","La libertad sindical.","El ejercicio de la huelga."],"bloque":"derechos","precepto":"Arts. 14.p y 15 del TREBEP","correcta":0,"justificaciones":["Esta es la que NO es de ejercicio colectivo, y por eso es la que hay que marcar. La libre asociación profesional está en el **art. 14.p**, entre los individuales.","Es de ejercicio colectivo (**art. 15.e**), así que no se marca.","Es de ejercicio colectivo (**art. 15.a**), así que no se marca.","Es de ejercicio colectivo (**art. 15.c**), así que no se marca."]},{"id":"au-03-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":5,"enunciado":"Según lo dispuesto en el artículo 17 del TREBEP, la carrera horizontal de los funcionarios de carrera se articula:","opciones":["Sobre un sistema de grupos, grados y categorías.","Sobre un sistema de grupos, grados y niveles.","Sobre un sistema de grados, categorías o escalones de ascenso.","Sobre un sistema de grupos, niveles o escalones de ascenso."],"bloque":"derechos","precepto":"Art. 17.a del TREBEP","correcta":2,"justificaciones":["No. En la carrera horizontal no hay grupos: son grados, categorías o escalones.","No. Tampoco “grupos” ni “niveles”.","Es esta. El **art. 17.a** habla de un sistema de grados, categorías o escalones de ascenso, fijándose la remuneración a cada uno.","No. Ni grupos ni niveles: son grados, categorías o escalones."]},{"id":"au-03-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":6,"enunciado":"De acuerdo con el artículo 16.3.a) del TREBEP, la carrera horizontal de los funcionarios públicos consiste en:","opciones":["El ascenso desde un cuerpo o escala de un Subgrupo, o Grupo de clasificación profesional, a otro superior.","El acceso a cuerpos o escalas del mismo Subgrupo profesional.","El ascenso en la estructura de puestos de trabajo por los procedimientos de provisión establecidos.","La progresión de grado, categoría, escalón u otros conceptos análogos, sin necesidad de cambiar de puesto de trabajo."],"bloque":"derechos","precepto":"Art. 16.3.a del TREBEP","correcta":3,"justificaciones":["No. Eso es la promoción interna vertical (**art. 16.3.c**).","No. Eso es la promoción interna horizontal (**art. 16.3.d**).","No. Eso es la carrera vertical (**art. 16.3.b**).","Es esta. La carrera horizontal es la progresión de grado, categoría, escalón u otros conceptos análogos sin cambiar de puesto (**art. 16.3.a**)."]},{"id":"au-03-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":7,"enunciado":"El TREBEP determina las modalidades que podrán establecerse para garantizar la carrera profesional de los funcionarios, entre las que se encuentra la “carrera vertical”, que consiste en:","opciones":["La progresión sin necesidad de cambiar de puesto de trabajo.","El acceso a cuerpos o escalas del mismo subgrupo profesional.","El ascenso en la estructura de puestos de trabajo mediante los procedimientos de provisión.","El ascenso desde un cuerpo o escala de un Subgrupo, o un grupo, a otro superior."],"bloque":"derechos","precepto":"Art. 16.3.b del TREBEP","correcta":2,"justificaciones":["No. Eso es la carrera horizontal.","No. Eso es la promoción interna horizontal.","Es esta. La carrera vertical es el ascenso en la estructura de puestos de trabajo por los procedimientos de provisión (**art. 16.3.b**).","No. Eso es la promoción interna vertical."]},{"id":"au-03-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":8,"enunciado":"De acuerdo con el TREBEP, ¿a qué elementos pueden alcanzar los efectos de la evaluación del desempeño?","opciones":["Carrera, formación, situaciones administrativas y retribuciones complementarias.","Carrera, inamovilidad en la condición de funcionario, situaciones administrativas y retribuciones básicas.","Carrera, formación, provisión de puestos de trabajo y retribuciones complementarias.","Carrera, formación, provisión de puestos de trabajo y retribuciones tanto básicas como complementarias."],"bloque":"derechos","precepto":"Art. 20.3 del TREBEP","correcta":2,"justificaciones":["No. Las situaciones administrativas no son un efecto de la evaluación.","No. Ni la inamovilidad ni las retribuciones básicas dependen de la evaluación.","Es esta. El **art. 20.3** dice: carrera profesional horizontal, formación, provisión de puestos de trabajo y retribuciones complementarias.","No. Las retribuciones básicas no están afectadas, solo las complementarias."]},{"id":"au-03-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":9,"enunciado":"En el Real Decreto Legislativo 5/2015, por el que se aprueba el TREBEP, la carrera profesional se define como:","opciones":["La progresión de grado, categoría, escalón u otros conceptos análogos, sin necesidad de cambiar de puesto de trabajo.","El ascenso en la estructura de puestos de trabajo por los procedimientos de provisión establecidos legalmente.","El acceso a cuerpos o escalas del mismo Subgrupo profesional.","El conjunto ordenado de oportunidades de ascenso y expectativas de progreso profesional."],"bloque":"derechos","precepto":"Art. 16.2 del TREBEP","correcta":3,"justificaciones":["No. Eso es la carrera horizontal, solo una modalidad.","No. Eso es la carrera vertical, otra modalidad.","No. Eso es la promoción interna horizontal.","Es esta. El **art. 16.2** define la carrera profesional como el conjunto ordenado de oportunidades de ascenso y expectativas de progreso profesional conforme a igualdad, mérito y capacidad."]},{"id":"au-03-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":10,"enunciado":"Señale la respuesta incorrecta en virtud de lo dispuesto en el TREBEP sobre las reglas que se aplican a la carrera horizontal de los funcionarios de carrera:","opciones":["Los ascensos serán consecutivos, en todo caso.","Podrán valorarse méritos y aptitudes por razón de la especificidad de la función desarrollada y la experiencia adquirida.","Se deberá valorar la evaluación del desempeño.","Se articulará un sistema de grados, categorías o escalones de ascenso fijándose la remuneración a cada uno de ellos."],"bloque":"derechos","precepto":"Art. 17 del TREBEP","correcta":0,"justificaciones":["Esta es la falsa, y por eso es la que hay que marcar. El **art. 17.a** dice que los ascensos serán consecutivos “con carácter general”, salvo excepciones. No “en todo caso”.","Es verdadera, así que no se marca. **Art. 17.b**.","Es verdadera, así que no se marca. **Art. 17.b**.","Es verdadera, así que no se marca. **Art. 17.a**."]},{"id":"au-03-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":11,"enunciado":"Señale la respuesta correcta según el TREBEP:","opciones":["El personal laboral tendrá derecho a la promoción profesional","La aplicación de la promoción interna requerirá la aprobación de sistemas objetivos que permitan evaluar el desempeño.","Los funcionarios interinos tendrán derecho a la promoción profesional.","En la carrera horizontal de los funcionarios de carrera los ascensos serán, sin excepciones, consecutivos."],"bloque":"derechos","precepto":"Art. 19.1 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 19.1** dice que el personal laboral tendrá derecho a la promoción profesional.","No. Los sistemas objetivos de evaluación del desempeño los exige el **art. 20.5** para la carrera horizontal, no para la promoción interna.","No. El derecho a la promoción profesional es de los funcionarios de carrera (**art. 16.1**) y del personal laboral (**art. 19**).","No. Es “con carácter general”, no “sin excepciones” (**art. 17.a**)."]},{"id":"au-03-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":12,"enunciado":"De acuerdo con el TREBEP, ¿cómo se denomina el procedimiento mediante el cual se mide y valora la conducta profesional y el rendimiento o el logro de resultados?","opciones":["Análisis del rendimiento.","Valoración profesional.","Evaluación del desempeño.","Estudio de rendimiento objetivo."],"bloque":"derechos","precepto":"Art. 20.1 del TREBEP","correcta":2,"justificaciones":["No. No es un nombre que use el Estatuto.","No. No es un nombre que use el Estatuto.","Es esta. El **art. 20.1** define la evaluación del desempeño como el procedimiento que mide y valora la conducta profesional y el rendimiento o logro de resultados.","No. No es un nombre que use el Estatuto."]},{"id":"au-03-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":13,"enunciado":"Señale la respuesta INCORRECTA. Según el TREBEP, las leyes de Función Pública que se dicten en desarrollo de este Estatuto regularán la carrera profesional aplicable en cada ámbito que podrá consistir, entre otras, en la aplicación aislada o simultánea de alguna o algunas de las siguientes modalidades:","opciones":["Promoción interna vertical.","Carrera vertical.","Carrera horizontal.","Evaluación del desempeño."],"bloque":"derechos","precepto":"Art. 16.3 del TREBEP","correcta":3,"justificaciones":["Es una modalidad (**art. 16.3.c**), así que no se marca.","Es una modalidad (**art. 16.3.b**), así que no se marca.","Es una modalidad (**art. 16.3.a**), así que no se marca.","Esta es la falsa, y por eso es la que hay que marcar. La evaluación del desempeño está en el **art. 20** y no es una modalidad de carrera profesional."]},{"id":"au-03-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":14,"enunciado":"El artículo 18 del TREBEP determina una serie de requisitos necesarios para hacer efectivo el derecho a la promoción interna de los funcionarios de carrera. De los siguientes, ¿cuál no es uno de ellos?","opciones":["Poseer los requisitos exigidos para el ingreso en el Cuerpo al que se promociona.","Participar en los correspondientes cursos de preparación para la superación de los procesos selectivos de promoción interna.","Tener una antigüedad de, al menos, dos años de servicio activo en el inferior Subgrupo, o Grupo de clasificación profesional.","Superar las correspondientes pruebas selectivas."],"bloque":"derechos","precepto":"Art. 18.2 del TREBEP","correcta":1,"justificaciones":["Es requisito, así que no es la respuesta. **Art. 18.2**.","Es esta. Participar en cursos de preparación no figura entre los requisitos del **art. 18.2**.","Es requisito, así que no es la respuesta. Dos años de antigüedad en el Subgrupo inferior (**art. 18.2**).","Es requisito, así que no es la respuesta. Superar las pruebas selectivas (**art. 18.2**)."]},{"id":"au-03-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":15,"enunciado":"Señale la respuesta correcta en relación con la evaluación del desempeño a que se refiere el artículo 20 del TREBEP:","opciones":["Las Administraciones Públicas determinarán sus efectos en la percepción de las retribuciones básicas.","La continuidad en un puesto de trabajo obtenido por promoción interna quedará vinculada a la evaluación del desempeño.","La aplicación de la carrera horizontal requerirá la aprobación previa de sistemas objetivos de evaluación del desempeño.","Consiste en la progresión de grado, categoría, escalón o conceptos análogos, sin necesidad de cambiar de puesto de trabajo."],"bloque":"derechos","precepto":"Art. 20.5 del TREBEP","correcta":2,"justificaciones":["No. Afecta a las retribuciones complementarias, no a las básicas (**art. 20.3**).","No. La continuidad vinculada a la evaluación es en un puesto obtenido por concurso, no por promoción interna (**art. 20.4**).","Es esta. El **art. 20.5** exige la aprobación previa de sistemas objetivos de evaluación del desempeño para aplicar la carrera horizontal.","No. Eso describe la carrera horizontal, no la evaluación del desempeño."]},{"id":"au-04-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":1,"enunciado":"El artículo 23 del TREBEP establece que las retribuciones básicas de los funcionarios se fijan:","opciones":["Por la Ley de Presupuestos Generales del Estado.","Por los respectivos órganos de Gobierno de cada Administración Pública.","Por Real Decreto del Consejo de Ministros.","Por las leyes de Función Pública que se dicten en desarrollo del presente Estatuto."],"bloque":"retribuciones","precepto":"Art. 23 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 23** dice que las retribuciones básicas se fijan en la Ley de Presupuestos Generales del Estado.","No. Los órganos de gobierno de cada Administración no fijan las básicas. Eso es para las complementarias a través de sus leyes (**art. 24**).","No. No se fijan por Real Decreto, sino en la Ley de Presupuestos Generales del Estado.","No. Las leyes de Función Pública de cada Administración regulan las complementarias (**art. 24**), no las básicas."]},{"id":"au-04-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":2,"enunciado":"De acuerdo con el Real Decreto legislativo 5/2015, de 30 de octubre, por el que se aprueba el TREBEP, las retribuciones básicas que se fijan en la Ley de Presupuestos Generales del Estado, estarán integradas por:","opciones":["El sueldo, los trienios y el complemento de destino.","El sueldo, los trienios, el complemento de destino y el complemento específico.","Única y exclusivamente por el sueldo y los trienios.","El sueldo, el complemento de destino y el complemento específico."],"bloque":"retribuciones","precepto":"Art. 23 del TREBEP","correcta":2,"justificaciones":["No. El complemento de destino es una retribución complementaria, no básica.","No. Ni el complemento de destino ni el específico son básicas.","Es esta. El **art. 23** dice que las básicas están integradas única y exclusivamente por el sueldo y los trienios.","No. Los complementos de destino y específico son retribuciones complementarias."]},{"id":"au-04-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":3,"enunciado":"Señale la opción incorrecta. Las retribuciones complementarias se establecerán atendiendo a los siguientes factores:","opciones":["El grado de interés, iniciativa o esfuerzo con que el funcionario desempeña su trabajo y el rendimiento o resultados obtenidos.","La progresión alcanzada por el funcionario dentro del sistema de carrera administrativa.","Los servicios extraordinarios prestados dentro de la jornada normal de trabajo.","La especial dificultad técnica, responsabilidad, dedicación, incompatibilidad exigible para el desempeño de determinados puestos de trabajo o las condiciones en que se desarrolla el trabajo."],"bloque":"retribuciones","precepto":"Art. 24 del TREBEP","correcta":2,"justificaciones":["Es verdadera, así que no se marca. Es el factor del **art. 24.c**.","Es verdadera, así que no se marca. Es el factor del **art. 24.a**.","Esta es la falsa, y por eso es la que hay que marcar. El **art. 24.d** habla de servicios extraordinarios prestados “fuera” de la jornada normal, no dentro.","Es verdadera, así que no se marca. Es el factor del **art. 24.b**."]},{"id":"au-04-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":4,"enunciado":"Según el TREBEP, los servicios extraordinarios prestados fuera de la jornada normal de trabajo del personal funcionario, son un factor a tener en cuenta para determinar la cuantía y estructura de:","opciones":["Las retribuciones básicas.","Las retribuciones complementarias.","Las pagas extraordinarias.","Las indemnizaciones por razón del servicio."],"bloque":"retribuciones","precepto":"Art. 24.d del TREBEP","correcta":1,"justificaciones":["No. Las básicas son solo el sueldo y los trienios (**art. 23**).","Es esta. Los servicios extraordinarios fuera de la jornada son un factor de las retribuciones complementarias (**art. 24.d**).","No. Las pagas extraordinarias no se determinan por ese factor.","No. Las indemnizaciones por razón del servicio son otra cosa (**art. 28**)."]},{"id":"au-04-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":5,"enunciado":"Conforme al TREBEP, la cuantía y estructura de las retribuciones complementarias de los funcionarios se establecerán atendiendo, entre otros, a los siguientes factores. Señale la respuesta incorrecta:","opciones":["La progresión alcanzada por el funcionario dentro del sistema de carrera administrativa.","La antigüedad en la condición de funcionario público.","El grado de interés, iniciativa o esfuerzo con que el funcionario desempeña su trabajo y el rendimiento o resultados obtenidos.","Los servicios extraordinarios prestados fuera de la jornada normal de trabajo."],"bloque":"retribuciones","precepto":"Art. 24 del TREBEP","correcta":1,"justificaciones":["Es un factor del **art. 24.a**, así que no se marca.","Esta es la falsa, y por eso es la que hay que marcar. La antigüedad se retribuye con los trienios, que son retribución básica (**art. 23.b**), no complementaria.","Es un factor del **art. 24.c**, así que no se marca.","Es un factor del **art. 24.d**, así que no se marca."]},{"id":"au-04-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":6,"enunciado":"Según el artículo 29 del TREBEP, las cantidades destinadas por las Administraciones Públicas a financiar aportaciones a planes de pensiones, tendrán a todos los efectos la consideración de:","opciones":["Retribuciones básicas.","Retribuciones complementarias.","Retribuciones diferidas.","Pagos en especie."],"bloque":"retribuciones","precepto":"Art. 29 del TREBEP","correcta":2,"justificaciones":["No. No son retribuciones básicas.","No. Tampoco complementarias.","Es esta. El **art. 29** dice que tendrán a todos los efectos la consideración de retribución diferida.","No. No se llaman pagos en especie."]},{"id":"au-04-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":7,"enunciado":"Señale la respuesta correcta. El Estatuto Básico del Empleado Público establece en cuanto a los derechos retributivos que:","opciones":["Los funcionarios no podrán percibir indemnizaciones por razón del servicio.","Los funcionarios interinos solo percibirán las retribuciones básicas.","Quienes ejerciten el derecho de huelga no devengarán ni percibirán retribuciones.","La parte de jornada no realizada dará lugar a la deducción proporcional de haberes y tendrá carácter sancionador en todo caso."],"bloque":"retribuciones","precepto":"Arts. 25, 28 y 30 del TREBEP","correcta":2,"justificaciones":["No. Sí perciben indemnizaciones por razón del servicio (**art. 28**).","No. Los interinos perciben también las pagas extraordinarias y complementarias (**art. 25**).","Es esta. Según el **art. 30.2**, quienes ejercitan la huelga no devengan ni perciben retribuciones por el tiempo en esa situación.","No. La deducción de haberes por jornada no realizada no tiene carácter sancionador (**art. 30.1**)."]},{"id":"au-04-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":8,"enunciado":"Según el TREBEP, las retribuciones de los funcionarios en prácticas serán determinadas por cada Administración Pública y se corresponderán:","opciones":["Como máximo, a las del sueldo del Subgrupo o Grupo en que aspiren a ingresar.","Como mínimo, a las del sueldo del Subgrupo o Grupo en que aspiren a ingresar.","Como máximo, a las retribuciones básicas del Subgrupo o Grupo en que aspiren a ingresar.","Como mínimo, a las retribuciones básicas del Subgrupo o Grupo en que aspiren a ingresar."],"bloque":"retribuciones","precepto":"Art. 26 del TREBEP","correcta":1,"justificaciones":["No. Es “como mínimo”, no “como máximo”.","Es esta. El **art. 26** dice que, como mínimo, se corresponderán a las del sueldo del Subgrupo o Grupo en que aspiren a ingresar.","No. Es mínimo, y además habla del sueldo, no de las retribuciones básicas.","No. Habla del sueldo, no de las retribuciones básicas (que incluyen trienios)."]},{"id":"au-04-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":9,"enunciado":"Las retribuciones de los funcionarios de carrera se clasifican en:","opciones":["Básicas y complementarias.","Ordinarias y extraordinarias.","Extraordinarias y complementarias.","Básicas y globales."],"bloque":"retribuciones","precepto":"Art. 22.1 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 22.1** clasifica las retribuciones de los funcionarios de carrera en básicas y complementarias.","No. Ordinarias y extraordinarias no es la clasificación del Estatuto.","No. Las extraordinarias son las pagas, no una categoría de retribución.","No. No existen “retribuciones globales” en esa clasificación."]},{"id":"au-04-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":10,"enunciado":"Señale la respuesta correcta en relación con los trienios:","opciones":["Tendrán a todos los efectos la consideración de retribución complementaria.","Consisten en una cantidad, que será igual para cada Subgrupo o Grupo de clasificación profesional.","Tendrán a todos los efectos la consideración de retribución diferida.","Retribuyen la progresión alcanzada por el funcionario dentro del sistema de carrera administrativa."],"bloque":"retribuciones","precepto":"Art. 23.b del TREBEP","correcta":1,"justificaciones":["No. Los trienios son retribuciones básicas (**art. 23.b**).","Es esta. Los trienios son una cantidad igual para cada Subgrupo o Grupo por cada tres años de servicio (**art. 23.b**).","No. La retribución diferida son las aportaciones a planes de pensiones (**art. 29**).","No. Los trienios retribuyen la antigüedad. La progresión en la carrera se retribuye con complementarias (**art. 24.a**)."]},{"id":"au-04-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":11,"enunciado":"Señale la respuesta correcta en relación con los funcionarios públicos que ejerciten el derecho de huelga:","opciones":["La deducción de haberes que se efectúe tendrá, en todo caso, carácter sancionador.","Percibirán las retribuciones básicas y los trienios correspondientes al tiempo en que hayan permanecido en esa situación.","No devengarán ni percibirán las retribuciones correspondientes al tiempo en que hayan permanecido en esa situación.","Percibirán las retribuciones básicas correspondientes al tiempo en que hayan permanecido en esa situación."],"bloque":"retribuciones","precepto":"Art. 30.2 del TREBEP","correcta":2,"justificaciones":["No. El **art. 30.2** dice que la deducción no tiene carácter de sanción.","No. No perciben ni básicas ni trienios por ese tiempo.","Es esta. No devengarán ni percibirán las retribuciones correspondientes al tiempo en huelga (**art. 30.2**).","No. Tampoco perciben las básicas por ese tiempo."]},{"id":"au-04-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":12,"enunciado":"Según el TREBEP, las retribuciones básicas de los empleados públicos estarán integradas única y exclusivamente por:","opciones":["El sueldo y los trienios.","El sueldo, los trienios y las retribuciones específicas.","El sueldo y los complementos específicos.","El sueldo, los trienios y las pagas extraordinarias."],"bloque":"retribuciones","precepto":"Art. 23 del TREBEP","correcta":0,"justificaciones":["Es esta. Las básicas son única y exclusivamente el sueldo y los trienios (**art. 23**).","No. Las retribuciones específicas son complementarias.","No. El complemento específico es complementario.","No. Los componentes de las pagas extraordinarias están ya incluidos en sueldo y trienios (**art. 22.2**), no son un concepto aparte."]},{"id":"au-04-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":13,"enunciado":"Señale la respuesta incorrecta en relación con los funcionarios que ejerciten el derecho de huelga:","opciones":["Se les efectuará deducción de haberes, sin que ello conlleve el ejercicio de potestad sancionadora.","No percibirán las retribuciones correspondientes al tiempo en que hayan permanecido en esa situación.","Se les efectuará deducción de haberes, que no afectará al régimen de sus prestaciones sociales.","Devengarán las retribuciones correspondientes el tiempo en que hayan permanecido en esa situación."],"bloque":"retribuciones","precepto":"Art. 30.2 del TREBEP","correcta":3,"justificaciones":["Es verdadera, así que no se marca. La deducción no tiene carácter sancionador (**art. 30.2**).","Es verdadera, así que no se marca. No perciben retribuciones por ese tiempo.","Es verdadera, así que no se marca. La deducción no afecta a sus prestaciones sociales (**art. 30.2**).","Esta es la falsa, y por eso es la que hay que marcar. No devengan las retribuciones del tiempo de huelga."]},{"id":"au-04-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":14,"enunciado":"Señale la respuesta incorrecta en relación con las retribuciones de los funcionarios:","opciones":["Las retribuciones de los funcionarios de carrera se clasifican en básicas y complementarias.","Las pagas extraordinarias, que serán dos al año, comprenderán la totalidad de las retribuciones complementarias.","Las retribuciones complementarias retribuyen, entre otros aspectos, las características de los puestos de trabajo.","No podrá percibirse participación en tributos como contraprestación de cualquier servicio."],"bloque":"retribuciones","precepto":"Art. 22.4 del TREBEP","correcta":1,"justificaciones":["Es verdadera, así que no se marca. **Art. 22.1**.","Esta es la falsa, y por eso es la que hay que marcar. Las pagas extraordinarias incluyen la totalidad de las complementarias salvo las de los apartados c) y d) del art. 24 (**art. 22.4**).","Es verdadera, así que no se marca. **Art. 22.3**.","Es verdadera, así que no se marca. **Art. 22.5**."]},{"id":"au-04-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":15,"enunciado":"De acuerdo con el artículo 24 del TREBEP, la cuantía y estructura de las retribuciones complementarias de los funcionarios se establecerán por:","opciones":["Las correspondientes leyes de cada Administración Pública.","Los correspondientes convenios colectivos.","Los órganos de Gobierno de las respectivas Administraciones Públicas.","La Ley de Presupuestos Generales del Estado."],"bloque":"retribuciones","precepto":"Art. 24 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 24** dice que se establecen por las correspondientes leyes de cada Administración Pública.","No. No se fijan por convenios colectivos (que son del personal laboral).","No. No son los órganos de gobierno, sino las leyes de cada Administración.","No. La Ley de Presupuestos del Estado fija las básicas (**art. 23**)."]},{"id":"au-04-016","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":16,"enunciado":"Las retribuciones que retribuyen las características de los puestos de trabajo, la carrera profesional o el desempeño alcanzado por el funcionario se denominan:","opciones":["Básicas.","Fijas.","Complementarias.","Variables."],"bloque":"retribuciones","precepto":"Art. 22.3 del TREBEP","correcta":2,"justificaciones":["No. Las básicas retribuyen la adscripción al Subgrupo y la antigüedad (**art. 22.2**).","No. “Fijas” no es una categoría del Estatuto.","Es esta. El **art. 22.3** dice que las complementarias retribuyen las características de los puestos, la carrera profesional o el desempeño.","No. “Variables” no es una categoría del Estatuto."]},{"id":"au-04-017","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":17,"enunciado":"Según el artículo 22 del TREBEP, las pagas extraordinarias de los funcionarios de carrera se compondrán por el importe de una mensualidad de:","opciones":["Las retribuciones básicas, exclusivamente.","Las retribuciones básicas y las retribuciones complementarias a las que se refieren los apartados a) y b) del artículo 24.","Las retribuciones básicas y las retribuciones complementarias a las que se refieren los apartados c) y d) del artículo 24.","Las retribuciones básicas y la totalidad de las retribuciones complementarias."],"bloque":"retribuciones","precepto":"Arts. 22.4 y 24 del TREBEP","correcta":1,"justificaciones":["No. También incluyen las complementarias, salvo las de los apartados c) y d) del art. 24.","Es esta. Una mensualidad de básicas y de las complementarias, salvo c) y d) del art. 24, es decir, las de los apartados a) y b) (**art. 22.4**).","No. Son justo las que se excluyen.","No. No incluyen la totalidad: quedan fuera las de los apartados c) y d)."]},{"id":"au-04-018","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":18,"enunciado":"Señale la respuesta incorrecta en relación con las retribuciones de los funcionarios interinos:","opciones":["Percibirán las retribuciones básicas correspondientes al Subgrupo o Grupo de adscripción.","Salvo excepciones, no percibirán retribuciones complementarias.","Percibirán las pagas extraordinarias correspondientes al Subgrupo o Grupo de adscripción.","Se reconocerán los trienios correspondientes a los servicios prestados antes de la entrada en vigor del TREBEP."],"bloque":"retribuciones","precepto":"Art. 25 del TREBEP","correcta":1,"justificaciones":["Es verdadera, así que no se marca. **Art. 25.1**.","Esta es la falsa, y por eso es la que hay que marcar. Perciben las complementarias de los apartados b), c) y d) del art. 24 y las de la categoría de entrada (**art. 25.1**).","Es verdadera, así que no se marca. **Art. 25.1**.","Es verdadera, así que no se marca. **Art. 25.2**."]},{"id":"au-04-019","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":19,"enunciado":"Las retribuciones del personal laboral se determinarán de acuerdo con:","opciones":["La legislación laboral.","El convenio colectivo que sea aplicable.","El contrato de trabajo.","Todas las respuestas anteriores son correctas."],"bloque":"retribuciones","precepto":"Art. 27 del TREBEP","correcta":3,"justificaciones":["Es correcta, pero no es la única.","Es correcta, pero no es la única.","Es correcta, pero no es la única.","Es esta. El **art. 27** menciona las tres: legislación laboral, convenio colectivo y contrato de trabajo."]},{"id":"au-04-020","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":20,"enunciado":"Los trienios de las pagas extraordinarias y las retribuciones por servicios extraordinarios prestados fuera de la jornada normal de trabajo constituyen:","opciones":["Retribuciones complementarias, en ambos casos.","Retribuciones básicas, los primeros, y complementarias, los segundos.","Retribuciones complementarias, los primeros, y básicas, los segundos.","Retribuciones básicas, en ambos casos."],"bloque":"retribuciones","precepto":"Arts. 22.2 y 24.d del TREBEP","correcta":1,"justificaciones":["No. Los trienios son retribuciones básicas.","Es esta. Los trienios (incluidos los de las pagas extraordinarias) son básicos (**art. 22.2**) y los servicios extraordinarios fuera de jornada son complementarios (**art. 24.d**).","No. Los has invertido.","No. Los servicios extraordinarios son complementarios."]},{"id":"au-05-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":1,"enunciado":"¿A qué principios estará sujeta la negociación colectiva de condiciones de trabajo de los funcionarios públicos?","opciones":["De legalidad, jerarquía, eficacia, buena fe negocial, publicidad y transparencia.","De legalidad, eficacia, eficiencia, desconcentración, publicidad y obligatoriedad.","De legalidad, cobertura presupuestaria, obligatoriedad, buena fe negocial, publicidad y transparencia.","De legalidad, jerarquía, desconcentración, buena fe negocial, cobertura presupuestaria y coordinación."],"bloque":"negociacion","precepto":"Art. 33.1 del TREBEP","correcta":2,"justificaciones":["No. La jerarquía y la eficacia no son principios del art. 33.1.","No. Eficacia, eficiencia y desconcentración no están en la lista.","Es esta. El **art. 33.1** cita legalidad, cobertura presupuestaria, obligatoriedad, buena fe negocial, publicidad y transparencia.","No. Ni jerarquía, ni desconcentración, ni coordinación son principios del art. 33.1."]},{"id":"au-05-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":2,"enunciado":"¿Cuál de las siguientes materias NO queda excluida de la obligatoriedad de la negociación?","opciones":["La determinación de condiciones de trabajo del personal directivo.","La regulación del ejercicio del derecho de los ciudadanos y de los usuarios de los servicios públicos.","Los criterios generales sobre ofertas de empleo público.","Los poderes de dirección y control propios de la relación jerárquica."],"bloque":"negociacion","precepto":"Art. 37 del TREBEP","correcta":2,"justificaciones":["No. Está excluida (**art. 37.2.c**).","No. Está excluida (**art. 37.2.b**).","Es esta. Los criterios generales sobre ofertas de empleo público son materia de negociación obligatoria (**art. 37.1.l**).","No. Está excluida (**art. 37.2.d**)."]},{"id":"au-05-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":3,"enunciado":"Según el TREBEP, salvo que existan causas legales o pactadas que lo impidan, el proceso de negociación se iniciará, desde que la mayoría de una de las partes legitimadas lo promueva, en el plazo máximo de:","opciones":["Seis meses.","Veinte días.","Un mes.","Tres meses."],"bloque":"negociacion","precepto":"Art. 34.6 del TREBEP","correcta":2,"justificaciones":["No. No son seis meses.","No. No son veinte días.","Es esta. A falta de acuerdo, el proceso se inicia en el plazo máximo de un mes (**art. 34.6**).","No. No son tres meses."]},{"id":"au-05-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":4,"enunciado":"¿Cuál de las siguientes materias NO ha de ser objeto de negociación obligatoria según el artículo 37 del TREBEP?","opciones":["La determinación de condiciones de trabajo del personal directivo.","Los planes de Previsión Social Complementaria.","Las propuestas sobre derechos sindicales y de participación.","Los criterios generales para la determinación de prestaciones sociales y pensiones de clases pasivas."],"bloque":"negociacion","precepto":"Art. 37.2.c del TREBEP","correcta":0,"justificaciones":["Es esta. La determinación de condiciones de trabajo del personal directivo está excluida de la negociación obligatoria (**art. 37.2.c**).","No. Es materia de negociación (**art. 37.1.e**).","No. Es materia de negociación (**art. 37.1.h**).","No. Es materia de negociación (**art. 37.1.g**)."]},{"id":"au-05-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":5,"enunciado":"Según el TREBEP, a efectos de negociación colectiva de los funcionarios públicos se constituye una Mesa General de Negociación de las Administraciones Públicas, que contará con representantes de:","opciones":["Las Comunidades Autónomas.","Las ciudades de Ceuta y Melilla.","La Federación Española de Municipios y Provincias.","Todas las respuestas anteriores son correctas."],"bloque":"negociacion","precepto":"Art. 36.1 del TREBEP","correcta":3,"justificaciones":["Es correcta, pero no es la única.","Es correcta, pero no es la única.","Es correcta, pero no es la única.","Es esta. La Mesa General cuenta con representantes de las Comunidades Autónomas, Ceuta y Melilla y la FEMP (**art. 36.1**)."]},{"id":"au-05-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":6,"enunciado":"Según el artículo 34 del TREBEP, en el ámbito de la Administración General del Estado es obligatorio constituir:","opciones":["Una Mesa General de Negociación.","Tanto una Mesa General de Negociación como Mesas Sectoriales.","Mesas Sectoriales de negociación.","La constitución de cualquier Mesa de Negociación es facultativa."],"bloque":"negociacion","precepto":"Art. 34.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Se constituirá una Mesa General de Negociación en la Administración General del Estado (**art. 34.1**).","No. Las Mesas Sectoriales son facultativas: se constituyen por acuerdo de las Mesas Generales (**art. 34.4**).","No. Las Mesas Sectoriales no son obligatorias.","No. La Mesa General sí es obligatoria."]},{"id":"au-05-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":7,"enunciado":"Según el artículo 36 del TREBEP, la Mesa General de Negociación de las Administraciones Públicas estará presidida por:","opciones":["La Administración General del Estado.","Representantes de las Comunidades Autónomas.","La Federación Española de Municipios y Provincias.","Rotativamente por todos los anteriores."],"bloque":"negociacion","precepto":"Art. 36.1 del TREBEP","correcta":0,"justificaciones":["Es esta. La Mesa General de las Administraciones Públicas está presidida por la Administración General del Estado (**art. 36.1**).","No. Las Comunidades Autónomas tienen representantes, pero no la presiden.","No. La FEMP tiene representantes, pero no la preside.","No. No hay presidencia rotativa."]},{"id":"au-05-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":8,"enunciado":"En el seno de las Mesas de Negociación correspondientes, los representantes de las Administraciones Públicas podrán concertar Pactos y Acuerdos para la determinación de condiciones de trabajo de los funcionarios de dichas Administraciones con:","opciones":["La representación de las organizaciones sindicales legitimadas a tales efectos.","Los Delegados de Personal.","La Junta de Personal.","Cualquiera de los anteriores."],"bloque":"negociacion","precepto":"Art. 38.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Los Pactos y Acuerdos se concertan con las organizaciones sindicales legitimadas (**art. 38.1**).","No. Los delegados de personal son órganos de representación, no negocian Pactos y Acuerdos en la Mesa.","No. La Junta de Personal es un órgano de representación unitaria, no una parte del Pacto.","No. Solo vale la primera."]},{"id":"au-05-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":9,"enunciado":"Para el seguimiento de los Pactos y Acuerdos se establecerán, con la composición y funciones que las partes determinen:","opciones":["Mesas Generales de Negociación.","Organizaciones sindicales.","Comisiones Paritarias.","Mesas Sectoriales."],"bloque":"negociacion","precepto":"Art. 38.5 del TREBEP","correcta":2,"justificaciones":["No. Las Mesas Generales son donde se negocia.","No. Las organizaciones sindicales son una de las partes.","Es esta. El **art. 38.5** establece Comisiones Paritarias de seguimiento.","No. Las Mesas Sectoriales negocian, no hacen el seguimiento."],"dup":"au-05-009"},{"id":"au-05-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":10,"enunciado":"Según el TREBEP, el derecho a participar, a través de las organizaciones sindicales, en los órganos de control y seguimiento de las entidades u organismos que legalmente se determine, se denomina:","opciones":["Derecho de representación.","Mesas de negociación.","Participación Institucional.","Negociación colectiva."],"bloque":"negociacion","precepto":"Art. 31.4 del TREBEP","correcta":2,"justificaciones":["No. La representación es la facultad de elegir representantes (**art. 31.3**).","No. Las Mesas son órganos de negociación.","Es esta. La participación institucional es el derecho a participar, a través de los sindicatos, en los órganos de control y seguimiento (**art. 31.4**).","No. La negociación colectiva es el derecho a negociar condiciones de trabajo (**art. 31.2**)."]},{"id":"au-05-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":11,"enunciado":"De conformidad con el TREBEP, salvo acuerdo en contrario, los Pactos y Acuerdos se prorrogarán:","opciones":["De año en año, siempre que conste la aceptación expresa de todas las partes.","De año en año, si no mediara denuncia expresa de una de las partes.","De mes en mes, siempre que conste la aceptación expresa de todas las partes.","De mes en mes, si no mediara denuncia expresa de una de las partes."],"bloque":"negociacion","precepto":"Art. 38.11 del TREBEP","correcta":1,"justificaciones":["No. No hace falta aceptación expresa: se prorrogan si nadie los denuncia.","Es esta. Salvo acuerdo en contrario, se prorrogan de año en año si no media denuncia expresa de una de las partes (**art. 38.11**).","No. El plazo es de año en año, no de mes en mes.","No. El plazo es de un año."]},{"id":"au-05-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":12,"enunciado":"Según el TREBEP, la negociación colectiva de condiciones de trabajo de los funcionarios públicos estará sujeta, entre otros, a los principios de:","opciones":["Cobertura presupuestaria.","Obligatoriedad","Buena fe negocial.","Todas las respuestas anteriores son correctas."],"bloque":"negociacion","precepto":"Art. 33.1 del TREBEP","correcta":3,"justificaciones":["Es un principio del **art. 33.1**, pero no el único.","Es un principio del **art. 33.1**, pero no el único.","Es un principio del **art. 33.1**, pero no el único.","Es esta. Las tres son principios del **art. 33.1**."]},{"id":"au-05-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":13,"enunciado":"Conforme al artículo 34.7 del TREBEP, en los procesos de negociación, la Administración correspondiente y la mayoría de la representación sindical están obligadas a proporcionarse mutuamente la información que precisen relativa a la negociación y a negociar bajo el principio de:","opciones":["Cobertura presupuestaria.","Transparencia.","La buena fe.","Publicidad."],"bloque":"negociacion","precepto":"Art. 34.7 del TREBEP","correcta":2,"justificaciones":["No. La cobertura presupuestaria es otro principio del art. 33.1.","No. Es otro principio del art. 33.1, no el del 34.7.","Es esta. El **art. 34.7** dice que ambas partes negociarán bajo el principio de la buena fe.","No. Es otro principio del art. 33.1."]},{"id":"au-05-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":14,"enunciado":"De conformidad con lo establecido en el texto refundido de la Ley del Estatuto Básico del Empleado Público, entre los principios a los que está sujeta la negociación colectiva de las condiciones de trabajo de los funcionarios públicos, NO se encuentra:","opciones":["El principio de legalidad.","El principio de cobertura presupuestaria.","El principio de jerarquía.","El principio de obligatoriedad."],"bloque":"negociacion","precepto":"Art. 33.1 del TREBEP","correcta":2,"justificaciones":["Es un principio del **art. 33.1**, así que no se marca.","Es un principio del **art. 33.1**, así que no se marca.","Esta es la que NO está, y por eso es la que hay que marcar. La jerarquía no es un principio de la negociación colectiva.","Es un principio del **art. 33.1**, así que no se marca."]},{"id":"au-05-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":15,"enunciado":"Según el TREBEP, quedará excluida de la obligatoriedad de la negociación:","opciones":["La determinación y aplicación de las retribuciones complementarias de los funcionarios.","El procedimiento de formación de los actos y disposiciones administrativas.","Los criterios generales de acción social.","Las normas que fijen los criterios y mecanismos generales en materia de evaluación del desempeño."],"bloque":"negociacion","precepto":"Art. 37.2.b del TREBEP","correcta":1,"justificaciones":["No. Es materia de negociación (**art. 37.1.b**).","Es esta. El procedimiento de formación de los actos y disposiciones administrativas está excluido (**art. 37.2.b**).","No. Es materia de negociación (**art. 37.1.i**).","No. Es materia de negociación (**art. 37.1.d**)."]},{"id":"au-05-016","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":16,"enunciado":"Señale cuál de estas materias queda excluida de la negociación colectiva de los empleados públicos, a tenor de lo previsto en el artículo 37 del TREBEP:","opciones":["Los criterios generales sobre ofertas de empleo público.","Los planes de previsión social complementaria.","La regulación y determinación concreta, en cada caso, de los sistemas de acceso al empleo público.","La determinación y aplicación de las retribuciones complementarias de los funcionarios."],"bloque":"negociacion","precepto":"Art. 37.2.e del TREBEP","correcta":2,"justificaciones":["No. Es materia de negociación (**art. 37.1.l**).","No. Es materia de negociación (**art. 37.1.e**).","Es esta. La regulación y determinación concreta de los sistemas de acceso al empleo público está excluida (**art. 37.2.e**).","No. Es materia de negociación (**art. 37.1.b**)."]},{"id":"au-05-017","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":17,"enunciado":"Conforme al TREBEP, a efectos de negociación colectiva de las condiciones de trabajo de funcionarios públicos, se constituirán Mesas de negociación en las que no estarán legitimadas para estar presentes:","opciones":["Las organizaciones sindicales más representativas a nivel estatal.","Los representantes de la Administración Pública correspondiente.","Las organizaciones sindicales más representativas de Comunidades Autónomas.","Los sindicatos que hayan obtenido el 5% de los representantes en las elecciones para Delegados y Juntas de Personal."],"bloque":"negociacion","precepto":"Art. 33.1 del TREBEP","correcta":3,"justificaciones":["No. Están legitimadas (**art. 33.1**).","No. Están legitimados.","No. Están legitimadas.","Es esta. Los sindicatos necesitan el 10 por 100 o más de los representantes, no el 5 (**art. 33.1**)."]},{"id":"au-05-018","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":18,"enunciado":"¿Cuál de las siguientes materias NO ha de ser objeto de negociación según el artículo 37 del TREBEP?","opciones":["Los criterios generales de los planes y fondos para la formación y la promoción interna.","Los planes de Previsión Social Complementaria.","Las normas que fijen los criterios y mecanismos generales en materia de evaluación del desempeño.","Los poderes de dirección y control propios de la relación jerárquica."],"bloque":"negociacion","precepto":"Art. 37 del TREBEP","correcta":3,"justificaciones":["No. Es materia de negociación (**art. 37.1.f**).","No. Es materia de negociación (**art. 37.1.e**).","No. Es materia de negociación (**art. 37.1.d**).","Es esta. Los poderes de dirección y control propios de la relación jerárquica están excluidos (**art. 37.2.d**)."]},{"id":"au-05-019","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":19,"enunciado":"De acuerdo con el TREBEP, quedan excluidas de la obligatoriedad de la negociación colectiva:","opciones":["Las decisiones de las Administraciones Públicas que afecten a sus potestades de organización.","Los criterios generales sobre oferta de empleo público.","La determinación y aplicación de las retribuciones complementarias de los funcionarios.","Las normas que fijen los mecanismos generales de evaluación del desempeño."],"bloque":"negociacion","precepto":"Art. 37.2.a del TREBEP","correcta":0,"justificaciones":["Es esta. Las decisiones que afecten a las potestades de organización están excluidas (**art. 37.2.a**).","No. Es materia de negociación (**art. 37.1.l**).","No. Es materia de negociación (**art. 37.1.b**).","No. Es materia de negociación (**art. 37.1.d**)."]},{"id":"au-05-020","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":20,"enunciado":"Señale la respuesta correcta en relación con los acuerdos a que se refiere el artículo 38 del TREBEP:","opciones":["Salvo acuerdo en contrario, se prorrogarán cada 5 años si no mediara denuncia expresa de una de las partes.","Se celebrarán sobre materias que correspondan estrictamente al ámbito competencial del órgano que lo suscriba.","Versarán sobre materias competencia de los órganos de gobierno de Administraciones Públicas.","Tendrán eficacia directa, en todo caso."],"bloque":"negociacion","precepto":"Art. 38.3 del TREBEP","correcta":2,"justificaciones":["No. Se prorrogan de año en año, no cada cinco años (**art. 38.11**).","No. Eso describe los Pactos (**art. 38.2**). Los Acuerdos versan sobre materias de los órganos de gobierno.","Es esta. Los Acuerdos versan sobre materias competencia de los órganos de gobierno de las Administraciones Públicas (**art. 38.3**).","No. No siempre tienen eficacia directa: si tratan materias de reserva de ley, carecen de ella (**art. 38.3**)."]},{"id":"au-05-021","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":21,"enunciado":"A efectos del Real Decreto Legislativo 5/2015, el derecho a negociar la determinación de condiciones de trabajo de los empleados de las Administraciones Públicas, se entiende como:","opciones":["Negociación institucional.","Negociación colectiva.","Pactos colectivos.","Acuerdos institucionales."],"bloque":"negociacion","precepto":"Art. 31.2 del TREBEP","correcta":1,"justificaciones":["No. No existe como tal en el Estatuto.","Es esta. Es el derecho a negociar la determinación de condiciones de trabajo (**art. 31.2**).","No. Los Pactos son el resultado de la negociación.","No. Los Acuerdos son el resultado de la negociación."]},{"id":"au-05-022","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":22,"enunciado":"Están legitimados para la interposición de recursos en vía administrativa y jurisdiccional contra las resoluciones de los órganos de selección:","opciones":["Los empleados públicos.","Los órganos de control y seguimiento de las Administraciones Públicas.","Las organizaciones sindicales más representativas en el ámbito de la Función Pública.","Cualquier organización sindical."],"bloque":"negociacion","precepto":"Art. 31.6 del TREBEP","correcta":2,"justificaciones":["No. El Estatuto no legitima a todos los empleados públicos en este supuesto.","No. Los órganos de control no recurren.","Es esta. Las organizaciones sindicales más representativas en el ámbito de la Función Pública están legitimadas (**art. 31.6**).","No. No vale cualquier organización sindical, solo las más representativas."]},{"id":"au-05-023","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":23,"enunciado":"En la composición numérica de las Mesas Generales de Negociación:","opciones":["Ninguna de las partes puede superar los siete miembros.","Ninguna de las partes puede superar los nueve miembros.","Ninguna de las partes puede superar el número de once miembros.","Ninguna de las partes puede superar el número de quince miembros."],"bloque":"negociacion","precepto":"Art. 35.4 del TREBEP","correcta":3,"justificaciones":["No. El tope es quince.","No. El tope es quince.","No. El tope es quince.","Es esta. Ninguna de las partes puede superar el número de quince miembros (**art. 35.4**)."]},{"id":"au-05-024","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":24,"enunciado":"¿Por quién estará presidida la Mesa General de Negociación de las Administraciones Públicas?","opciones":["Por los Delegados de Personal.","Por el Comité de Empresa.","Por la Administración General del Estado.","Por la Junta de Personal."],"bloque":"negociacion","precepto":"Art. 36.1 del TREBEP","correcta":2,"justificaciones":["No. Los delegados de personal son órganos de representación.","No. El Comité de Empresa es órgano de representación del personal laboral.","Es esta. La preside la Administración General del Estado (**art. 36.1**).","No. La Junta de Personal es órgano de representación."]},{"id":"au-05-025","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":25,"enunciado":"Cuando exista falta de ratificación de un Acuerdo o, en su caso, una negativa expresa a incorporar lo acordado en el proyecto de ley correspondiente se deberá iniciar la renegociación de las materias tratadas:","opciones":["En el plazo de un mes, si así lo solicitara al menos la mayoría de una de las partes.","En el plazo de un mes, si así lo solicitara al menos los dos tercios de una de las partes.","En el plazo de un año, si así lo solicitara al menos la mayoría de una de las partes.","En el plazo de un año, si así lo solicitara al menos los dos tercios de una de las partes."],"bloque":"negociacion","precepto":"Art. 38.3 del TREBEP","correcta":0,"justificaciones":["Es esta. Se renegocia en el plazo de un mes si lo solicita al menos la mayoría de una de las partes (**art. 38.3**).","No. No son los dos tercios.","No. El plazo es de un mes, no de un año.","No. Ni un año ni dos tercios."]},{"id":"au-06-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":1,"enunciado":"Los Delegados de Personal se elegirán mediante:","opciones":["Listas abiertas y sistema mayoritario.","Listas abiertas y sistema proporcional corregido.","Listas cerradas y sistema mayoritario.","Listas cerradas y sistema proporcional corregido."],"bloque":"representacion","precepto":"Art. 44.d del TREBEP","correcta":0,"justificaciones":["Es esta. Los Delegados de Personal se eligen por listas abiertas y sistema mayoritario (**art. 44.d**).","No. Las listas abiertas son las de los Delegados, pero el sistema proporcional corregido es el de las Juntas de Personal.","No. Las listas cerradas son las de las Juntas de Personal, no las de los Delegados.","No. Esta es la fórmula de las Juntas de Personal, no la de los Delegados (**art. 44.d**)."]},{"id":"au-06-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":2,"enunciado":"En unidades electorales que cuenten con un censo de trescientos funcionarios, los miembros de las Juntas de Personal tendrán derecho a un crédito de horas mensuales retribuidas, dentro de la jornada de trabajo, de:","opciones":["Veinte horas.","Treinta horas.","Treinta y cinco horas.","Cuarenta horas."],"bloque":"representacion","precepto":"Art. 41.1.d del TREBEP","correcta":1,"justificaciones":["No. Veinte horas es el tramo de 101 a 250 funcionarios.","Es esta. Con 300 funcionarios se está en el tramo de 251 a 500, que da treinta horas mensuales (**art. 41.1.d**).","No. Treinta y cinco horas es el tramo de 501 a 750 funcionarios.","No. Cuarenta horas es de 751 funcionarios en adelante."]},{"id":"au-06-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":3,"enunciado":"Señale la respuesta incorrecta. Los miembros de las Juntas de Personal y los Delegados de Personal tendrán derecho a un crédito de horas mensuales:","opciones":["No acumulables.","Dentro de la jornada de trabajo.","Retribuidas como de trabajo efectivo.","De acuerdo con una escala que atiende al número de funcionarios."],"bloque":"representacion","precepto":"Art. 41.1.d del TREBEP","correcta":0,"justificaciones":["Esta es la falsa, y por eso es la que hay que marcar. Los créditos horarios sí se pueden acumular, si lo manifiestan miembros de la misma candidatura y lo comunican a la Jefatura de Personal (**art. 41.1.d**).","Es verdadera, así que no se marca. El crédito de horas es dentro de la jornada de trabajo.","Es verdadera, así que no se marca. Las horas se retribuyen como de trabajo efectivo.","Es verdadera, así que no se marca. La escala va de 15 horas (hasta 100 funcionarios) a 40 (de 751 en adelante)."]},{"id":"au-06-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":4,"enunciado":"El TREBEP establece en su artículo 39 que las Juntas de Personal se constituirán en unidades electorales que cuenten con:","opciones":["Un censo máximo de 50 funcionarios.","Un censo mínimo de 100 funcionarios.","Un censo mínimo de 50 funcionarios.","Un censo máximo de 100 funcionarios."],"bloque":"representacion","precepto":"Art. 39.3 del TREBEP","correcta":2,"justificaciones":["No. No es un máximo: las Juntas de Personal exigen un mínimo, y además es de 50 funcionarios (**art. 39.3**).","No. Cien es el límite de la primera franja de la escala del crédito de horas, no el mínimo para constituir Junta.","Es esta. Las Juntas de Personal se constituyen en unidades electorales con un censo mínimo de 50 funcionarios (**art. 39.3**).","No. Es un mínimo, no un máximo, y la cifra es 50."]},{"id":"au-06-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":5,"enunciado":"El mandato de los miembros de las Juntas de Personal y de los Delegados de Personal será de:","opciones":["Cinco años, no reelegibles.","Cuatro años, reelegibles.","Cuatro años, no reelegibles.","Cinco años, reelegibles."],"bloque":"representacion","precepto":"Art. 42 del TREBEP","correcta":1,"justificaciones":["No. El mandato es de cuatro años, no cinco, y sí se puede ser reelegido.","Es esta. El mandato es de cuatro años, pudiendo ser reelegidos (**art. 42**).","No. Los cuatro años son correctos, pero sí cabe la reelección.","No. Es reelegible, pero el mandato es de cuatro años, no de cinco."]},{"id":"au-06-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":6,"enunciado":"El TREBEP establece que en unidades electorales donde el número de funcionarios sea de entre 31 y 49 su representación corresponderá:","opciones":["A tres delegados de personal que ejercerán su representación conjunta y mancomunadamente.","A cinco delegados de personal que ejercerán su representación conjunta y mancomunadamente.","A tres delegados de personal que ejercerán su representación conjunta y solidariamente.","A cinco delegados de personal que ejercerán su representación conjunta y solidariamente."],"bloque":"representacion","precepto":"Art. 39.2 del TREBEP","correcta":0,"justificaciones":["Es esta. De 31 a 49 funcionarios se eligen tres Delegados, que ejercen su representación conjunta y mancomunadamente (**art. 39.2**).","No. De 31 a 49 se eligen tres, no cinco.","No. Son tres, pero la representación es mancomunada, no solidaria.","No. Ni son cinco ni la representación es solidaria."]},{"id":"au-06-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":7,"enunciado":"¿Cuántos representantes tendrá una Junta de Personal en una unidad electoral de 1.000 funcionarios?","opciones":["Veintiuno.","Diecinueve.","Quince.","Diecisiete."],"bloque":"representacion","precepto":"Art. 39.5 del TREBEP","correcta":0,"justificaciones":["Es esta. Con 1.000 funcionarios se está en el tramo de 751 a 1.000, que tiene 21 representantes (**art. 39.5**).","No. Diecinueve no figura en la escala.","No. Quince tampoco figura en la escala.","No. Diecisiete es el tramo de 501 a 750 funcionarios."]},{"id":"au-06-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":8,"enunciado":"En las unidades electorales donde el número de funcionarios sea de 6 a 30 funcionarios:","opciones":["Se elegirán tres Delegados de Personal, que ejercerán su representación conjunta y solidariamente.","Se elegirán tres Delegados de Personal, que ejercerán su representación conjunta y mancomunadamente.","Su representación corresponderá a la Junta de Personal.","Se elegirá un Delegado de Personal."],"bloque":"representacion","precepto":"Art. 39.2 del TREBEP","correcta":3,"justificaciones":["No. Hasta 30 funcionarios se elige un solo Delegado; los tres son para el tramo de 31 a 49.","No. Los tres Delegados, mancomunados, son para el tramo de 31 a 49, no para el de 6 a 30.","No. La Junta de Personal exige un censo mínimo de 50 funcionarios (**art. 39.3**).","Es esta. Hasta 30 funcionarios se elige un Delegado de Personal (**art. 39.2**)."]},{"id":"au-06-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":9,"enunciado":"Los miembros de las Juntas de Personal y los Delegados de Personal, de 101 a 250 funcionarios, como representantes legales de los funcionarios, dispondrán de:","opciones":["15 horas mensuales dentro de la jornada de trabajo y retribuidas.","20 horas mensuales dentro de la jornada de trabajo y retribuidas.","30 horas mensuales dentro de la jornada de trabajo y retribuidas.","35 horas mensuales dentro de la jornada de trabajo y retribuidas."],"bloque":"representacion","precepto":"Art. 41.1.d del TREBEP","correcta":1,"justificaciones":["No. Quince horas es hasta 100 funcionarios.","Es esta. De 101 a 250 funcionarios son veinte horas mensuales, dentro de la jornada y retribuidas (**art. 41.1.d**).","No. Treinta horas es el tramo de 251 a 500.","No. Treinta y cinco horas es el tramo de 501 a 750."]},{"id":"au-06-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":10,"enunciado":"Los miembros de las Juntas de Personal y los Delegados de Personal, de 501 a 750 funcionarios, como representantes legales de los funcionarios, dispondrán de:","opciones":["15 horas mensuales dentro de la jornada de trabajo y retribuidas.","20 horas mensuales dentro de la jornada de trabajo y retribuidas.","30 horas mensuales dentro de la jornada de trabajo y retribuidas.","35 horas mensuales dentro de la jornada de trabajo y retribuidas."],"bloque":"representacion","precepto":"Art. 41.1.d del TREBEP","correcta":3,"justificaciones":["No. Quince horas es hasta 100 funcionarios.","No. Veinte horas es el tramo de 101 a 250.","No. Treinta horas es el tramo de 251 a 500.","Es esta. De 501 a 750 funcionarios son treinta y cinco horas mensuales, dentro de la jornada y retribuidas (**art. 41.1.d**)."]},{"id":"au-06-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":11,"enunciado":"Salvo acuerdo entre el órgano competente en materia de personal y quienes estén legitimados para convocarlas, las reuniones en el centro de trabajo se autorizarán:","opciones":["Dentro de las horas de trabajo.","Fuera de las horas de trabajo.","No serán posibles.","Ninguna es correcta."],"bloque":"representacion","precepto":"Art. 46.2 del TREBEP","correcta":1,"justificaciones":["No. La regla general es la contraria: se autorizan fuera de las horas de trabajo.","Es esta. Las reuniones en el centro de trabajo se autorizan fuera de las horas de trabajo, salvo acuerdo entre el órgano competente en materia de personal y los convocantes (**art. 46.2**).","No. Sí son posibles: el artículo regula en qué horario se autorizan.","No. Hay una correcta."]},{"id":"au-06-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":12,"enunciado":"Según el TREBEP, están legitimados para convocar una reunión, además de las Organizaciones Sindicales y de las personas o colectivos indicados en el artículo 46, los empleados públicos de las Administraciones respectivas:","opciones":["En número no inferior al 20 por 100 del colectivo convocado.","En número no inferior al 30 por 100 del colectivo convocado.","En número no inferior al 40 por 100 del colectivo convocado.","En número no inferior al 50 por 100 del colectivo convocado."],"bloque":"representacion","precepto":"Art. 46.1.d del TREBEP","correcta":2,"justificaciones":["No. El porcentaje mínimo es del 40 por 100, no del 20.","No. El porcentaje mínimo es del 40 por 100, no del 30.","Es esta. Los empleados públicos pueden convocar en número no inferior al 40 por 100 del colectivo convocado (**art. 46.1.d**).","No. El porcentaje mínimo es del 40 por 100, no del 50."]},{"id":"au-06-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":13,"enunciado":"En coherencia con el Estatuto de los Trabajadores, el artículo 39 del TREBEP establece que la Junta de Personal de una Unidad electoral con un total de 263 funcionarios estará compuesta por:","opciones":["21 representantes","13 representantes.","9 representantes.","17 representantes."],"bloque":"representacion","precepto":"Art. 39.5 del TREBEP","correcta":1,"justificaciones":["No. Veintiuno es el tramo de 751 a 1.000 funcionarios.","Es esta. Con 263 funcionarios se está en el tramo de 251 a 500, que tiene 13 representantes (**art. 39.5**).","No. Nueve es el tramo de 101 a 250 funcionarios.","No. Diecisiete es el tramo de 501 a 750 funcionarios."]},{"id":"au-06-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":14,"enunciado":"De conformidad con lo dispuesto en el artículo 39 del Real Decreto Legislativo 5/2015, de 30 de octubre, por el que se aprueba el Texto Refundido de la Ley del Estatuto básico del empleado público, ¿cuántos representantes tendrá la Junta de Personal en una unidad electoral donde hay 850 funcionarios?","opciones":["13.","21.","17.","19."],"bloque":"representacion","precepto":"Art. 39.5 del TREBEP","correcta":1,"justificaciones":["No. Trece es el tramo de 251 a 500 funcionarios.","Es esta. Con 850 funcionarios se está en el tramo de 751 a 1.000, que tiene 21 representantes (**art. 39.5**).","No. Diecisiete es el tramo de 501 a 750 funcionarios.","No. Diecinueve no figura en la escala."]},{"id":"au-06-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 6) - arts. 39 a 46","n":15,"enunciado":"Según el TREBEP, en una unidad electoral integrada por 500 funcionarios:","opciones":["La representación de los funcionarios corresponderá a los Delegados de Personal.","La representación de los funcionarios corresponderá a la Junta de Personal compuesta por 17 representantes.","La representación de los funcionarios corresponderá a la Junta de Personal compuesta por 13 representantes.","La representación de los funcionarios corresponderá al Comité de Empresa compuesto por 17 representantes."],"bloque":"representacion","precepto":"Art. 39.5 del TREBEP","correcta":2,"justificaciones":["No. Los Delegados de Personal son para unidades de 6 a 49 funcionarios; con 500 hay Junta de Personal.","No. Diecisiete es el tramo de 501 a 750 funcionarios.","Es esta. Con 500 funcionarios corresponde Junta de Personal, y el tramo de 251 a 500 tiene 13 representantes (**art. 39.5**).","No. El Comité de Empresa es el órgano del personal laboral; los funcionarios se representan con Juntas de Personal."]},{"id":"au-07-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":1,"enunciado":"De acuerdo con el TREBEP, señale la afirmación incorrecta con relación a las Juntas de Personal:","opciones":["Se constituyen en unidades electorales que cuenten con un censo mínimo de 50 funcionarios.","Elaborarán su propio reglamento de procedimiento, que deberá ser aprobado por mayoría simple de sus miembros.","El mandato de sus miembros será de cuatro años, pudiendo ser reelegidos.","Serán informadas de todas las sanciones impuestas por faltas muy graves."],"bloque":"representacion","precepto":"Art. 39.6 del TREBEP","correcta":1,"justificaciones":["Es verdadera, así que no se marca. El censo mínimo es de 50 funcionarios (**art. 39.3**).","Esta es la falsa, y por eso es la que hay que marcar. El reglamento y sus modificaciones exigen los votos favorables de, al menos, dos tercios de los miembros, no una mayoría simple (**art. 39.6**).","Es verdadera, así que no se marca. El mandato es de cuatro años, con posibilidad de reelección (**art. 42**).","Es verdadera, así que no se marca. Las Juntas son informadas de todas las sanciones por faltas muy graves (**art. 40.1.c**)."]},{"id":"au-07-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":2,"enunciado":"Según el artículo 40 del TREBEP, las Juntas de Personal y los Delegados de Personal podrán emitir informes sobre:","opciones":["Traslado total o parcial de las instalaciones.","Implantación o revisión de sistemas de organización.","Métodos de trabajo.","Todas las respuestas anteriores son correctas."],"bloque":"representacion","precepto":"Art. 40.1.b del TREBEP","correcta":3,"justificaciones":["No. Es cierta (**art. 40.1.b**), pero la opción correcta es la que recoge todas.","No. Es cierta (**art. 40.1.b**), pero la opción correcta es la que recoge todas.","No. Es cierta (**art. 40.1.b**), pero la opción correcta es la que recoge todas.","Es esta. El **art. 40.1.b** les atribuye emitir informe, a solicitud de la Administración, sobre el traslado de instalaciones y sobre la implantación o revisión de sistemas de organización y métodos de trabajo."]},{"id":"au-07-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":3,"enunciado":"En relación con el derecho de reunión de los empleados públicos, el Texto Refundido del Estatuto Básico del Empleado Público establece que no están legitimados para convocar una reunión:","opciones":["Los Delegados de Personal.","Los Comités de Empresa.","El Comité Intercentros.","Los empleados públicos en un número no inferior al 40 por ciento del colectivo convocado."],"bloque":"representacion","precepto":"Art. 46.1 del TREBEP","correcta":2,"justificaciones":["No. Los Delegados de Personal sí están legitimados (**art. 46.1.a**).","No. Los Comités de Empresa sí están legitimados (**art. 46.1.c**).","Es esta. El Comité Intercentros no figura en la lista de legitimados del **art. 46.1**.","No. Los empleados públicos sí pueden convocar si son al menos el 40 por 100 del colectivo convocado (**art. 46.1.d**)."]},{"id":"au-07-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":4,"enunciado":"Los órganos específicos de representación de los funcionarios son:","opciones":["Las Mesas Generales de Negociación y Mesas Sectoriales.","Las organizaciones sindicales.","Las Comisiones Paritarias.","Los Delegados de Personal y las Juntas de Personal."],"bloque":"representacion","precepto":"Art. 39.1 del TREBEP","correcta":3,"justificaciones":["No. Son órganos de negociación, no de representación.","No. Los sindicatos no son los órganos específicos de representación que enumera el **art. 39.1**.","No. Las comisiones paritarias resuelven los conflictos de aplicación e interpretación de los Pactos y Acuerdos (**art. 38.5**).","Es esta. Los órganos específicos de representación de los funcionarios son los Delegados de Personal y las Juntas de Personal (**art. 39.1**)."]},{"id":"au-07-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":5,"enunciado":"¿Dónde se constituirán las Juntas de Personal?","opciones":["En la totalidad de las unidades electorales.","En unidades electorales que cuenten con un censo mínimo de cincuenta funcionarios.","En unidades electorales que cuenten con un censo mínimo de setenta y cinco funcionarios.","En unidades electorales que cuenten con un censo mínimo de veinticinco funcionarios."],"bloque":"representacion","precepto":"Art. 39.3 del TREBEP","correcta":1,"justificaciones":["No. No se constituyen en todas las unidades electorales, solo en las de 50 o más funcionarios.","Es esta. Las Juntas de Personal se constituyen en unidades electorales con un censo mínimo de 50 funcionarios (**art. 39.3**).","No. El mínimo es de 50, no de 75.","No. El mínimo es de 50, no de 25."]},{"id":"au-07-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":6,"enunciado":"¿En qué unidades electorales corresponderá su representación a los Delegados de Personal?","opciones":["En aquellas que cuenten con un censo mínimo de cincuenta funcionarios.","En aquellas donde el número de funcionarios sea superior a seis e igual o inferior a cincuenta.","En aquellas donde el número de funcionarios sea igual o superior a seis e inferior a cincuenta.","En aquellas que cuenten con un censo máximo de cincuenta funcionarios."],"bloque":"representacion","precepto":"Art. 39.2 del TREBEP","correcta":2,"justificaciones":["No. Con un censo mínimo de 50 funcionarios corresponde Junta de Personal, no Delegados.","No. Invierte los límites: el tramo incluye el 6 y excluye el 50.","Es esta. Corresponde a Delegados de Personal en unidades con un número de funcionarios igual o superior a 6 e inferior a 50 (**art. 39.2**).","No. Con 50 funcionarios ya se constituye Junta de Personal (**art. 39.3**)."]},{"id":"au-07-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":7,"enunciado":"¿Cuánto durará el mandato de los miembros de las Juntas de Personal y de los Delegados de Personal?","opciones":["Cuatro años, sin posibilidad de reelección.","Cuatro años, pudiendo ser reelegidos.","Cinco años, sin posibilidad de reelección.","Cinco años, pudiendo ser reelegidos una sola vez."],"bloque":"representacion","precepto":"Art. 42 del TREBEP","correcta":1,"justificaciones":["No. Los cuatro años son correctos, pero sí cabe la reelección.","Es esta. El mandato es de cuatro años, pudiendo ser reelegidos (**art. 42**).","No. El mandato es de cuatro años, no de cinco, y hay reelección.","No. El mandato es de cuatro años, no de cinco, y no se limita la reelección a una vez."]},{"id":"au-07-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":8,"enunciado":"Los miembros de las Juntas de Personal y los Delegados de Personal en su caso, como representantes legales de los funcionarios no serán trasladados ni sancionados por causas relacionadas con el ejercicio de su mandato representativo:","opciones":["Ni durante la vigencia del mismo ni en el año siguiente a su extinción, exceptuando la extinción por revocación o dimisión.","Únicamente durante el año de la vigencia del mismo.","Ni durante la vigencia del mismo ni en el año siguiente a su extinción, exceptuando la extinción por incompatibilidad.","Ni durante la vigencia del mismo ni en el año siguiente a su extinción, en todo caso."],"bloque":"representacion","precepto":"Art. 41.1.e del TREBEP","correcta":0,"justificaciones":["Es esta. No pueden ser trasladados ni sancionados por causas relacionadas con su mandato ni durante este ni en el año siguiente, salvo que se extinga por revocación o dimisión (**art. 41.1.e**).","No. La protección dura la vigencia del mandato y el año siguiente a su extinción.","No. La excepción es la revocación o la dimisión, no la incompatibilidad.","No. Hay excepción: la extinción por revocación o dimisión."]},{"id":"au-07-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":9,"enunciado":"No están legitimados para convocar una reunión:","opciones":["Los Comités de Empresa.","Los empleados públicos en número inferior al cuarenta por ciento del colectivo convocado.","Los Delegados de Personal.","Las Juntas de Personal."],"bloque":"representacion","precepto":"Art. 46.1 del TREBEP","correcta":1,"justificaciones":["No. Los Comités de Empresa sí están legitimados (**art. 46.1.c**).","Es esta. Los empleados públicos solo pueden convocar si son al menos el 40 por 100 del colectivo; por debajo no están legitimados (**art. 46.1.d**).","No. Los Delegados de Personal sí están legitimados (**art. 46.1.a**).","No. Las Juntas de Personal sí están legitimadas (**art. 46.1.b**)."]},{"id":"au-07-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":10,"enunciado":"Las Juntas de Personal se elegirán mediante:","opciones":["Listas abiertas y sistema proporcional corregido.","Listas cerradas y sistema mayoritario.","Listas cerradas, a través de un sistema proporcional corregido.","Listas abiertas y sistema mayoritario."],"bloque":"representacion","precepto":"Art. 44.d del TREBEP","correcta":2,"justificaciones":["No. El sistema proporcional corregido es el de las Juntas, pero con listas cerradas, no abiertas.","No. Las listas cerradas son las de las Juntas, pero con sistema proporcional corregido, no mayoritario.","Es esta. Las Juntas de Personal se eligen mediante listas cerradas a través de un sistema proporcional corregido (**art. 44.d**).","No. Listas abiertas y sistema mayoritario es la fórmula de los Delegados de Personal."]},{"id":"au-07-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":11,"enunciado":"El reglamento y las modificaciones de las Juntas de Personal deberán ser aprobados:","opciones":["Por los votos favorables de, al menos, dos tercios de sus miembros.","Por los votos favorables de la mayoría simple de sus miembros.","Por los votos favorables de tres quintos de sus miembros.","Por los votos favorables de la mayoría absoluta de sus miembros."],"bloque":"representacion","precepto":"Art. 39.6 del TREBEP","correcta":0,"justificaciones":["Es esta. El reglamento y sus modificaciones deben aprobarse por al menos dos tercios de los miembros (**art. 39.6**).","No. No basta la mayoría simple.","No. Tres quintos no es la mayoría que fija el artículo.","No. No basta la mayoría absoluta: se exigen dos tercios."]},{"id":"au-07-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":12,"enunciado":"Las reuniones en el centro de trabajo:","opciones":["No se autorizarán fuera de las horas de trabajo en ningún supuesto.","No se autorizarán fuera de las horas de trabajo salvo acuerdo entre el órgano competente en materia de personal y quienes estén legitimados para convocarlas.","Se autorizarán fuera de las horas de trabajo, con expresa autorización del órgano competente en materia de personal.","Se autorizarán fuera de las horas de trabajo, salvo acuerdo entre el órgano competente en materia de personal y quienes estén legitimados para convocarlas."],"bloque":"representacion","precepto":"Art. 46.2 del TREBEP","correcta":3,"justificaciones":["No. Sí se autorizan fuera de las horas de trabajo si hay acuerdo con el órgano competente en materia de personal.","No. Invierte la regla: lo que se autoriza fuera de las horas de trabajo es lo normal, y el acuerdo permite lo contrario.","No. No se exige una autorización expresa: la regla general ya es que se autoricen fuera de las horas de trabajo.","Es esta. Se autorizan fuera de las horas de trabajo, salvo acuerdo entre el órgano competente en materia de personal y quienes estén legitimados para convocarlas (**art. 46.2**)."]},{"id":"au-07-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":13,"enunciado":"¿Por cuántos representantes estará formada la Junta de Personal en unidades electorales que cuenten con 501 funcionarios?","opciones":["Trece.","Diecisiete.","Veintiuno.","Once."],"bloque":"representacion","precepto":"Art. 39.5 del TREBEP","correcta":1,"justificaciones":["No. Trece es el tramo de 251 a 500 funcionarios.","Es esta. Con 501 funcionarios se entra en el tramo de 501 a 750, que tiene 17 representantes (**art. 39.5**).","No. Veintiuno es el tramo de 751 a 1.000 funcionarios.","No. Once no figura en la escala."]},{"id":"au-07-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":14,"enunciado":"La legitimación para iniciar, como interesados, los correspondientes procedimientos administrativos y ejercitar las acciones en vía administrativa o judicial en todo lo relativo al ámbito de sus funciones se reconoce a:","opciones":["Las Juntas de Personal, mancomunadamente por decisión unánime de sus miembros.","Los Delegados de personal, solidariamente.","Las Juntas de Personal, colegiadamente, por decisión mayoritaria de sus miembros y, en su caso, los Delegados de Personal, mancomunadamente.","Las Juntas de Personal, solidariamente, y Delegados de personal por decisión de la mayoría de sus miembros."],"bloque":"representacion","precepto":"Art. 40.2 del TREBEP","correcta":2,"justificaciones":["No. Las Juntas actúan colegiadamente y por mayoría, no mancomunadamente ni por unanimidad.","No. Los Delegados de Personal actúan mancomunadamente, no solidariamente.","Es esta. Las Juntas de Personal, colegiadamente por decisión mayoritaria, y los Delegados, mancomunadamente, están legitimados para iniciar procedimientos y ejercitar acciones (**art. 40.2**).","No. Mezcla los términos: las Juntas actúan colegiadamente y los Delegados, mancomunadamente."]},{"id":"au-07-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 7) - arts. 39 a 46","n":15,"enunciado":"Según el TREBEP, señale la respuesta correcta en relación con la solución de conflictos colectivos:","opciones":["Las propuestas de solución que ofrezcan el mediador o mediadores podrán ser rechazadas por las partes.","Las propuestas de solución que ofrezcan el mediador o mediadores serán obligatoriamente aceptadas por las partes.","El procedimiento de arbitraje será libremente acordado por las partes sin comprometerse a aceptar el resultado del mismo.","El acuerdo logrado a través de la mediación o de la resolución de arbitraje carece de eficacia jurídica."],"bloque":"representacion","precepto":"Art. 45 del TREBEP","correcta":0,"justificaciones":["Es esta. Las propuestas del mediador pueden ser libremente aceptadas o rechazadas por las partes (**art. 45.3**).","No. No son obligatorias: las partes son libres de aceptarlas o rechazarlas.","No. En el arbitraje las partes se comprometen de antemano a aceptar el contenido de la resolución (**art. 45.3**).","No. El acuerdo logrado por mediación o arbitraje tiene la misma eficacia jurídica que los Pactos y Acuerdos (**art. 45.4**)."]},{"id":"au-08-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":1,"enunciado":"Según el TREBEP, cuando las situaciones de permiso de maternidad, incapacidad temporal, riesgo durante la lactancia o riesgo durante el embarazo impidan iniciar el disfrute de las vacaciones dentro del año natural al que correspondan, o una vez iniciado el periodo vacacional sobreviniera una de dichas situaciones, el periodo vacacional se podrá disfrutar aunque haya terminado el año natural a que correspondan y siempre que no hayan transcurrido:","opciones":["Más de doce meses a partir del final del año en que se hayan originado.","Más de dieciocho meses a partir del final del año en que se hayan originado.","Doce meses desde la fecha en que fue autorizado el disfrute del permiso o licencia interrumpido.","Los veintidós días hábiles correspondientes al periodo de vacaciones legalmente reconocido."],"bloque":"jornada","precepto":"Art. 50.2 del TREBEP","correcta":1,"justificaciones":["No. El plazo es de dieciocho meses, no de doce.","Es esta. Las vacaciones se pueden disfrutar aunque haya terminado el año natural, siempre que no hayan pasado más de dieciocho meses desde el final del año en que se originó la situación (**art. 50.2**).","No. El plazo no se cuenta desde la autorización de un permiso interrumpido, sino desde el final del año en que se originó la situación.","No. Los veintidós días hábiles son la duración de las vacaciones (**art. 50.1**), no el plazo para disfrutarlas."]},{"id":"au-08-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":2,"enunciado":"De acuerdo con el TREBEP, los funcionarios tendrán derecho al siguiente permiso:","opciones":["Por fallecimiento de familiar de segundo grado de afinidad en la misma localidad, dos días.","Por el nacimiento de hijos prematuros que deban permanecer hospitalizados, dos días.","Por enfermedad grave de familiar de primer grado de consanguinidad en la misma localidad, dos días.","Por traslado de domicilio con cambio de residencia, un día."],"bloque":"jornada","precepto":"Art. 48.a del TREBEP","correcta":0,"justificaciones":["Es esta. El fallecimiento de un familiar de segundo grado de consanguinidad o afinidad da dos días hábiles si es en la misma localidad y cuatro si es en otra (**art. 48.a**).","No. En el nacimiento de hijos prematuros hospitalizados el permiso es de hasta dos horas diarias, no dos días (**art. 48.g**).","No. Para un familiar de primer grado con enfermedad grave son cinco días hábiles (**art. 48.a**), no dos.","No. El traslado de domicilio da un día, pero sin cambio de residencia (**art. 48.b**)."]},{"id":"au-08-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":3,"enunciado":"Según el artículo 48 del Texto Refundido del Estatuto Básico del Empleado Público, los funcionarios públicos tendrán un permiso por asuntos particulares de:","opciones":["Ocho días al año.","Cuatro días al año.","Cinco días al año.","Seis días al año."],"bloque":"jornada","precepto":"Art. 48.k del TREBEP","correcta":3,"justificaciones":["No. Son seis días, no ocho.","No. Son seis días, no cuatro.","No. Son seis días, no cinco.","Es esta. El permiso por asuntos particulares es de seis días al año (**art. 48.k**)."]},{"id":"au-08-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":4,"enunciado":"Según el TREBEP, el funcionario tendrá derecho a reducir la jornada hasta un 50% por razones de enfermedad muy grave de un familiar de primer grado y la duración de la reducción de jornada será de un mes. Durante dicho período percibirá:","opciones":["Sus retribuciones íntegras.","Las retribuciones básicas, pero no las complementarias","Las retribuciones complementarias, pero no las básicas.","Las retribuciones básicas y el complemento de destino, exclusivamente."],"bloque":"jornada","precepto":"Art. 48.i del TREBEP","correcta":0,"justificaciones":["Es esta. La reducción de hasta el 50 por ciento por enfermedad muy grave de un familiar de primer grado es con carácter retribuido, así que se perciben las retribuciones íntegras (**art. 48.i**).","No. No se pierden las complementarias: la reducción es retribuida.","No. No se pierden las básicas: la reducción es retribuida.","No. No se limita a básicas y complemento de destino: las retribuciones son íntegras."]},{"id":"au-08-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":5,"enunciado":"De acuerdo con el TREBEP, el permiso por lactancia se prevé para el caso de hijos menores de:","opciones":["Nueve meses.","Dieciocho meses.","Seis meses.","Doce meses."],"bloque":"jornada","precepto":"Art. 48.f del TREBEP","correcta":3,"justificaciones":["No. El permiso es para hijos menores de doce meses, no de nueve.","No. El permiso es para hijos menores de doce meses, no de dieciocho.","No. El permiso es para hijos menores de doce meses, no de seis.","Es esta. La lactancia se prevé para hijos menores de doce meses (**art. 48.f**)."]},{"id":"au-08-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":6,"enunciado":"De acuerdo con el TREBEP, los funcionarios tendrán derecho al siguiente permiso:","opciones":["Por el nacimiento de hijos prematuros trece semanas.","Por enfermedad grave de familiar de primer grado de consanguinidad en la misma localidad, cuatro días.","Por matrimonio, quince días.","Por traslado de domicilio con cambio de residencia, un día"],"bloque":"jornada","precepto":"Art. 48.l del TREBEP","correcta":2,"justificaciones":["No. Para hijos prematuros hospitalizados el permiso es de hasta dos horas diarias (**art. 48.g**). Las trece semanas son una ampliación del permiso por nacimiento (**art. 49**).","No. Para un familiar de primer grado con enfermedad grave son cinco días hábiles, no cuatro (**art. 48.a**).","Es esta. Por matrimonio o constitución de pareja de hecho formalizada por documento público, quince días (**art. 48.l**).","No. El traslado de domicilio da un día, pero sin cambio de residencia (**art. 48.b**)."]},{"id":"au-08-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":7,"enunciado":"De acuerdo con el TREBEP, las Administraciones Públicas podrán establecer hasta dos días adicionales de permiso por asuntos particulares al cumplir el:","opciones":["Quinto trienio, incrementándose en un día adicional por cada trienio cumplido a partir del séptimo.","Sexto trienio, incrementándose en un día adicional por cada trienio cumplido a partir del octavo.","Cuarto trienio, incrementándose en un día adicional por cada trienio cumplido a partir del séptimo.","Sexto trienio, incrementándose en un día adicional por cada trienio cumplido a partir del séptimo."],"bloque":"jornada","precepto":"Disposición adicional decimotercera del TREBEP","correcta":1,"justificaciones":["No. Los dos días adicionales se pueden establecer al cumplir el sexto trienio, no el quinto.","Es esta. Hasta dos días adicionales al cumplir el sexto trienio, con un día más por cada trienio cumplido a partir del octavo (**disposición adicional decimotercera**).","No. No es el cuarto trienio, sino el sexto, ni el incremento arranca en el séptimo.","No. El sexto trienio es correcto, pero el incremento arranca a partir del octavo, no del séptimo."]},{"id":"au-08-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":8,"enunciado":"Según el TREBEP, por nacimiento de hijos prematuros, o que por cualquier otra causa deban permanecer hospitalizados después del parto, la funcionaria o funcionario tiene derecho a ausentarse del trabajo:","opciones":["Durante un máximo de tres horas diarias percibiendo las retribuciones integras.","Durante un máximo de dos horas diarias percibiendo las retribuciones integras.","Durante un máximo de tres horas diarias sin derecho a retribución de las mismas.","Durante un máximo de dos horas diarias sin derecho a retribución de las mismas."],"bloque":"jornada","precepto":"Art. 48.g del TREBEP","correcta":1,"justificaciones":["No. El máximo es de dos horas diarias, no de tres.","Es esta. Hasta dos horas diarias, percibiendo las retribuciones íntegras (**art. 48.g**).","No. Son dos horas, no tres, y se perciben las retribuciones íntegras.","No. Las dos horas son correctas, pero con las retribuciones íntegras."]},{"id":"au-08-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":9,"enunciado":"Señale la afirmación correcta con relación a los permisos de los funcionarios públicos:","opciones":["El permiso por lactancia de un hijo menor de 12 meses ha de ser disfrutado necesariamente por la madre funcionaria.","La funcionaria podrá solicitar la sustitución del tiempo de lactancia por un permiso no retribuido.","Por lactancia, la reducción de la jornada ha de ser necesariamente de media hora al inicio y al final de la jornada.","El permiso de lactancia se incrementará proporcionalmente en los casos de parto múltiple."],"bloque":"jornada","precepto":"Art. 48.f del TREBEP","correcta":3,"justificaciones":["No. Es un derecho individual de los funcionarios, sea madre u otro progenitor, lo que no se puede es transferirlo (**art. 48.f**).","No. Lo que se puede solicitar es sustituir la lactancia por un permiso retribuido que acumule el tiempo en jornadas completas, no por uno no retribuido.","No. Puede ser una hora de ausencia dividida en dos fracciones, o una reducción de media hora al inicio y al final, o de una hora al inicio o al final.","Es esta. El permiso se incrementa proporcionalmente en los casos de parto, adopción, guarda con fines de adopción o acogimiento múltiple (**art. 48.f**)."]},{"id":"au-08-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":10,"enunciado":"De acuerdo con el TREBEP, si fuese necesario el desplazamiento previo de los progenitores al país de origen del adoptado, en los casos de adopción o acogimiento internacional, se tendrá derecho a un permiso de hasta:","opciones":["1 mes.","2 meses.","3 meses.","6 meses."],"bloque":"jornada","precepto":"Art. 49.b del TREBEP","correcta":1,"justificaciones":["No. El permiso es de hasta dos meses, no uno.","Es esta. Si hace falta el desplazamiento previo al país de origen del adoptado, hay un permiso de hasta dos meses (**art. 49.b**).","No. El permiso es de hasta dos meses, no tres.","No. El permiso es de hasta dos meses, no seis."]},{"id":"au-08-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":11,"enunciado":"Durante el desplazamiento previo al país de origen para adopción, se tendrá derecho a:","opciones":["Percibir las retribuciones íntegras.","Percibir solo las retribuciones básicas.","Percibir dietas de desplazamientos.","Las respuestas a y c con correctas."],"bloque":"jornada","precepto":"Art. 49.b del TREBEP","correcta":1,"justificaciones":["No. Durante ese permiso no se perciben las retribuciones íntegras, solo las básicas.","Es esta. Durante el permiso de hasta dos meses para el desplazamiento se perciben exclusivamente las retribuciones básicas (**art. 49.b**).","No. El artículo no prevé dietas de desplazamiento para este permiso.","No. Combina la a y la c, y ninguna de las dos es cierta."]},{"id":"au-08-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":12,"enunciado":"En materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica lactancia, el personal laboral al servicio de las Administraciones públicas se regirá:","opciones":["Por el texto refundido de la Ley del Estatuto de los Trabajadores.","Por el texto refundido de la Ley del Estatuto Básico del Empleado Público.","Por el Real Decreto 364/95 del 10 de marzo.","El contrato de trabajo."],"bloque":"jornada","precepto":"Art. 7 del TREBEP","correcta":1,"ojo":"Antes de la reforma del art. 7, estos permisos del personal laboral se regían por el Estatuto de los Trabajadores. Ahora el art. 7 manda aplicar el Estatuto Básico y excluye las suspensiones del Estatuto de los Trabajadores.","revisar":"Respondida con el texto vigente del art. 7. Si el profesor corrige con la redacción antigua, la clave sería la opción 0.","justificaciones":["No. El **art. 7** dice que no se les aplican las previsiones del Estatuto de los Trabajadores sobre las suspensiones de contrato por esos supuestos.","Es esta. En materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica, lactancia y parental, el personal laboral se rige por el Estatuto Básico (**art. 7**).","No. El Real Decreto 364/1995 es el reglamento de ingreso del personal de la Administración General del Estado, no regula estos permisos.","No. El contrato de trabajo no es la fuente que el **art. 7** fija para estos permisos."]},{"id":"au-08-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":13,"enunciado":"En relación con el permiso de lactancia de un menor de 12 meses, recogido en el TREBEP, ¿puede transferirse su ejercicio al otro progenitor:","opciones":["Sí.","No, ya que constituye un derecho individual de los funcionarios.","Solo durante el primer mes.","Solo la mitad del mismo."],"bloque":"jornada","precepto":"Art. 48.f del TREBEP","correcta":1,"justificaciones":["No. El permiso no puede transferirse al otro progenitor, adoptante, guardador o acogedor.","Es esta. Es un derecho individual de los funcionarios, sin que pueda transferirse su ejercicio al otro progenitor (**art. 48.f**).","No. No se puede transferir ni siquiera durante el primer mes.","No. No se puede transferir ni la mitad."]},{"id":"au-08-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":14,"enunciado":"Sobre el permiso por nacimiento para la madre biológica, ¿cuántas semanas inmediatas posteriores al parto serán en todo caso de descanso obligatorio e ininterrumpido?","opciones":["6 semanas.","4 semanas.","16 semanas.","No queda establecido en el TREBEP."],"bloque":"jornada","precepto":"Art. 49.a del TREBEP","correcta":0,"justificaciones":["Es esta. Las seis semanas ininterrumpidas inmediatamente posteriores al parto son obligatorias y se disfrutan a jornada completa (**art. 49.a**).","No. El descanso obligatorio es de seis semanas, no cuatro.","No. Dieciséis semanas no es el descanso obligatorio: son seis, de las diecinueve del permiso.","No. Sí lo establece: seis semanas (**art. 49.a**)."]},{"id":"au-08-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 8) - arts. 47 a 51","n":15,"enunciado":"Sobre el permiso por nacimiento para la madre biológica, recogido en el TREBEP, ¿cuándo se podrá participar en los cursos de formación que convoque la Administración?","opciones":["Una vez finalice el periodo de descanso obligatorio.","En cualquier momento.","A las 16 semanas.","No se puede realizar hasta la incorporación efectiva en su puesto de trabajo."],"bloque":"jornada","precepto":"Art. 49.a del TREBEP","correcta":0,"justificaciones":["Es esta. Durante el permiso se puede participar en los cursos de formación una vez finalizado el período de descanso obligatorio (**art. 49.a**).","No. No es en cualquier momento: hay que haber terminado el descanso obligatorio de seis semanas.","No. No se espera a las dieciséis semanas: basta con que haya terminado el descanso obligatorio.","No. No hay que esperar a la incorporación efectiva: se puede durante el permiso, tras el descanso obligatorio."]},{"id":"au-09-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":1,"enunciado":"Señale la respuesta incorrecta en relación con el permiso de los funcionarios públicos consistente en una reducción de la jornada para atender al cuidado de un familiar por razones de enfermedad muy grave:","opciones":["El permiso da derecho a solicitar una reducción de hasta el cincuenta por ciento de la jornada laboral, con carácter retribuido.","No tiene plazo máximo.","Debe tratarse de un familiar de primer grado.","Si hubiera más de un titular de este derecho por el mismo hecho causante, el tiempo de disfrute de esta reducción se podrá prorratear entre los mismos, respetando en todo caso, el plazo máximo de un mes."],"bloque":"jornada","precepto":"Art. 48.i del TREBEP","correcta":1,"justificaciones":["Es verdadera, así que no se marca. Es una reducción de hasta el cincuenta por ciento de la jornada, con carácter retribuido (**art. 48.i**).","Esta es la falsa, y por eso es la que hay que marcar. Sí tiene plazo máximo: un mes (**art. 48.i**).","Es verdadera, así que no se marca. El familiar debe ser de primer grado.","Es verdadera, así que no se marca. Si hay varios titulares, el tiempo se prorratea respetando el máximo de un mes."]},{"id":"au-09-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":2,"enunciado":"Según el artículo 48 del TREBEP, por nacimiento de hijos prematuros que deban permanecer hospitalizados a continuación del parto, la funcionaria o el funcionario tendrá derecho a reducir su jornada de trabajo:","opciones":["Hasta un máximo de cuatro horas, con la disminución proporcional de sus retribuciones.","Hasta un máximo de dos horas, con la disminución proporcional de sus retribuciones.","Hasta un máximo de dos horas, percibiendo las retribuciones integras.","Hasta un máximo de cuatro horas, percibiendo las retribuciones integras."],"bloque":"jornada","precepto":"Art. 48.g del TREBEP","correcta":1,"justificaciones":["No. El máximo es de dos horas, no de cuatro.","Es esta. Pueden reducir la jornada hasta un máximo de dos horas, con la disminución proporcional de las retribuciones (**art. 48.g**).","No. Las dos horas con retribuciones íntegras son la ausencia del trabajo, no la reducción de jornada, que se reduce proporcionalmente.","No. El máximo es de dos horas, no de cuatro."]},{"id":"au-09-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":3,"enunciado":"Señale la respuesta correcta, conforme al TREBEP. Cuando los funcionarios que hayan hecho uso del permiso por nacimiento, adopción, guarda con fines de adopción o acogimiento, tanto temporal como permanente, se reincorporen:","opciones":["Tendrán derecho a reintegrarse en su puesto de trabajo.","Tendrán derecho a reintegrarse en otro puesto de trabajo en la misma provincia.","Tendrán derecho a reintegrarse en otro puesto de trabajo en el mismo municipio.","Tendrán derecho a reintegrarse en un puesto con carácter provisional, en tanto obtienen otro con carácter definitivo."],"bloque":"jornada","precepto":"Art. 49 del TREBEP","correcta":0,"justificaciones":["Es esta. Tienen derecho a reintegrarse a su puesto de trabajo en términos y condiciones no menos favorables al disfrute del permiso (**art. 49**).","No. El derecho es a su puesto de trabajo, no a otro de la misma provincia.","No. El derecho es a su puesto de trabajo, no a otro del mismo municipio.","No. No se les reintegra de forma provisional: vuelven a su puesto."]},{"id":"au-09-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":4,"enunciado":"De acuerdo con el TREBEP, la funcionaria pública víctima de violencia de género mantendrá sus retribuciones íntegras:","opciones":["Cuando reduzca su jornada en un tercio o menos.","Cuando reduzca su jornada en un cuarto o menos.","Cuando reduzca su jornada, sin importar el porcentaje de reducción.","Cuando reduzca su jornada en menos de un 50 %."],"bloque":"jornada","precepto":"Art. 49.d del TREBEP","correcta":0,"justificaciones":["Es esta. La funcionaria víctima de violencia de género mantiene las retribuciones íntegras cuando reduce su jornada en un tercio o menos (**art. 49.d**).","No. El umbral es un tercio, no un cuarto.","No. Si reduce más de un tercio, la retribución disminuye proporcionalmente.","No. El umbral es un tercio, no el cincuenta por ciento."]},{"id":"au-09-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":5,"enunciado":"Señale la respuesta correcta en relación con el permiso por acogimiento, tanto temporal como permanente:","opciones":["Este permiso tendrá una duración de dieciocho semanas ininterrumpidas.","Durante el disfrute de este permiso no se podrá participar en los cursos de formación que convoque la Administración.","Este permiso podrá iniciarse hasta dos semanas antes de la decisión administrativa o judicial de acogimiento.","El acogimiento temporal deberá tener una duración no inferior a un año."],"bloque":"jornada","precepto":"Art. 49.b del TREBEP","correcta":3,"justificaciones":["No. Dura diecinueve semanas, no dieciocho, y no todas son ininterrumpidas: solo las seis primeras.","No. Una vez finalizado el descanso obligatorio sí se puede participar en cursos de formación.","No. Puede iniciarse hasta cuatro semanas antes de la decisión, no dos.","Es esta. El acogimiento temporal debe tener una duración no inferior a un año (**art. 49.b**)."]},{"id":"au-09-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":6,"enunciado":"De acuerdo con el TREBEP, los funcionarios tendrán derecho a un permiso de seis días al año:","opciones":["Por razones de guarda legal, cuando el funcionario tenga el cuidado directo de algún menor de doce años.","Para realizar funciones sindicales o de representación del personal.","Por asuntos particulares.","Para concurrir a exámenes finales y demás pruebas definitivas de aptitud."],"bloque":"jornada","precepto":"Art. 48.k del TREBEP","correcta":2,"justificaciones":["No. La guarda legal da derecho a reducción de jornada, no a seis días (**art. 48.h**).","No. Las funciones sindicales o de representación se conceden en los términos que se determinen (**art. 48.c**).","Es esta. Por asuntos particulares son seis días al año (**art. 48.k**).","No. Para exámenes finales el permiso dura los días de su celebración (**art. 48.d**)."]},{"id":"au-09-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":7,"enunciado":"Según el artículo 49 del TREBEP, en el supuesto de discapacidad del hijo o hija, el permiso del progenitor diferente de la madre biológica por nacimiento:","opciones":["Se ampliará para ambos progenitores en cuatro semanas más, dos para cada uno de los progenitores.","Se ampliará para ambos progenitores en una semana más.","Se ampliará en dos semanas más, que deberán disfrutarse de forma ininterrumpida.","Se ampliará para ambos progenitores en dos semanas más, una para cada uno de los progenitores."],"bloque":"jornada","precepto":"Art. 49.c del TREBEP","correcta":3,"justificaciones":["No. Son dos semanas en total, una para cada progenitor, no cuatro.","No. Son dos semanas, no una.","No. La ampliación es para ambos progenitores, una semana cada uno, y no se exige que sea ininterrumpida.","Es esta. Se amplía para ambos progenitores en dos semanas más, una para cada uno (**art. 49.c**)."]},{"id":"au-09-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":8,"enunciado":"Señale la respuesta incorrecta en relación con el permiso de los funcionarios públicos por razones de lactancia:","opciones":["Este derecho podrá sustituirse por una reducción de la jornada normal en media hora al inicio y al final de la jornada.","Este permiso constituye un derecho individual de los funcionarios, sin que pueda transferirse su ejercicio al otro progenitor.","Si el hijo fuera menor de 18 meses tendrá derecho a una hora de ausencia del trabajo que podrá dividir en dos fracciones.","Este derecho podrá sustituirse por una reducción de la jornada normal en una hora al inicio o al final de la jornada."],"bloque":"jornada","precepto":"Art. 48.f del TREBEP","correcta":2,"justificaciones":["Es verdadera, así que no se marca. Se puede sustituir por una reducción de media hora al inicio y al final.","Es verdadera, así que no se marca. Es un derecho individual y no se puede transferir al otro progenitor.","Esta es la falsa, y por eso es la que hay que marcar. El permiso es para hijos menores de doce meses, no de dieciocho (**art. 48.f**).","Es verdadera, así que no se marca. También se puede sustituir por una reducción de una hora al inicio o al final."]},{"id":"au-09-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":9,"enunciado":"Según el TREBEP, ¿de cuántos días de permiso podría disfrutar un funcionario de carrera en caso de intervención quirúrgica sin hospitalización del padre de su cónyuge?","opciones":["5 días hábiles.","4 días hábiles.","3 días hábiles.","Este supuesto no origina derecho a permiso alguno."],"bloque":"jornada","precepto":"Art. 48.a del TREBEP","correcta":0,"justificaciones":["Es esta. El suegro es familiar de primer grado por afinidad, y la intervención quirúrgica sin hospitalización con reposo domiciliario da cinco días hábiles (**art. 48.a**).","No. Cuatro días hábiles es para familiares de segundo grado.","No. Tres días hábiles es el fallecimiento de un familiar de primer grado en la misma localidad.","No. Sí origina permiso: el padre del cónyuge es familiar de primer grado por afinidad."]},{"id":"au-09-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":10,"enunciado":"Señale la respuesta correcta en relación con las vacaciones de los funcionarios públicos:","opciones":["Por razones del servicio, el derecho a vacaciones podrá ser sustituido por una cuantía económica.","La renuncia voluntaria a la condición de funcionario implica la pérdida del derecho al disfrute de las vacaciones devengadas.","Los funcionarios tendrán derecho a disfrutar, durante cada año natural, de unas vacaciones retribuidas de 22 días naturales.","Cada Administración Pública podrá establecer hasta un máximo de cuatro días adicionales de vacaciones por antigüedad."],"bloque":"jornada","precepto":"Disposición adicional decimocuarta del TREBEP","correcta":3,"justificaciones":["No. Las vacaciones no pueden sustituirse por una cuantía económica (**art. 50.3**).","No. En la renuncia voluntaria debe garantizarse el disfrute de las vacaciones devengadas (**art. 50.3**).","No. Son veintidós días hábiles, no naturales (**art. 50.1**).","Es esta. Cada Administración puede establecer hasta cuatro días adicionales de vacaciones por tiempo de servicios (**disposición adicional decimocuarta**)."]},{"id":"au-09-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":11,"enunciado":"Conforme al TREBEP, en caso de enfermedad grave de un familiar de segundo grado de consanguinidad, en distinta localidad, el funcionario tendrá derecho a un permiso de:","opciones":["Tres días hábiles.","Cuatro días hábiles.","Seis días hábiles.","Cinco días hábiles."],"bloque":"jornada","precepto":"Art. 48.a del TREBEP","correcta":1,"justificaciones":["No. Son cuatro días hábiles, no tres.","Es esta. Para un familiar de segundo grado con enfermedad grave el permiso es de cuatro días hábiles (**art. 48.a**).","No. Seis días hábiles no figura en el artículo.","No. Cinco días hábiles es para familiares de primer grado."]},{"id":"au-09-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":12,"enunciado":"Conforme al TREBEP, las funcionarias víctimas de violencia sobre la mujer, con la finalidad de hacer efectiva su protección o derecho de asistencia social integral, tendrán derecho a:","opciones":["La reducción de la jornada sin disminución proporcional de la retribución.","La reordenación del tiempo de trabajo.","Un permiso retribuido de hasta seis meses.","Todas las respuestas son correctas."],"bloque":"jornada","precepto":"Art. 49.d del TREBEP","correcta":1,"justificaciones":["No. La reducción de jornada es con disminución proporcional de la retribución.","Es esta. Tienen derecho a la reordenación del tiempo de trabajo, adaptando el horario o con horario flexible (**art. 49.d**).","No. No existe un permiso retribuido de hasta seis meses en este artículo.","No. Solo es correcta la reordenación del tiempo de trabajo."]},{"id":"au-09-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":13,"enunciado":"Indique cuál de los siguientes es un permiso de los funcionarios recogido en el TREBEP:","opciones":["Por asuntos particulares, ocho días al año.","Por matrimonio, quince días hábiles.","Por deberes relacionados con la conciliación de la vida familiar y laboral, tres días al año.","Por razones de guarda legal, reducción de su jornada de trabajo, con la disminución de retribuciones que corresponda."],"bloque":"jornada","precepto":"Art. 48.h del TREBEP","correcta":3,"justificaciones":["No. Por asuntos particulares son seis días, no ocho (**art. 48.k**).","No. Por matrimonio son quince días, sin la precisión de hábiles (**art. 48.l**).","No. Los deberes de conciliación dan el tiempo indispensable, sin fijar tres días al año (**art. 48.j**).","Es esta. Por razones de guarda legal hay reducción de jornada, con la disminución de retribuciones que corresponda (**art. 48.h**)."]},{"id":"au-09-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":14,"enunciado":"Para atender a un hijo menor de edad afectado por una enfermedad grave que implique ingreso hospitalario de larga duración y que requiera de su cuidado directo, continuo y permanente, el funcionario tendrá derecho a una reducción de:","opciones":["Al menos el 50% de la jornada laboral, con carácter retribuido y como máximo hasta que el menor cumpla 23 años de edad.","Al menos el 50% de la jornada laboral, con carácter retribuido y por el plazo máximo de un mes.","Hasta el 50% de la jornada laboral, con carácter retribuido y por el plazo máximo de un mes.","Hasta el 50% de la jornada laboral, con carácter retribuido y como máximo hasta que el menor cumpla 23 años de edad."],"bloque":"jornada","precepto":"Art. 49.e del TREBEP","correcta":0,"justificaciones":["Es esta. Reducción de al menos la mitad de la jornada, con retribuciones íntegras, como máximo hasta que el menor cumpla 23 años (**art. 49.e**).","No. El plazo de un mes es el de la reducción por enfermedad muy grave de un familiar (**art. 48.i**).","No. Es de al menos la mitad, no hasta la mitad, y el plazo de un mes es de otro permiso.","No. Es de al menos la mitad, no hasta la mitad."]},{"id":"au-09-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 9) - arts. 47 a 51","n":15,"enunciado":"¿Cuál será la duración del permiso del progenitor diferente de la madre biológica por nacimiento, guarda con fines de adopción, acogimiento o adopción de un hijo o hija, de conformidad con lo previsto en el TREBEP?","opciones":["16 semanas.","19 semanas.","17 semanas.","8 semanas."],"bloque":"jornada","precepto":"Art. 49.c del TREBEP","correcta":1,"justificaciones":["No. Dieciséis semanas era la duración anterior.","Es esta. Tiene una duración de diecinueve semanas (**art. 49.c**).","No. Diecisiete semanas no figura en el artículo.","No. Ocho semanas es la duración máxima del permiso parental (**art. 49.g**)."]},{"id":"au-10-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 10) - arts. 52 a 54","n":1,"enunciado":"Señale cuál de los siguientes es uno de los principios éticos de los empleados públicos recogidos en el artículo 53 del TREBEP:","opciones":["Tratar con atención y respeto a los ciudadanos, superiores y restantes empleados públicos.","Mantener actualizada su formación y cualificación.","Actuar de acuerdo con los principios de eficacia, economía y eficiencia.","Observar las normas sobre seguridad y salud laboral."],"bloque":"deberes","precepto":"Art. 53.8 del TREBEP","correcta":2,"justificaciones":["No. Tratar con atención y respeto es un principio de conducta (**art. 54.1**).","No. Mantener actualizada la formación es un principio de conducta (**art. 54.8**).","Es esta. Actuar de acuerdo con eficacia, economía y eficiencia es un principio ético (**art. 53.8**).","No. Observar las normas de seguridad y salud laboral es un principio de conducta (**art. 54.9**)."]},{"id":"au-10-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 10) - arts. 52 a 54","n":2,"enunciado":"Señale cuál de los siguientes es uno de los principios de conducta de los empleados públicos según el artículo 54 del TREBEP:","opciones":["Cumplir con diligencia las tareas que les correspondan o se les encomienden.","Respetar la Constitución y el resto de normas que integran el ordenamiento jurídico.","Ajustar su actuación a los principios de lealtad y buena fe con la Administración en la que presten sus servicios.","Garantizar la atención al ciudadano en la lengua que lo solicite siempre que sea oficial en el territorio."],"bloque":"deberes","precepto":"Art. 54.11 del TREBEP","correcta":3,"justificaciones":["No. Cumplir con diligencia las tareas es un principio ético (**art. 53.10**).","No. Respetar la Constitución es un principio ético (**art. 53.1**).","No. La lealtad y la buena fe son un principio ético (**art. 53.3**).","Es esta. Garantizar la atención al ciudadano en la lengua que lo solicite, si es oficial en el territorio, es un principio de conducta (**art. 54.11**)."]},{"id":"au-10-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 10) - arts. 52 a 54","n":3,"enunciado":"Según el artículo 53 del TREBEP, es un principio ético en la actuación de los empleados públicos:","opciones":["No aceptar ningún trato de favor o situación que implique privilegio o ventaja injustificada.","Rechazar cualquier regalo, favor o servicio en condiciones ventajosas más allá de los usos habituales, sociales y de cortesía.","Garantizar la constancia y permanencia de los documentos para su transmisión y entrega a sus posteriores responsables.","El desempeño de las tareas correspondientes a su puesto de trabajo de forma diligente."],"bloque":"deberes","precepto":"Art. 53.7 del TREBEP","correcta":0,"justificaciones":["Es esta. No aceptar ningún trato de favor o situación que implique privilegio o ventaja injustificada es un principio ético (**art. 53.7**).","No. Rechazar regalos y favores es un principio de conducta (**art. 54.6**).","No. Garantizar la constancia y permanencia de los documentos es un principio de conducta (**art. 54.7**).","No. Desempeñar las tareas de forma diligente es un principio de conducta (**art. 54.2**)."]},{"id":"au-10-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 10) - arts. 52 a 54","n":4,"enunciado":"Según el artículo 54 del TREBEP, es un principio de conducta en la actuación de los empleados públicos:","opciones":["Guardar secreto de las materias clasificadas u otras cuya difusión esté prohibida legalmente.","Informar a los ciudadanos sobre aquellas materias o asuntos que tengan derecho a conocer.","Abstenerse en aquellos asuntos en los que tengan un interés personal.","Ejercer sus atribuciones según el principio de dedicación al servicio público."],"bloque":"deberes","precepto":"Art. 54.4 del TREBEP","correcta":1,"justificaciones":["No. Guardar secreto de las materias clasificadas es un principio ético (**art. 53.12**).","Es esta. Informar a los ciudadanos sobre lo que tengan derecho a conocer es un principio de conducta (**art. 54.4**).","No. Abstenerse en asuntos de interés personal es un principio ético (**art. 53.5**).","No. La dedicación al servicio público es un principio ético (**art. 53.11**)."]},{"id":"au-10-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 10) - arts. 52 a 54","n":5,"enunciado":"Según el artículo 54 del TREBEP, es un principio de conducta en la actuación de los empleados públicos:","opciones":["Administrar los recursos y bienes públicos con austeridad.","Actuar de acuerdo con los principios de eficacia, economía y eficiencia.","No intervenir en negocios jurídicos con personas o entidades cuando pueda suponer un conflicto de intereses.","Ejercer sus atribuciones según el principio de dedicación al servicio público."],"bloque":"deberes","precepto":"Art. 54.5 del TREBEP","correcta":0,"justificaciones":["Es esta. Administrar los recursos y bienes públicos con austeridad es un principio de conducta (**art. 54.5**).","No. Eficacia, economía y eficiencia es un principio ético (**art. 53.8**).","No. No intervenir en negocios jurídicos con conflicto de intereses es un principio ético (**art. 53.6**).","No. La dedicación al servicio público es un principio ético (**art. 53.11**)."]},{"id":"au-10-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 10) - arts. 52 a 54","n":6,"enunciado":"Según el artículo 53 del TREBEP, es un principio ético en la actuación de los empleados públicos:","opciones":["Tratar con atención y respeto a los ciudadanos, a sus superiores y a los restantes empleados públicos.","Ajustar su actuación a los principios de lealtad y buena fe con la Administración en la que presten sus servicios.","Cumplir la jornada y el horario establecidos.","Obedecer las instrucciones y órdenes profesionales de los superiores."],"bloque":"deberes","precepto":"Art. 53.3 del TREBEP","correcta":1,"justificaciones":["No. Tratar con atención y respeto es un principio de conducta (**art. 54.1**).","Es esta. Ajustar la actuación a la lealtad y la buena fe con la Administración es un principio ético (**art. 53.3**).","No. Cumplir la jornada y el horario es un principio de conducta (**art. 54.2**).","No. Obedecer las instrucciones y órdenes profesionales es un principio de conducta (**art. 54.3**)."]},{"id":"au-10-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 10) - arts. 52 a 54","n":7,"enunciado":"Señale cuál de los siguientes NO es un principio ético del Código de conducta de los empleados públicos:","opciones":["No aceptarán ningún trato de favor o situación que implique privilegio o ventaja injustificada.","Ejercerán sus atribuciones según el principio de dedicación al servicio público.","Administrarán los recursos y bienes públicos con austeridad.","Su conducta se basará en el respeto de los derechos fundamentales y libertades públicas."],"bloque":"deberes","precepto":"Art. 54.5 del TREBEP","correcta":2,"justificaciones":["No. No aceptar trato de favor es un principio ético (**art. 53.7**).","No. La dedicación al servicio público es un principio ético (**art. 53.11**).","Es esta. Administrar los recursos con austeridad es un principio de conducta, no ético (**art. 54.5**).","No. El respeto de los derechos fundamentales es un principio ético (**art. 53.4**)."]},{"id":"au-10-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 10) - arts. 52 a 54","n":8,"enunciado":"Señale cuál de los siguientes es un principio ético del Código de conducta de los empleados públicos:","opciones":["Mantendrán actualizada su formación y cualificación.","Observarán las normas sobre seguridad y salud laboral.","Garantizarán la atención al ciudadano en la lengua que lo solicite siempre que sea oficial en el territorio.","Se abstendrán en aquellos asuntos en los que tengan un interés personal."],"bloque":"deberes","precepto":"Art. 53.5 del TREBEP","correcta":3,"justificaciones":["No. Mantener actualizada la formación es un principio de conducta (**art. 54.8**).","No. Observar las normas de seguridad y salud laboral es un principio de conducta (**art. 54.9**).","No. Garantizar la atención en la lengua que se solicite es un principio de conducta (**art. 54.11**).","Es esta. Abstenerse en asuntos de interés personal es un principio ético (**art. 53.5**)."]},{"id":"au-10-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 10) - arts. 52 a 54","n":9,"enunciado":"Señale cuál de los siguientes es un principio de conducta de los empleados públicos, conforme al artículo 54 del TREBEP:","opciones":["Respetarán la Constitución y el resto de normas que integran el ordenamiento jurídico.","Ajustarán su actuación a los principios de lealtad y buena fe con la Administración.","Informarán a los ciudadanos sobre aquellas materias o asuntos que tengan derecho a conocer.","Guardarán secreto de las materias clasificadas u otras cuya difusión esté prohibida legalmente."],"bloque":"deberes","precepto":"Art. 54.4 del TREBEP","correcta":2,"justificaciones":["No. Respetar la Constitución es un principio ético (**art. 53.1**).","No. La lealtad y la buena fe son un principio ético (**art. 53.3**).","Es esta. Informar a los ciudadanos sobre lo que tengan derecho a conocer es un principio de conducta (**art. 54.4**).","No. Guardar secreto de las materias clasificadas es un principio ético (**art. 53.12**)."]},{"id":"au-10-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 10) - arts. 52 a 54","n":10,"enunciado":"Señale cuál de los siguientes NO es un principio de conducta de los empleados públicos, conforme al artículo 54 del TREBEP:","opciones":["Su conducta se basará en el respeto de los derechos fundamentales y libertades públicas, evitando toda actuación que pueda producir discriminación.","Tratarán con atención y respeto a los ciudadanos, a sus superiores y a los restantes empleados públicos.","Se rechazará cualquier regalo, favor o servicio en condiciones ventajosas que vaya más allá de los usos habituales, sociales y de cortesía.","Obedecerán las instrucciones y órdenes profesionales de los superiores, salvo que constituyan una infracción manifiesta del ordenamiento jurídico."],"bloque":"deberes","precepto":"Art. 53.4 del TREBEP","correcta":0,"justificaciones":["Es esta. El respeto a los derechos fundamentales y la no discriminación es un principio ético, no de conducta (**art. 53.4**).","No. Tratar con atención y respeto es un principio de conducta (**art. 54.1**).","No. Rechazar regalos y favores es un principio de conducta (**art. 54.6**).","No. Obedecer las órdenes salvo infracción manifiesta es un principio de conducta (**art. 54.3**)."]},{"id":"au-11-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":1,"enunciado":"Según el artículo 55 del TREBEP, ¿cuál de los siguientes NO es un principio rector del acceso al empleo público?","opciones":["Publicidad de las convocatorias y de sus bases.","Transparencia.","Imparcialidad y profesionalidad de los miembros de los órganos de selección.","Objetividad técnica en la actuación de los órganos de selección."],"bloque":"acceso","precepto":"Art. 55.2 del TREBEP","correcta":3,"justificaciones":["No. La publicidad de las convocatorias y sus bases es un principio rector (**art. 55.2.a**).","No. La transparencia es un principio rector (**art. 55.2.b**).","No. La imparcialidad y profesionalidad de los órganos de selección es un principio rector (**art. 55.2.c**).","Es esta. El principio es la independencia y discrecionalidad técnica, no la objetividad técnica (**art. 55.2.d**)."]},{"id":"au-11-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":2,"enunciado":"La edad mínima establecida en el TREBEP para participar en procesos selectivos de acceso al empleo público es de:","opciones":["16 años.","18 años.","14 años.","20 años."],"bloque":"acceso","precepto":"Art. 56.1.c del TREBEP","correcta":0,"justificaciones":["Es esta. Hay que tener cumplidos dieciséis años (**art. 56.1.c**).","No. La edad mínima es de dieciséis años, no de dieciocho.","No. La edad mínima es de dieciséis años, no de catorce.","No. La edad mínima es de dieciséis años, no de veinte."]},{"id":"au-11-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":3,"enunciado":"¿Cuál de estos requisitos NO es exigible en relación con el acceso al empleo público, de acuerdo con lo previsto en el artículo 56 del Texto Refundido del Estatuto Básico del Empleado Público?","opciones":["Poseer la capacidad funcional para el desempeño de las tareas.","Tener cumplidos 18 años y no exceder en su caso, de la edad máxima de jubilación forzosa.","Poseer la titulación exigida.","Tener la nacionalidad española, sin perjuicio de lo dispuesto en el artículo 57 del TREBEP."],"bloque":"acceso","precepto":"Art. 56.1.c del TREBEP","correcta":1,"justificaciones":["No. La capacidad funcional sí se exige (**art. 56.1.b**).","Es esta. El TREBEP exige tener cumplidos dieciséis años, no dieciocho (**art. 56.1.c**).","No. La titulación exigida sí se exige (**art. 56.1.e**).","No. La nacionalidad española sí se exige, sin perjuicio del art. 57 (**art. 56.1.a**)."]},{"id":"au-11-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":4,"enunciado":"El artículo 59 del TREBEP regula el cupo de plazas para reservar, en las Ofertas de Empleo Público, a personas con discapacidad. Este cupo será:","opciones":["No inferior al cinco por ciento de las vacantes.","No inferior al siete por ciento de las vacantes.","No superior al cinco por ciento de las vacantes.","No superior al siete por ciento de las vacantes."],"bloque":"acceso","precepto":"Art. 59.1 del TREBEP","correcta":1,"justificaciones":["No. El cupo es del siete por ciento, no del cinco.","Es esta. Se reserva un cupo no inferior al siete por ciento de las vacantes (**art. 59.1**).","No. Es un mínimo, no un máximo, y la cifra es siete.","No. Es un mínimo, no un máximo."]},{"id":"au-11-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":5,"enunciado":"Conforme al artículo 59 del TREBEP, la reserva de vacantes se realizará de manera que las personas que acrediten discapacidad intelectual puedan cubrir:","opciones":["Al menos, el dos por ciento de las plazas ofertadas.","Al menos, el tres por ciento de las plazas ofertadas.","Al menos, el cinco por ciento de las plazas ofertadas.","Al menos, el siete por ciento de las plazas ofertadas."],"bloque":"acceso","precepto":"Art. 59.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Al menos el dos por ciento de las plazas ofertadas es para personas con discapacidad intelectual (**art. 59.1**).","No. El mínimo es del dos por ciento, no del tres.","No. El cinco por ciento no figura en el artículo.","No. El siete por ciento es el cupo total para personas con discapacidad."]},{"id":"au-11-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":6,"enunciado":"De acuerdo con el artículo 60.2 del TREBEP, no podrán formar parte de los órganos de selección del personal al servicio de las Administraciones públicas:","opciones":["El personal de elección o de designación política, los funcionarios interinos y el personal eventual.","El personal de elección o de designación política, los funcionarios interinos, el personal eventual y el personal directivo.","El personal de elección o de designación política, los funcionarios interinos, el personal eventual y el personal laboral.","El personal de elección o de designación política, el personal eventual y el personal laboral."],"bloque":"acceso","precepto":"Art. 60.2 del TREBEP","correcta":0,"justificaciones":["Es esta. No pueden formar parte el personal de elección o designación política, los funcionarios interinos y el personal eventual (**art. 60.2**).","No. El personal directivo no figura entre los excluidos.","No. El personal laboral no figura entre los excluidos.","No. Faltan los funcionarios interinos y sobra el personal laboral."]},{"id":"au-11-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":7,"enunciado":"Según el TREBEP, ¿podría aplicarse el sistema de concurso para el acceso a la condición de funcionario de carrera?","opciones":["No, en ningún caso.","Sí, con carácter general.","Sí, pero solo en virtud de Ley y con carácter excepcional.","Sí, con carácter excepcional, en virtud de norma legal o reglamentaria."],"bloque":"acceso","precepto":"Art. 61.6 del TREBEP","correcta":2,"justificaciones":["No. Sí es posible, con carácter excepcional.","No. El concurso no se aplica con carácter general, sino excepcional.","Es esta. Solo en virtud de ley y con carácter excepcional puede aplicarse el concurso (**art. 61.6**).","No. Hace falta una ley, no basta una norma reglamentaria."]},{"id":"au-11-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":8,"enunciado":"El artículo 61 del TREBEP contempla los siguientes sistemas de selección de funcionarios de carrera:","opciones":["Oposición, exclusivamente.","Oposición y concurso-oposición, exclusivamente.","Oposición y concurso-oposición y, con carácter excepcional, el concurso, si está así previsto en una norma con rango legal.","Oposición y, con carácter excepcional, el concurso-oposición y el concurso, si está así previsto en una norma con rango legal."],"bloque":"acceso","precepto":"Art. 61.6 del TREBEP","correcta":2,"justificaciones":["No. Hay también concurso-oposición, y excepcionalmente concurso.","No. Falta el concurso, que puede aplicarse excepcionalmente por ley.","Es esta. Oposición y concurso-oposición, y excepcionalmente el concurso, solo en virtud de ley (**art. 61.6**).","No. La oposición y el concurso-oposición son los sistemas ordinarios; solo el concurso es excepcional."]},{"id":"au-11-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":9,"enunciado":"Según el TREBEP, los sistemas selectivos de acceso al empleo público para personal laboral fijo son:","opciones":["La oposición, el concurso-oposición y, excepcionalmente, el concurso.","La oposición, el concurso-oposición y, solo en virtud de ley y con carácter excepcional, el concurso.","Solo el concurso.","La oposición, el concurso-oposición y el concurso de valoración de méritos."],"bloque":"acceso","precepto":"Art. 61.7 del TREBEP","correcta":3,"justificaciones":["No. En el personal laboral fijo el concurso de valoración de méritos no es excepcional.","No. La exigencia de ley y carácter excepcional es la del concurso para funcionarios de carrera.","No. No es solo el concurso: también la oposición y el concurso-oposición.","Es esta. Oposición, concurso-oposición y concurso de valoración de méritos (**art. 61.7**)."]},{"id":"au-11-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":10,"enunciado":"Según el artículo 62 del TREBEP, uno de los requisitos para adquirir la condición de funcionario de carrera es:","opciones":["Ser nacional de un estado miembro de la Unión Europea.","Toma de posesión dentro del plazo que se establezca.","Declaración responsable de no haber sido apartado del servicio en ninguna otra administración pública.","Tener cumplidos 18 años y no exceder la edad máxima de jubilación forzosa"],"bloque":"acceso","precepto":"Art. 62.1 del TREBEP","correcta":1,"justificaciones":["No. La nacionalidad es un requisito para participar en los procesos selectivos (**art. 56.1.a**), no para adquirir la condición.","Es esta. La toma de posesión dentro del plazo que se establezca es uno de los requisitos (**art. 62.1.d**).","No. La declaración responsable no figura en el art. 62.","No. La edad es un requisito para participar en el proceso selectivo (**art. 56.1.c**), no para adquirir la condición."]},{"id":"au-11-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":11,"enunciado":"Conforme al TREBEP, ¿cuál de los siguientes NO es un principio rector del acceso al empleo público?","opciones":["Igualdad.","Adecuación entre el contenido de los procesos selectivos y las funciones o tareas a desarrollar.","Agilidad, sin perjuicio de la subjetividad, en los procesos de selección.","Capacidad."],"bloque":"acceso","precepto":"Art. 55 del TREBEP","correcta":2,"justificaciones":["No. La igualdad es un principio constitucional rector (**art. 55.1**).","No. La adecuación entre procesos y funciones es un principio rector (**art. 55.2.e**).","Es esta. La agilidad es sin perjuicio de la objetividad, no de la subjetividad (**art. 55.2.f**).","No. La capacidad es un principio constitucional rector (**art. 55.1**)."]},{"id":"au-11-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":12,"enunciado":"De acuerdo con el TREBEP, no pueden formar parte de los órganos de selección de empleados públicos:","opciones":["El personal laboral fijo.","El personal laboral temporal.","Los funcionarios interinos.","Los funcionarios de carrera."],"bloque":"acceso","precepto":"Art. 60.2 del TREBEP","correcta":2,"justificaciones":["No. El personal laboral fijo no está excluido.","No. El personal laboral temporal no está excluido.","Es esta. Los funcionarios interinos no pueden formar parte (**art. 60.2**).","No. Los funcionarios de carrera sí pueden formar parte."]},{"id":"au-11-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":13,"enunciado":"No es un principio a garantizar en los procedimientos de selección de personal según el artículo 55 del TREBEP:","opciones":["Transparencia.","Publicidad de las convocatorias y sus bases.","Eficiencia en la actuación del órgano de selección.","Agilidad, sin perjuicio de la objetividad, en los procesos de selección."],"bloque":"acceso","precepto":"Art. 55.2 del TREBEP","correcta":2,"justificaciones":["No. La transparencia es un principio (**art. 55.2.b**).","No. La publicidad de las convocatorias es un principio (**art. 55.2.a**).","Es esta. La eficiencia en la actuación del órgano de selección no figura entre los principios del **art. 55.2**.","No. La agilidad, sin perjuicio de la objetividad, es un principio (**art. 55.2.f**)."]},{"id":"au-11-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":14,"enunciado":"Según el artículo 57 del TREBEP, los nacionales de otros Estados miembros de la Unión Europea:","opciones":["No podrán acceder a los empleos públicos que impliquen participación en la salvaguardia de los intereses del Estado.","Pueden acceder a todos los empleos públicos, sin excepción.","Podrán acceder a todos los empleos públicos, pero solo cuando tengan cumplida la edad de veintiún años.","Podrán acceder a todos los cuerpos de funcionarios, salvo a aquellos que exijan titulación universitaria para el ingreso."],"bloque":"acceso","precepto":"Art. 57.1 del TREBEP","correcta":0,"justificaciones":["Es esta. No pueden acceder a empleos que impliquen participación en el poder público o en la salvaguardia de los intereses del Estado o de las Administraciones (**art. 57.1**).","No. Hay excepciones: los empleos de poder público.","No. La edad de veintiún años se refiere a descendientes del cónyuge, no a una condición general.","No. No hay exclusión por exigir titulación universitaria."]},{"id":"au-11-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":15,"enunciado":"¿Cuál de los siguientes NO es uno de los requisitos previstos en el artículo 62 del TREBEP para la adquisición de la condición de funcionario de carrera?","opciones":["La superación del proceso selectivo.","El nombramiento por el órgano o autoridad competente.","La toma de posesión, dentro del mes siguiente a la publicación del nombramiento.","El acto de acatamiento de la Constitución."],"bloque":"acceso","precepto":"Art. 62.1 del TREBEP","correcta":2,"justificaciones":["No. La superación del proceso selectivo es un requisito (**art. 62.1.a**).","No. El nombramiento por el órgano competente es un requisito (**art. 62.1.b**).","Es esta. La toma de posesión es un requisito, pero dentro del plazo que se establezca, no del mes siguiente (**art. 62.1.d**).","No. El acto de acatamiento de la Constitución es un requisito (**art. 62.1.c**)."]},{"id":"au-11-016","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":16,"enunciado":"¿Puede eximirse el requisito de la nacionalidad para el acceso a la condición de personal funcionario?","opciones":["Solo por razones de interés general, mediante ley.","Solo por necesidades de servicio, mediante Real Decreto del Consejo de Ministros.","No, el requisito de la nacionalidad es imprescindible en todas las convocatorias de personal funcionario.","Sí, el órgano convocante podrá eximir del requisito de nacionalidad por razones de imperiosa urgencia."],"bloque":"acceso","precepto":"Art. 57.5 del TREBEP","correcta":0,"justificaciones":["Es esta. Solo por ley de las Cortes Generales o de las asambleas legislativas de las comunidades autónomas, por razones de interés general (**art. 57.5**).","No. No se exime por real decreto ni por necesidades de servicio.","No. Sí se puede eximir, por ley.","No. El órgano convocante no puede eximirlo."]},{"id":"au-11-017","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":17,"enunciado":"Señale la afirmación correcta en relación con los requisitos generales para poder participar en procesos selectivos públicos, según lo dispuesto en el TREBEP:","opciones":["Para participar en procesos selectivos es necesario tener como mínimo 18 años.","No podrá establecerse otra edad máxima, distinta de la edad de jubilación forzosa, para el acceso al empleo público.","En ningún caso podrá eximirse del requisito de la nacionalidad para participar en procesos selectivos.","Los extranjeros con residencia legal en España podrán acceder a las Administraciones Públicas, como personal laboral, en igualdad de condiciones que los españoles."],"bloque":"acceso","precepto":"Art. 57.4 del TREBEP","correcta":3,"justificaciones":["No. La edad mínima es de dieciséis años (**art. 56.1.c**).","No. Por ley sí puede establecerse otra edad máxima (**art. 56.1.c**).","No. Puede eximirse por ley, por razones de interés general (**art. 57.5**).","Es esta. Los extranjeros con residencia legal pueden acceder como personal laboral en igualdad de condiciones que los españoles (**art. 57.4**)."]},{"id":"au-11-018","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":18,"enunciado":"Según el TREBEP, en las ofertas de empleo público debe reservarse para ser cubierto por personas con discapacidad un cupo:","opciones":["No inferior al 5%.","No inferior al 3%.","No inferior al 10%.","No inferior al 7%."],"bloque":"acceso","precepto":"Art. 59.1 del TREBEP","correcta":3,"justificaciones":["No. El cupo mínimo es del siete por ciento, no del cinco.","No. El cupo mínimo es del siete por ciento, no del tres.","No. El cupo mínimo es del siete por ciento, no del diez.","Es esta. No inferior al siete por ciento (**art. 59.1**)."]},{"id":"au-11-019","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":19,"enunciado":"De acuerdo con el TREBEP, en las ofertas de empleo público se reservará al menos un 2% de las plazas ofertadas para el acceso al empleo público de personas que acrediten:","opciones":["Discapacidad psíquica.","Discapacidad intelectual.","Discapacidad física.","Cualquier tipo de discapacidad."],"bloque":"acceso","precepto":"Art. 59.1 del TREBEP","correcta":1,"justificaciones":["No. Se habla de discapacidad intelectual.","Es esta. Al menos el dos por ciento de las plazas es para personas con discapacidad intelectual (**art. 59.1**).","No. La discapacidad física entra en el resto de las plazas reservadas.","No. El dos por ciento es solo para la discapacidad intelectual."]},{"id":"au-11-020","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":20,"enunciado":"Los principios rectores del acceso al empleo público se establecen tanto en la Constitución como en el TREBEP. De los siguientes, ¿cuál es un principio constitucional?","opciones":["Agilidad.","Transparencia.","Capacidad.","Publicidad."],"bloque":"acceso","precepto":"Art. 55.1 del TREBEP","correcta":2,"justificaciones":["No. La agilidad es un principio del TREBEP (**art. 55.2.f**), no constitucional.","No. La transparencia es un principio del TREBEP (**art. 55.2.b**), no constitucional.","Es esta. Los principios constitucionales son igualdad, mérito y capacidad (**art. 55.1**).","No. La publicidad es un principio del TREBEP (**art. 55.2.a**), no constitucional."]},{"id":"au-11-021","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":21,"enunciado":"¿Cuál de los siguientes sistemas selectivos consiste únicamente en la valoración de méritos?","opciones":["El concurso.","La oposición.","La libre designación.","La evaluación del desempeño."],"bloque":"acceso","precepto":"Art. 61.6 del TREBEP","correcta":0,"justificaciones":["Es esta. El concurso consiste únicamente en la valoración de méritos (**art. 61.6**).","No. La oposición consiste en pruebas de capacidad.","No. La libre designación es una forma de provisión de puestos, no un sistema selectivo.","No. La evaluación del desempeño no es un sistema selectivo."]},{"id":"au-11-022","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":22,"enunciado":"De acuerdo con el TREBEP, ¿puede un ciudadano italiano acceder a un puesto de empleo público en España?","opciones":["Sí, tanto como personal funcionario como laboral.","Solo como personal funcionario.","No, salvo que su cónyuge ostente la nacionalidad española.","Solo como personal laboral."],"bloque":"acceso","precepto":"Art. 57 del TREBEP","correcta":0,"justificaciones":["Es esta. Un italiano es nacional de un Estado miembro: puede acceder como funcionario (salvo poder público) y como laboral (**art. 57.1 y 57.4**).","No. También puede acceder como personal laboral.","No. No se exige que su cónyuge sea español.","No. También puede acceder como personal funcionario."]},{"id":"au-11-023","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":23,"enunciado":"Señale la respuesta correcta en relación con el acceso al empleo público y adquisición de la relación de servicio:","opciones":["Los procesos selectivos serán siempre abiertos, sin que puedan establecer medidas de discriminación positiva.","En cada convocatoria se reservará un cupo no inferior al 7% para ser cubierto entre personas con discapacidad.","Excepcionalmente, podrá proponerse el acceso a funcionario de un número superior de aprobados al de plazas convocadas.","Los integrantes que formen parte de los órganos de selección lo harán siempre en representación del órgano convocante."],"bloque":"acceso","precepto":"Art. 61.8 del TREBEP","correcta":2,"justificaciones":["No. Los procesos son abiertos, pero sí admiten medidas de discriminación positiva (**art. 61.1**).","No. El cupo del siete por ciento se reserva en las ofertas de empleo público, no en cada convocatoria (**art. 59.1**).","Es esta. Excepcionalmente puede proponerse un número superior de aprobados cuando lo prevea la convocatoria (**art. 61.8**).","No. La pertenencia a los órganos de selección es siempre a título individual (**art. 60.3**)."]},{"id":"au-11-024","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":24,"enunciado":"Señale la respuesta incorrecta. Para poder participar en los procesos selectivos será necesario:","opciones":["Poseer la capacidad funcional para el desempeño de las tareas.","Ostentar, en todo caso, la nacionalidad española.","No haber sido separado mediante expediente disciplinario del servicio de cualquiera de las Administraciones Públicas.","Poseer la titulación exigida."],"bloque":"acceso","precepto":"Art. 56.1.a del TREBEP","correcta":1,"justificaciones":["Es verdadera, así que no se marca (**art. 56.1.b**).","Esta es la falsa, y por eso es la que hay que marcar. La nacionalidad española se exige sin perjuicio del art. 57, así que no es en todo caso (**art. 56.1.a**).","Es verdadera, así que no se marca (**art. 56.1.d**).","Es verdadera, así que no se marca (**art. 56.1.e**)."]},{"id":"au-11-025","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 11) - arts. 55 a 62","n":25,"enunciado":"No es correcto afirmar respecto a los sistemas selectivos que:","opciones":["Los procesos selectivos tendrán carácter cerrado.","Los procesos selectivos garantizarán la libre concurrencia.","Los órganos de selección velarán por el cumplimiento del principio de igualdad de oportunidades entre sexos.","Los procedimientos de selección cuidarán la conexión entre las pruebas a superar y las tareas de los puestos convocados."],"bloque":"acceso","precepto":"Art. 61.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Los procesos selectivos tienen carácter abierto, no cerrado (**art. 61.1**).","No. Garantizan la libre concurrencia (**art. 61.1**).","No. Los órganos velan por la igualdad de oportunidades entre sexos (**art. 61.1**).","No. Se cuida la conexión entre las pruebas y las tareas de los puestos (**art. 61.2**)."]},{"id":"au-12-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":1,"enunciado":"Según el artículo 61 del TREBEP, los procesos selectivos tendrán carácter:","opciones":["Abierto y garantizarán una concurrencia limitada.","Cerrado y garantizarán una concurrencia limitada.","Restringido y garantizarán la libre concurrencia.","Abierto y garantizarán la libre concurrencia."],"bloque":"acceso","precepto":"Art. 61.1 del TREBEP","correcta":3,"justificaciones":["No. Son abiertos, pero garantizan la libre concurrencia, no una concurrencia limitada.","No. No son cerrados ni de concurrencia limitada.","No. La libre concurrencia es correcta, pero no son restringidos sino abiertos.","Es esta. Los procesos selectivos son abiertos y garantizan la libre concurrencia (**art. 61.1**)."]},{"id":"au-12-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":2,"enunciado":"La selección del personal funcionario y laboral se hará mediante procedimientos en los que se garanticen los principios constitucionales, así como los establecidos en el artículo 55.2 del TREBEP. ¿Cuál de los siguientes no es uno de esos principios?","opciones":["Imparcialidad y profesionalidad de los miembros de los órganos de selección.","Agilidad, sin perjuicio de la objetividad, en los procesos de selección.","Proporcionalidad entre la dificultad de los procesos selectivos y las funciones o tareas a desarrollar.","Independencia y discrecionalidad técnica en la actuación de los órganos de selección."],"bloque":"acceso","precepto":"Art. 55.2 del TREBEP","correcta":2,"justificaciones":["No. La imparcialidad y profesionalidad de los órganos es un principio (**art. 55.2.c**).","No. La agilidad, sin perjuicio de la objetividad, es un principio (**art. 55.2.f**).","Es esta. El principio del **art. 55.2.e** es la adecuación entre el contenido de los procesos y las funciones, no la proporcionalidad entre dificultad y funciones.","No. La independencia y discrecionalidad técnica es un principio (**art. 55.2.d**)."]},{"id":"au-12-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":3,"enunciado":"Según el TREBEP, las edades mínima y máxima para el acceso al empleo público son, respectivamente:","opciones":["18 años y no exceder de la edad máxima de jubilación forzosa.","16 y 70 años.","18 y 70 años.","16 años y no exceder de la edad máxima de jubilación forzosa."],"bloque":"acceso","precepto":"Art. 56.1.c del TREBEP","correcta":3,"justificaciones":["No. La edad mínima es de dieciséis años, no de dieciocho.","No. No hay un máximo fijo de 70 años: es la edad máxima de jubilación forzosa.","No. Ni el mínimo es 18 ni el máximo es fijo en 70.","Es esta. Dieciséis años cumplidos y no exceder de la edad máxima de jubilación forzosa (**art. 56.1.c**)."]},{"id":"au-12-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":4,"enunciado":"Según el TREBEP, el requisito la nacionalidad española para el acceso a la condición de personal funcionario:","opciones":["Solo puede eximirse por ley de las Cortes Generales o de las Asambleas legislativas de las Comunidades Autónomas.","No puede eximirse en ningún caso.","Solo puede eximirse en el caso de que se trate de nacionales de los Estados miembros de la Unión Europea.","Solo puede eximirse por ley de las Cortes Generales."],"bloque":"acceso","precepto":"Art. 57.5 del TREBEP","correcta":0,"justificaciones":["Es esta. Solo por ley de las Cortes Generales o de las asambleas legislativas de las comunidades autónomas, por razones de interés general (**art. 57.5**).","No. Sí puede eximirse, por ley.","No. La exención no depende de que sean nacionales de la Unión Europea, y se hace por ley.","No. También pueden hacerlo las asambleas legislativas de las comunidades autónomas, no solo las Cortes Generales."]},{"id":"au-12-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":5,"enunciado":"Indique cuál de los siguientes órganos podrá eximir del requisito de la nacionalidad exigido para poder participar en los procesos selectivos de las Administraciones Públicas cuando existan razones de interés general que así lo aconsejen:","opciones":["El Consejo de Gobierno de una Comunidad Autónoma.","El Consejo de Ministros.","El Ministro de Función Pública.","Las Cortes Generales."],"bloque":"acceso","precepto":"Art. 57.5 del TREBEP","correcta":3,"justificaciones":["No. Un Consejo de Gobierno no puede hacerlo: hace falta ley.","No. El Consejo de Ministros no puede hacerlo: hace falta ley.","No. Una ministra o ministro no puede hacerlo: hace falta ley.","Es esta. Solo por ley de las Cortes Generales o de las asambleas legislativas autonómicas (**art. 57.5**)."]},{"id":"au-12-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":6,"enunciado":"De acuerdo con el artículo 60 del TREBEP, los órganos de selección de los funcionarios públicos serán:","opciones":["Unipersonales.","Colegiados.","Privados.","Secretos."],"bloque":"acceso","precepto":"Art. 60.1 del TREBEP","correcta":1,"justificaciones":["No. Son colegiados, no unipersonales.","Es esta. Los órganos de selección serán colegiados (**art. 60.1**).","No. El artículo no los califica de privados.","No. El artículo no los califica de secretos."]},{"id":"au-12-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":7,"enunciado":"Según lo dispuesto en el artículo 60 TREBEP, la pertenencia a los órganos de selección será:","opciones":["Siempre a título individual.","Siempre en representación.","Por cuenta propia o ajena.","A título individual o en representación."],"bloque":"acceso","precepto":"Art. 60.3 del TREBEP","correcta":0,"justificaciones":["Es esta. La pertenencia es siempre a título individual (**art. 60.3**).","No. No puede ostentarse en representación de nadie.","No. No puede ostentarse por cuenta de nadie.","No. Es siempre a título individual, no cabe la representación."]},{"id":"au-12-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":8,"enunciado":"Según el TREBEP, los sistemas selectivos de personal laboral fijo serán:","opciones":["Concurso-oposición y concurso de valoración de méritos.","Oposición, concurso-oposición y concurso de valoración de méritos.","Concurso de valoración de méritos y libre designación.","Oposición y concurso-oposición."],"bloque":"acceso","precepto":"Art. 61.7 del TREBEP","correcta":1,"justificaciones":["No. Falta la oposición.","Es esta. Oposición, concurso-oposición y concurso de valoración de méritos (**art. 61.7**).","No. La libre designación no es un sistema selectivo.","No. Falta el concurso de valoración de méritos."]},{"id":"au-12-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":9,"enunciado":"De acuerdo con el TREBEP, para asegurar la objetividad y la racionalidad de los procesos selectivos de los empleados públicos, las pruebas podrán completarse con:","opciones":["La realización de entrevistas.","La exposición curricular por los candidatos.","La superación de cursos.","Todas las respuestas son correctas."],"bloque":"acceso","precepto":"Art. 61.5 del TREBEP","correcta":3,"justificaciones":["No. Es cierta (**art. 61.5**), pero la opción correcta es la que recoge todas.","No. Es cierta (**art. 61.5**), pero la opción correcta es la que recoge todas.","No. Es cierta (**art. 61.5**), pero la opción correcta es la que recoge todas.","Es esta. El **art. 61.5** menciona cursos, periodos de prácticas, exposición curricular, pruebas psicotécnicas y entrevistas."]},{"id":"au-12-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":10,"enunciado":"Señale la respuesta incorrecta en relación con los sistemas selectivos de funcionarios de carrera, según el TREBEP:","opciones":["Tendrán carácter abierto.","Sólo en virtud de ley podrá aplicarse, con carácter excepcional, el sistema de concurso.","Podrán incluir la comprobación del dominio de lenguas extranjeras.","En el desarrollo de los procesos selectivos podrán colaborar las organizaciones sindicales."],"bloque":"acceso","precepto":"Art. 61.7 del TREBEP","correcta":3,"justificaciones":["Es verdadera, así que no se marca (**art. 61.1**).","Es verdadera, así que no se marca (**art. 61.6**).","Es verdadera, así que no se marca (**art. 61.2**).","Esta es la falsa, y por eso es la que hay que marcar. La colaboración de las organizaciones sindicales en los procesos selectivos se prevé para el personal laboral, no para los funcionarios de carrera (**art. 61.7**)."]},{"id":"au-12-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":11,"enunciado":"No podrán formar parte de los órganos de selección de las pruebas de acceso al empleo público:","opciones":["El personal eventual.","Los funcionarios interinos.","El personal de elección o de designación política.","Ninguno de los reseñados puede formar parte de los órganos de selección."],"bloque":"acceso","precepto":"Art. 60.2 del TREBEP","correcta":3,"justificaciones":["No. Es cierto que no puede formar parte, pero la opción correcta es la que recoge los tres casos (**art. 60.2**).","No. Es cierto que no pueden formar parte, pero la opción correcta es la que recoge los tres casos (**art. 60.2**).","No. Es cierto que no puede formar parte, pero la opción correcta es la que recoge los tres casos (**art. 60.2**).","Es esta. Ni el personal eventual, ni los funcionarios interinos, ni el de elección o designación política pueden formar parte (**art. 60.2**)."]},{"id":"au-12-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":12,"enunciado":"Señale la respuesta incorrecta en relación con los órganos de selección, conforme al artículo 60 del TREBEP:","opciones":["Serán colegiados.","Su composición deberá ajustarse a los principios de imparcialidad y profesionalidad de sus miembros.","Su composición será paritaria, incluyendo igual número de hombres y mujeres.","La pertenencia a los órganos de selección será siempre a título individual."],"bloque":"acceso","precepto":"Art. 60 del TREBEP","correcta":2,"justificaciones":["Es verdadera, así que no se marca (**art. 60.1**).","Es verdadera, así que no se marca (**art. 60.1**).","Esta es la falsa, y por eso es la que hay que marcar. Se tenderá a la paridad entre mujer y hombre, no se exige igual número (**art. 60.1**).","Es verdadera, así que no se marca (**art. 60.3**)."]},{"id":"au-12-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":13,"enunciado":"De acuerdo con el artículo 55 del TREBEP, todos los ciudadanos tienen derecho al acceso al empleo público de acuerdo con los principios constitucionales de:","opciones":["Mérito y capacidad.","Igualdad, mérito y capacidad.","Igualdad, mérito, capacidad y publicidad.","Igualdad."],"bloque":"acceso","precepto":"Art. 55.1 del TREBEP","correcta":1,"justificaciones":["No. Falta la igualdad.","Es esta. Igualdad, mérito y capacidad (**art. 55.1**).","No. La publicidad es un principio del art. 55.2, no constitucional.","No. Faltan mérito y capacidad."]},{"id":"au-12-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":14,"enunciado":"Del requisito de la nacionalidad para el acceso a la condición de personal funcionario:","opciones":["Podrá eximirse por ley de las Cortes Generales.","Podrá eximirse por ley de las Asambleas Legislativas de las Comunidades Autónomas.","Las respuestas a y b son correctas.","No podrá eximirse en ningún caso."],"bloque":"acceso","precepto":"Art. 57.5 del TREBEP","correcta":2,"justificaciones":["No. Es correcta, pero incompleta: también pueden las asambleas legislativas de las comunidades autónomas.","No. Es correcta, pero incompleta: también pueden las Cortes Generales.","Es esta. Pueden eximirlo tanto las Cortes Generales como las asambleas legislativas autonómicas, por ley (**art. 57.5**).","No. Sí puede eximirse, por ley."]},{"id":"au-12-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":15,"enunciado":"Solo en virtud de ley podrá aplicarse como sistema selectivo de funcionarios de carrera, excepcionalmente, el sistema de:","opciones":["Concurso.","Oposición.","Concurso-oposición.","Libre designación."],"bloque":"acceso","precepto":"Art. 61.6 del TREBEP","correcta":0,"justificaciones":["Es esta. Solo en virtud de ley y con carácter excepcional puede aplicarse el concurso (**art. 61.6**).","No. La oposición es un sistema ordinario, no excepcional.","No. El concurso-oposición es un sistema ordinario, no excepcional.","No. La libre designación no es un sistema selectivo."]},{"id":"au-12-016","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":16,"enunciado":"Indique la respuesta incorrecta. Conforme al TREBEP, la condición de funcionario de carrera se adquiere por el cumplimiento sucesivo de los siguientes requisitos:","opciones":["Superación del proceso selectivo.","Nombramiento por el órgano o autoridad competente, que será publicado en el Diario Oficial correspondiente.","Acto de acatamiento de la Constitución, del Estatuto de Autonomía correspondiente, y del resto del Ordenamiento Jurídico.","Toma de posesión en el plazo de 20 días."],"bloque":"acceso","precepto":"Art. 62.1 del TREBEP","correcta":3,"justificaciones":["Es verdadera, así que no se marca (**art. 62.1.a**).","Es verdadera, así que no se marca (**art. 62.1.b**).","Es verdadera, así que no se marca (**art. 62.1.c**).","Esta es la falsa, y por eso es la que hay que marcar. La toma de posesión es dentro del plazo que se establezca, no en veinte días (**art. 62.1.d**)."]},{"id":"au-12-017","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":17,"enunciado":"Señale la respuesta incorrecta. Podrán acceder, como personal funcionario, en igualdad de condiciones que los españoles, con las excepciones previstas en el artículo 57 del TREBEP:","opciones":["Los nacionales de los Estados miembros de la Unión Europea.","Cualquiera que sea su nacionalidad, los extranjeros con residencia legal en España.","Cualquiera que sea su nacionalidad, al cónyuge de los nacionales de otros Estados miembros de la Unión Europea.","Los descendientes de nacionales de Estados miembros de la Unión Europea menores de 21 años, o mayores dependientes."],"bloque":"acceso","precepto":"Art. 57 del TREBEP","correcta":1,"justificaciones":["Es verdadera, así que no se marca (**art. 57.1**).","Esta es la falsa, y por eso es la que hay que marcar. Los extranjeros con residencia legal solo pueden acceder como personal laboral, no como funcionarios (**art. 57.4**).","Es verdadera, así que no se marca. Se aplica al cónyuge, cualquiera que sea su nacionalidad (**art. 57.2**).","Es verdadera, así que no se marca. Se aplica a los descendientes menores de 21 años o mayores dependientes (**art. 57.2**)."]},{"id":"au-12-018","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":18,"enunciado":"Señale la respuesta correcta. Podrá eximirse del requisito de nacionalidad para acceder a la condición de funcionario de carrera:","opciones":["Exclusivamente, por Ley de las Cortes Generales.","Por ley de las asambleas legislativas de las Comunidades Autónomas.","Por razones presupuestarias.","Por razones de urgencia mediante Decreto ley."],"bloque":"acceso","precepto":"Art. 57.5 del TREBEP","correcta":1,"justificaciones":["No. No es exclusivamente por ley de las Cortes Generales: también pueden las asambleas autonómicas.","Es esta. Puede eximirse por ley de las asambleas legislativas de las comunidades autónomas (o de las Cortes Generales) (**art. 57.5**).","No. Solo por razones de interés general, no presupuestarias.","No. No cabe por decreto ley: hace falta ley, por interés general."]},{"id":"au-12-019","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":19,"enunciado":"No es correcto afirmar, respecto a los órganos de selección, que:","opciones":["Serán colegiados y su composición deberá ajustarse a los principios de imparcialidad y profesionalidad de sus miembros.","Se tenderá a la paridad entre mujer y hombre.","El personal eventual no podrán formar parte de los órganos de selección.","La pertenencia a los órganos de selección podrá ostentarse en representación de otra persona."],"bloque":"acceso","precepto":"Art. 60.3 del TREBEP","correcta":3,"justificaciones":["Es verdadera, así que no se marca (**art. 60.1**).","Es verdadera, así que no se marca (**art. 60.1**).","Es verdadera, así que no se marca (**art. 60.2**).","Esta es la falsa, y por eso es la que hay que marcar. La pertenencia es siempre a título individual, sin representación de nadie (**art. 60.3**)."]},{"id":"au-12-020","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 12) - arts. 55 a 62","n":20,"enunciado":"En los procedimientos selectivos las pruebas podrán consistir en:","opciones":["La comprobación de los conocimientos y la capacidad analítica de los aspirantes, expresados de forma oral o escrita.","La realización de ejercicios que demuestren la posesión de habilidades y destrezas.","La superación de pruebas físicas.","Todas las opciones anteriores son correctas."],"bloque":"acceso","precepto":"Art. 61.2 del TREBEP","correcta":3,"justificaciones":["No. Es cierta (**art. 61.2**), pero la opción correcta es la que recoge todas.","No. Es cierta (**art. 61.2**), pero la opción correcta es la que recoge todas.","No. Es cierta (**art. 61.2**), pero la opción correcta es la que recoge todas.","Es esta. El **art. 61.2** incluye conocimientos y capacidad analítica, ejercicios de habilidades y destrezas, lenguas extranjeras y pruebas físicas."]},{"id":"au-13-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":1,"enunciado":"Conforme al artículo 63 del TREBEP, no es causa de pérdida de la condición de funcionario de carrera:","opciones":["La renuncia a la condición de funcionario.","La pérdida de la nacionalidad.","La jubilación total del funcionario.","La sanción disciplinaria de suspensión firme del servicio."],"bloque":"adquisicion","precepto":"Art. 63 del TREBEP","correcta":3,"justificaciones":["No. Es causa de pérdida (**art. 63.a**).","No. Es causa de pérdida (**art. 63.b**).","No. Es causa de pérdida (**art. 63.c**).","Es esta. La causa es la sanción de separación del servicio con carácter firme, no la de suspensión (**art. 63.d**)."]},{"id":"au-13-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":2,"enunciado":"La renuncia a la condición de funcionario no podrá ser aceptada:","opciones":["Cuando el funcionario la solicite con la intención de prestar sus servicios en el sector privado.","Cuando el funcionario esté sujeto a expediente disciplinario.","Cuando haya sido dictada en su contra cualquier sentencia judicial firme.","Cuando el funcionario se encuentre en situación administrativa distinta a servicio activo."],"bloque":"adquisicion","precepto":"Art. 64.2 del TREBEP","correcta":1,"justificaciones":["No. El destino de la persona tras la renuncia no impide aceptarla.","Es esta. No puede aceptarse si el funcionario está sujeto a expediente disciplinario o hay auto de procesamiento o apertura de juicio oral (**art. 64.2**).","No. Solo impide la aceptación el auto de procesamiento o de apertura de juicio oral, no cualquier sentencia firme.","No. La situación administrativa no impide aceptarla."]},{"id":"au-13-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":3,"enunciado":"Según el TREBEP, ¿en cuál de los siguientes casos se puede producir la rehabilitación de la condición de funcionario?","opciones":["Jubilación voluntaria y sanción disciplinaria de separación de servicio.","Pérdida de la nacionalidad y jubilación voluntaria.","Pérdida de la nacionalidad y jubilación por incapacidad permanente para el servicio.","Jubilación voluntaria y pena principal o accesoria de inhabilitación."],"bloque":"adquisicion","precepto":"Art. 68.1 del TREBEP","correcta":2,"justificaciones":["No. La separación del servicio y la jubilación voluntaria no dan derecho a rehabilitación.","No. La jubilación voluntaria no permite rehabilitar.","Es esta. Cabe rehabilitación por pérdida de la nacionalidad o jubilación por incapacidad permanente (**art. 68.1**).","No. La jubilación voluntaria no permite rehabilitar, y la inhabilitación solo excepcionalmente (**art. 68.2**)."]},{"id":"au-13-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":4,"enunciado":"Señale la respuesta correcta en relación con la renuncia a la condición de funcionario de carrera de acuerdo con el TREBEP:","opciones":["Podrá ser aceptada cuando el funcionario esté sujeto a expediente disciplinario.","No inhabilita para ingresar de nuevo en la Administración Pública a través del procedimiento de selección establecido.","Será aceptada, tácita o expresamente, por la Administración.","Desaparecida la causa objetiva que la motivó, el funcionario podrá solicitar la rehabilitación en la condición de funcionario."],"bloque":"adquisicion","precepto":"Art. 64.3 del TREBEP","correcta":1,"justificaciones":["No. No puede aceptarse si está sujeto a expediente disciplinario (**art. 64.2**).","Es esta. La renuncia no inhabilita para ingresar de nuevo por el procedimiento de selección (**art. 64.3**).","No. Debe ser aceptada expresamente, no tácitamente (**art. 64.1**).","No. La rehabilitación no cabe tras la renuncia (**art. 68**)."]},{"id":"au-13-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":5,"enunciado":"En relación con la rehabilitación de la condición de funcionario, en caso de extinción de la relación de servicio como consecuencia de pérdida de la nacionalidad o de jubilación por incapacidad permanente para el servicio:","opciones":["El interesado, una vez desaparecida la causa objetiva que la motiva, podrá solicitarla y le será concedida.","Los órganos de gobierno de las Administraciones Públicas podrán concederla excepcionalmente.","Una vez desaparecida la causa, el órgano de gobierno concederá la rehabilitación automáticamente.","Solo cabrá la rehabilitación en la condición de funcionario cuando la extinción de la relación de servicio derive de renuncia."],"bloque":"adquisicion","precepto":"Art. 68.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Una vez desaparecida la causa, el interesado puede solicitarla y le será concedida (**art. 68.1**).","No. Esa es la rehabilitación excepcional por inhabilitación (**art. 68.2**).","No. No es automática: hay que solicitarla.","No. Cabe también por pérdida de la nacionalidad y por incapacidad permanente, no por renuncia."]},{"id":"au-13-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":6,"enunciado":"Conforme al artículo 68 del TREBEP, procederá la rehabilitación de la condición de funcionario en el caso de que la extinción de la relación de servicios se haya producido por una de las siguientes causas:","opciones":["Jubilación voluntaria.","Pérdida de la nacionalidad.","Renuncia voluntaria a la condición de funcionario.","Sanción disciplinaria de separación del servicio."],"bloque":"adquisicion","precepto":"Art. 68.1 del TREBEP","correcta":1,"justificaciones":["No. La jubilación voluntaria no permite rehabilitar.","Es esta. Procede por pérdida de la nacionalidad (**art. 68.1**).","No. La renuncia voluntaria no permite rehabilitar.","No. La separación del servicio no permite rehabilitar."]},{"id":"au-13-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":7,"enunciado":"Según el TREBEP, ¿es posible la rehabilitación de la condición de funcionario cuando la pérdida de dicha condición se produzca a consecuencia de la imposición por sentencia firme de la pena accesoria de inhabilitación?","opciones":["No, en ningún caso.","Sí, con carácter excepcional, a petición del interesado.","Sí. Una vez cumplida la condena, podrá solicitarse la rehabilitación, que será concedida.","Solo de oficio, con carácter excepcional, por los órganos de gobierno de las Administraciones Públicas."],"bloque":"adquisicion","precepto":"Art. 68.2 del TREBEP","correcta":1,"justificaciones":["No. Sí cabe, excepcionalmente.","Es esta. Los órganos de gobierno pueden concederla con carácter excepcional, a petición del interesado (**art. 68.2**).","No. No se concede por el mero cumplimiento de la condena.","No. Es a petición del interesado, no de oficio."]},{"id":"au-13-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":8,"enunciado":"De acuerdo con el artículo 67 del TREBEP, la jubilación de los funcionarios podrá ser:","opciones":["Voluntaria, a solicitud del funcionario.","Forzosa, al cumplir la edad legalmente establecida.","Por la declaración de incapacidad permanente para el ejercicio de las funciones propias de su cuerpo o escala.","Todas las respuestas anteriores son correctas."],"bloque":"adquisicion","precepto":"Art. 67.1 del TREBEP","correcta":3,"justificaciones":["No. Es correcta (**art. 67.1.a**), pero la opción correcta es la que recoge todas.","No. Es correcta (**art. 67.1.b**), pero la opción correcta es la que recoge todas.","No. Es correcta (**art. 67.1.c**), pero la opción correcta es la que recoge todas.","Es esta. La jubilación puede ser voluntaria, forzosa o por incapacidad permanente (**art. 67.1**)."]},{"id":"au-13-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":9,"enunciado":"De conformidad con el artículo 63 del TREBEP, NO es causa de pérdida de la condición de funcionario de carrera:","opciones":["La adquisición de la condición de personal laboral fijo.","La pérdida de la nacionalidad.","La pena principal o accesoria de inhabilitación absoluta o especial para cargo público que tuviere carácter firme.","La jubilación total del funcionario."],"bloque":"adquisicion","precepto":"Art. 63 del TREBEP","correcta":0,"justificaciones":["Es esta. Adquirir la condición de personal laboral fijo no figura entre las causas del **art. 63**.","No. Es causa de pérdida (**art. 63.b**).","No. Es causa de pérdida (**art. 63.e**).","No. Es causa de pérdida (**art. 63.c**)."]},{"id":"au-13-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":10,"enunciado":"La pérdida de la nacionalidad española o la de cualquier otro Estado miembro de la Unión Europea o la de aquellos Estados a los que, en virtud de tratados internacionales celebrados por la Unión Europea y ratificados por España, les sea de aplicación la libre circulación de trabajadores, que haya sido tenida en cuenta para el nombramiento, determinará:","opciones":["La pérdida de la condición de funcionario, en todo caso.","La declaración de oficio de la situación administrativa de suspensión de funciones.","La declaración de oficio de la situación administrativa de excedencia forzosa.","La pérdida de la condición de funcionario salvo que simultáneamente se adquiera la nacionalidad de alguno de dichos Estados."],"bloque":"adquisicion","precepto":"Art. 65 del TREBEP","correcta":3,"justificaciones":["No. No es en todo caso: no se pierde si simultáneamente se adquiere la nacionalidad de alguno de esos Estados.","No. No determina una suspensión de funciones.","No. No determina una excedencia forzosa.","Es esta. Determina la pérdida de la condición salvo que simultáneamente se adquiera la nacionalidad de alguno de dichos Estados (**art. 65**)."]},{"id":"au-13-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":11,"enunciado":"Según el TREBEP, se podrá solicitar la prolongación de la permanencia en el servicio activo como máximo hasta los 70 años:","opciones":["Que será aceptada con carácter general, teniendo la Administración competente que resolver de forma motivada la denegación.","Configurándose como un derecho que solo se podrá denegar por motivos extraordinarios.","Que será aceptada siempre que el funcionario conserve en plenitud sus capacidades funcionales.","Teniendo la Administración competente que resolver de forma motivada la aceptación o denegación."],"bloque":"adquisicion","precepto":"Art. 67.3 del TREBEP","correcta":3,"justificaciones":["No. No se acepta con carácter general: la Administración resuelve motivadamente la aceptación o la denegación.","No. No es un derecho: la Administración puede aceptar o denegar de forma motivada.","No. No se acepta automáticamente por conservar las capacidades.","Es esta. La Administración debe resolver de forma motivada la aceptación o denegación de la prolongación (**art. 67.3**)."]},{"id":"au-13-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":12,"enunciado":"Señale la respuesta correcta según el TREBEP, en relación con la rehabilitación de la condición de funcionario:","opciones":["Se producirá automáticamente, una vez desaparecida la causa objetiva que la motivó.","Se producirá, en caso de recuperación de la nacionalidad española, sin necesidad de que el interesado lo solicite.","Se producirá solo en los casos de extinción de la relación de servicios como consecuencia de pérdida de la nacionalidad.","Transcurrido el plazo para dictar resolución sin que esta se haya producido, se entenderá desestimada la solicitud."],"bloque":"adquisicion","precepto":"Art. 68 del TREBEP","correcta":3,"ojo":"La regla del silencio negativo del art. 68.2 se refiere a la rehabilitación excepcional por inhabilitación. En la rehabilitación por pérdida de la nacionalidad o incapacidad (art. 68.1) se concede si la solicita el interesado.","justificaciones":["No. No es automática: la solicita el interesado (**art. 68.1**).","No. Hay que solicitarla.","No. También cabe por jubilación por incapacidad permanente y, excepcionalmente, por inhabilitación.","Es esta. Si transcurrido el plazo no hay resolución expresa, se entiende desestimada la solicitud (**art. 68.2**)."]},{"id":"au-13-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":13,"enunciado":"¿Cuál de las siguientes NO es una causa de pérdida de la condición de funcionario de carrera?","opciones":["La pena accesoria de inhabilitación absoluta o especial para cargo público que tuviere carácter firme.","La jubilación total del funcionario.","La incapacidad temporal.","La pérdida de la nacionalidad."],"bloque":"adquisicion","precepto":"Art. 63 del TREBEP","correcta":2,"justificaciones":["No. Es causa de pérdida (**art. 63.e**).","No. Es causa de pérdida (**art. 63.c**).","Es esta. La incapacidad temporal no figura entre las causas del **art. 63**.","No. Es causa de pérdida (**art. 63.b**)."]},{"id":"au-13-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":14,"enunciado":"Señale la respuesta incorrecta. Es causa de pérdida de la condición de funcionario de carrera:","opciones":["La pérdida de la nacionalidad.","La jubilación total.","La incoación de expediente disciplinario por la comisión de infracción muy grave.","La pena principal o accesoria de inhabilitación absoluta o especial para cargo público que tuviere carácter firme."],"bloque":"adquisicion","precepto":"Art. 63 del TREBEP","correcta":2,"justificaciones":["Es verdadera, así que no se marca (**art. 63.b**).","Es verdadera, así que no se marca (**art. 63.c**).","Esta es la falsa, y por eso es la que hay que marcar. La causa es la sanción de separación con carácter firme, no la mera incoación del expediente (**art. 63.d**).","Es verdadera, así que no se marca (**art. 63.e**)."]},{"id":"au-13-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 13) - arts. 63 a 68","n":15,"enunciado":"Será en todo caso causa de pérdida de la condición de funcionario de carrera:","opciones":["La renuncia a la condición de funcionario.","La pérdida de la nacionalidad española aunque se adquiera la de cualquier otro Estado miembro de la Unión Europea.","La jubilación parcial del funcionario.","La sanción disciplinaria de separación del servicio que no tenga carácter firme."],"bloque":"adquisicion","precepto":"Art. 63.a del TREBEP","correcta":0,"justificaciones":["Es esta. La renuncia a la condición de funcionario es causa de pérdida (**art. 63.a**).","No. Si se adquiere simultáneamente la de otro Estado miembro, no se pierde (**art. 65**).","No. La causa es la jubilación total, no la parcial (**art. 63.c**).","No. La separación solo es causa si tiene carácter firme (**art. 63.d**)."]},{"id":"au-14-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 14) - arts. 63 a 68","n":1,"enunciado":"Produce la pérdida de la condición de funcionario respecto a todos los empleos o cargos que tuviere:","opciones":["La pena principal o accesoria de inhabilitación absoluta cuando hubiere adquirido firmeza la sentencia que la imponga.","La pena principal o accesoria de inhabilitación especial cuando hubiere adquirido firmeza la sentencia que la imponga.","La pena principal o accesoria de inhabilitación particular cuando hubiere adquirido firmeza la sentencia que la imponga.","Ninguna es correcta."],"bloque":"adquisicion","precepto":"Art. 66 del TREBEP","correcta":0,"justificaciones":["Es esta. La inhabilitación absoluta firme produce la pérdida respecto a todos los empleos o cargos (**art. 66**).","No. La inhabilitación especial solo afecta a los empleos o cargos especificados en la sentencia.","No. La inhabilitación particular no figura en el artículo.","No. Hay una correcta."]},{"id":"au-14-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 14) - arts. 63 a 68","n":2,"enunciado":"Según el artículo 67 del TREBEP, la jubilación forzosa se declarará de oficio al cumplir el funcionario la edad de:","opciones":["60 años.","65 años.","67 años","70 años."],"bloque":"adquisicion","precepto":"Art. 67.3 del TREBEP","correcta":1,"ojo":"El art. 67.3 fija 65 años. El art. 67.4 remite, para el Régimen General de la Seguridad Social, a la edad de acceso a la pensión de jubilación sin coeficiente reductor (hoy hasta 67 años).","revisar":"Respondida con el art. 67.3 (65 años), que es lo que suele dar la academia. Si la clave es 67 años por el art. 67.4, sería la opción 2.","justificaciones":["No. Sesenta años no es la edad de jubilación forzosa.","Es esta. La jubilación forzosa se declara de oficio al cumplir los sesenta y cinco años (**art. 67.3**).","No. Es la edad que puede aplicar la normativa de Seguridad Social (**art. 67.4**), pero el **art. 67.3** fija sesenta y cinco.","No. Setenta años es el máximo de la prolongación de la permanencia en el servicio activo."]},{"id":"au-14-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 14) - arts. 63 a 68","n":3,"enunciado":"En los términos de las leyes de Función Pública que se dicten en desarrollo de este Estatuto, se podrá solicitar la prolongación de la permanencia en el servicio activo como máximo hasta que se cumpla:","opciones":["70 años.","72 años.","73 años.","75 años."],"bloque":"adquisicion","precepto":"Art. 67.3 del TREBEP","correcta":0,"justificaciones":["Es esta. Se puede solicitar la prolongación como máximo hasta los setenta años (**art. 67.3**).","No. El máximo es de setenta años, no setenta y dos.","No. El máximo es de setenta años, no setenta y tres.","No. El máximo es de setenta años, no setenta y cinco."]},{"id":"au-14-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 14) - arts. 63 a 68","n":4,"enunciado":"Según el TREBEP, el interesado, una vez desaparecida la causa objetiva que la motivó, podrá solicitar la rehabilitación de su condición de funcionario, que le será concedida en caso de extinción de la relación de servicios como consecuencia de:","opciones":["Pérdida de la nacionalidad.","Jubilación por incapacidad permanente para el servicio.","Sanción disciplinaria de separación del servicio.","Las respuestas a y b son correctas."],"bloque":"adquisicion","precepto":"Art. 68.1 del TREBEP","correcta":3,"justificaciones":["No. Es correcta (**art. 68.1**), pero también lo es la jubilación por incapacidad.","No. Es correcta (**art. 68.1**), pero también lo es la pérdida de la nacionalidad.","No. La separación del servicio no da derecho a rehabilitación.","Es esta. Pérdida de la nacionalidad y jubilación por incapacidad permanente (**art. 68.1**)."]},{"id":"au-14-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 14) - arts. 63 a 68","n":5,"enunciado":"¿Cuál de estas causas de pérdida de la condición de funcionario impide la rehabilitación, según el Texto Refundido de la Ley del Estatuto Básico del Empleado Público?","opciones":["La pérdida de la nacionalidad.","La jubilación por incapacidad permanente.","La renuncia a la condición de funcionario.","La pena principal o accesoria de inhabilitación absoluta o especial para cargo público."],"bloque":"adquisicion","precepto":"Art. 68 del TREBEP","correcta":2,"justificaciones":["No. La pérdida de la nacionalidad permite rehabilitación (**art. 68.1**).","No. La incapacidad permanente permite rehabilitación (**art. 68.1**).","Es esta. Tras la renuncia no cabe rehabilitación; solo se puede volver a ingresar por el procedimiento de selección (**art. 64.3**).","No. La inhabilitación permite rehabilitación excepcional (**art. 68.2**)."]},{"id":"au-14-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 14) - arts. 63 a 68","n":6,"enunciado":"Es correcto señalar respecto a la renuncia de la condición de funcionario que:","opciones":["Habrá de ser manifestada por escrito o verbalmente a su superior.","Podrá ser aceptada cuando el funcionario esté sujeto a expediente disciplinario.","No podrá ser aceptada cuando haya sido dictado en su contra auto de procesamiento por la comisión de algún delito.","Inhabilita para ingresar de nuevo en la Administración Pública a través del procedimiento de selección establecido."],"bloque":"adquisicion","precepto":"Art. 64 del TREBEP","correcta":2,"justificaciones":["No. Debe ser por escrito, no verbalmente (**art. 64.1**).","No. No puede aceptarse si el funcionario está sujeto a expediente disciplinario (**art. 64.2**).","Es esta. No puede aceptarse si se ha dictado auto de procesamiento por un delito (**art. 64.2**).","No. No inhabilita para ingresar de nuevo (**art. 64.3**)."]},{"id":"au-14-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 14) - arts. 63 a 68","n":7,"enunciado":"La jubilación de los funcionarios podrá producirse por el reconocimiento de una pensión de:","opciones":["Incapacidad permanente absoluta o incapacidad permanente parcial en relación con el ejercicio de las funciones de su cuerpo.","Incapacidad permanente total o incapacidad permanente parcial en relación con el ejercicio de las funciones de su cuerpo.","Incapacidad permanente absoluta o incapacidad permanente total en relación con el ejercicio de las funciones de su cuerpo.","Incapacidad permanente absoluta, total o parcial en relación con el ejercicio de las funciones de su cuerpo o escala."],"bloque":"adquisicion","precepto":"Art. 67.1.c del TREBEP","correcta":2,"justificaciones":["No. La incapacidad parcial no figura.","No. La incapacidad parcial no figura.","Es esta. Incapacidad permanente absoluta o total (**art. 67.1.c**).","No. La incapacidad parcial no figura."]},{"id":"au-14-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 14) - arts. 63 a 68","n":8,"enunciado":"Un funcionario de carrera que haya cumplido setenta años, ¿puede solicitar la prórroga de la permanencia en servicio activo?","opciones":["Sí, sin límite de tiempo alguno.","Sí, como máximo hasta que cumpla setenta y cinco.","Sí, como máximo hasta que cumpla ochenta años.","No."],"bloque":"adquisicion","precepto":"Art. 67.3 del TREBEP","correcta":3,"justificaciones":["No. La prolongación tiene un límite: setenta años.","No. El límite es setenta años, no setenta y cinco.","No. El límite es setenta años, no ochenta.","Es esta. La prolongación llega como máximo hasta los setenta años, así que quien ya los ha cumplido no puede solicitarla (**art. 67.3**)."]},{"id":"au-14-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 14) - arts. 63 a 68","n":9,"enunciado":"Con independencia de la edad establecida en el artículo 67.3, la edad de la jubilación forzosa del personal funcionario incluido en el Régimen General de la Seguridad Social será, en todo caso, las que prevean las normas reguladoras de dicho régimen para el acceso a la pensión de jubilación:","opciones":["En su modalidad contributiva con coeficiente reductor por razón de la edad.","En su modalidad no contributiva sin coeficiente reductor por razón de la edad.","En su modalidad contributiva sin coeficiente reductor por razón de la edad.","En su modalidad no contributiva con coeficiente reductor por razón de la edad."],"bloque":"adquisicion","precepto":"Art. 67.4 del TREBEP","correcta":2,"justificaciones":["No. Es sin coeficiente reductor.","No. Es en modalidad contributiva, no no contributiva.","Es esta. Será la que prevean las normas del Régimen General en su modalidad contributiva sin coeficiente reductor por razón de la edad (**art. 67.4**).","No. Es contributiva y sin coeficiente reductor."]},{"id":"au-14-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 14) - arts. 63 a 68","n":10,"enunciado":"Según el TREBEP, con carácter general la jubilación forzosa de los funcionarios:","opciones":["Se declarará a instancia del funcionario, al cumplir los setenta y siete años de edad.","Se declarará de oficio, al cumplir el funcionario los sesenta y cinco años de edad.","Se declarará a instancia del funcionario, al cumplir los setenta y cinco años de edad.","Se declarará de oficio, al cumplir el funcionario los sesenta y siete años de edad."],"bloque":"adquisicion","precepto":"Art. 67.3 del TREBEP","correcta":1,"ojo":"El art. 67.3 fija 65 años. El art. 67.4 remite, para el Régimen General de la Seguridad Social, a la edad de acceso a la pensión de jubilación sin coeficiente reductor (hoy hasta 67 años).","revisar":"Respondida con el art. 67.3 (65 años de oficio). Si la clave fuera 67 años por el art. 67.4, sería la opción 3.","justificaciones":["No. Se declara de oficio, no a instancia, y no a los setenta y siete años.","Es esta. La jubilación forzosa se declara de oficio al cumplir sesenta y cinco años (**art. 67.3**).","No. Se declara de oficio, no a instancia, y no a los setenta y cinco años.","No. Es de oficio, pero la edad del **art. 67.3** es sesenta y cinco; sesenta y siete es la del Régimen General (**art. 67.4**)."]},{"id":"au-15-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":1,"enunciado":"Según el artículo 70 del TREBP, la ejecución de la oferta de empleo público o instrumento similar deberá desarrollarse:","opciones":["En todo caso, dentro del plazo improrrogable de tres años.","Dentro del plazo improrrogable de tres años, excepto causa justificada de interés público.","En todo caso, dentro del plazo del plazo improrrogable de cinco años.","Dentro del plazo improrrogable de cinco años, excepto causa justificada de interés público."],"bloque":"provision","precepto":"Art. 70.1 del TREBEP","correcta":0,"justificaciones":["Es esta. En todo caso, la ejecución de la oferta debe desarrollarse dentro del plazo improrrogable de tres años (**art. 70.1**).","No. El plazo no admite excepción por interés público: es improrrogable en todo caso.","No. El plazo es de tres años, no de cinco.","No. El plazo es de tres años y no hay excepción."]},{"id":"au-15-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":2,"enunciado":"La creación, modificación o extinción de cuerpos y escalas de funcionarios se hará, en todo caso:","opciones":["Por Ley.","Por la propia norma de convocatoria.","Por Acuerdo del Consejo de Gobierno.","Por Decreto."],"bloque":"provision","precepto":"Art. 75.2 del TREBEP","correcta":0,"justificaciones":["Es esta. Los cuerpos y escalas se crean, modifican y suprimen por ley (**art. 75.2**).","No. No se crean por la norma de convocatoria.","No. No basta un acuerdo del Consejo de Gobierno: hace falta ley.","No. No basta un decreto: hace falta ley."]},{"id":"au-15-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":3,"enunciado":"Según el artículo 75.2 del TREBEP, los cuerpos y escalas de funcionarios se modifican:","opciones":["Por acuerdo de la Conferencia Sectorial de las Administraciones Públicas.","Por Real Decreto del Consejo de Ministros o del máximo órgano de Gobierno de las Comunidades Autónomas.","En el marco de sus competencias de auto organización, por acuerdo del órgano de gobierno la correspondiente administración.","Mediante Ley de las Cortes Generales o de las Asambleas legislativas de las Comunidades Autónomas."],"bloque":"provision","precepto":"Art. 75.2 del TREBEP","correcta":3,"justificaciones":["No. La Conferencia Sectorial no modifica cuerpos y escalas.","No. Un real decreto no basta: hace falta ley.","No. La autoorganización no permite modificarlos por simple acuerdo: hace falta ley.","Es esta. Mediante ley de las Cortes Generales o de las asambleas legislativas autonómicas (**art. 75.2**)."]},{"id":"au-15-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":4,"enunciado":"Señale la respuesta incorrecta. Las Administraciones Públicas estructurarán su organización a través de relaciones de puestos de trabajo u otros instrumentos organizativos similares que comprenderán, al menos:","opciones":["La denominación de los puestos de trabajo.","Los sistemas de provisión de los puestos de trabajo.","Las retribuciones básicas de los puestos de trabajo.","Los cuerpos o escalas a que estén adscritos los puestos de trabajo."],"bloque":"provision","precepto":"Art. 74 del TREBEP","correcta":2,"justificaciones":["Es verdadera, así que no se marca (**art. 74**).","Es verdadera, así que no se marca (**art. 74**).","Esta es la falsa, y por eso es la que hay que marcar. Las relaciones de puestos incluyen las retribuciones complementarias, no las básicas (**art. 74**).","Es verdadera, así que no se marca (**art. 74**)."]},{"id":"au-15-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":5,"enunciado":"En relación con la Oferta de empleo público, no es cierto, según el TREBEP, que","opciones":["Comportará la obligación de convocar los procesos selectivos para las plazas comprometidas y hasta un 10% adicional.","La ejecución de la misma deberá desarrollarse dentro del plazo improrrogable de 3 años.","Se aprobará anualmente.","Deberá contener, en todo caso, medidas derivadas de la planificación de recursos humanos."],"bloque":"provision","precepto":"Art. 70 del TREBEP","correcta":3,"justificaciones":["Es cierta (**art. 70.1**), así que no se marca.","Es cierta (**art. 70.1**), así que no se marca.","Es cierta (**art. 70.2**), así que no se marca.","Es esta. La oferta podrá contener medidas derivadas de la planificación, no deberá contenerlas en todo caso (**art. 70.3**)."]},{"id":"au-15-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":6,"enunciado":"En el TREBEP no se establece literalmente que las relaciones de puestos de trabajo comprendan:","opciones":["La denominación de los puestos de trabajo.","La totalidad de las retribuciones de los mismos.","Los grupos de clasificación profesional a que estén adscritos.","Los sistemas de provisión."],"bloque":"provision","precepto":"Art. 74 del TREBEP","correcta":1,"justificaciones":["No. Sí lo dice literalmente (**art. 74**).","Es esta. El artículo menciona las retribuciones complementarias, no la totalidad de las retribuciones (**art. 74**).","No. Sí lo dice literalmente: los grupos de clasificación profesional (**art. 74**).","No. Sí lo dice literalmente: los sistemas de provisión (**art. 74**)."]},{"id":"au-15-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":7,"enunciado":"En aplicación del artículo 70 del TREBEP, y en relación con la oferta de empleo público, señale la respuesta correcta:","opciones":["Tendrán como objeto necesidades de recursos humanos que deban proveerse mediante convocatorias de promoción interna.","En todo caso, la ejecución de la oferta de empleo público deberá desarrollarse dentro del plazo improrrogable de dos años.","Se aprobará anualmente por los órganos de Gobierno de las Administraciones Públicas.","Su aprobación comportará la obligación de convocar procesos selectivos para las plazas comprometidas y un 7% adicional."],"bloque":"provision","precepto":"Art. 70.2 del TREBEP","correcta":2,"justificaciones":["No. Su objeto son las necesidades que se provean con personal de nuevo ingreso, no la promoción interna.","No. El plazo es de tres años, no de dos.","Es esta. Se aprueba anualmente por los órganos de Gobierno de las Administraciones Públicas (**art. 70.2**).","No. El adicional es de hasta un diez por cien, no un 7 %."]},{"id":"au-15-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":8,"enunciado":"¿Qué instrumento de planificación de los recursos humanos en las Administraciones Públicas tiene como objetivo establecer las necesidades de recursos humanos para proveer mediante la incorporación de personal de nuevo ingreso?","opciones":["La Oferta de Empleo Público.","Los Registros de personal.","Los Planes de ordenación de los recursos humanos.","Las Relaciones de puestos de trabajo."],"bloque":"provision","precepto":"Art. 70.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Las necesidades que se proveen con personal de nuevo ingreso son objeto de la Oferta de empleo público (**art. 70.1**).","No. Los registros recogen datos del personal.","No. Los planes de ordenación son más amplios (**art. 69.2**).","No. Las relaciones de puestos estructuran la organización (**art. 74**)."],"dup":"au-15-008"},{"id":"au-15-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":9,"enunciado":"Según el TREBEP la ejecución de la oferta de empleo público o instrumento similar deberá desarrollarse:","opciones":["Dentro del plazo de dos años, prorrogable por dos más en casos de concurrir circunstancias excepcionales.","Dentro del plazo improrrogable de cuatro años.","Dentro del plazo improrrogable de dos años.","Dentro del plazo improrrogable de tres años."],"bloque":"provision","precepto":"Art. 70.1 del TREBEP","correcta":3,"justificaciones":["No. El plazo es de tres años y no se prorroga.","No. El plazo es de tres años, no de cuatro.","No. El plazo es de tres años, no de dos.","Es esta. Dentro del plazo improrrogable de tres años (**art. 70.1**)."]},{"id":"au-15-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":10,"enunciado":"Se exigirá estar en posesión del título de Técnico Superior para el acceso a los cuerpos o escalas del Grupo:","opciones":["B.","C2.","C1.","A."],"bloque":"provision","precepto":"Art. 76 del TREBEP","correcta":0,"justificaciones":["Es esta. Para el Grupo B se exige el título de Técnico Superior (**art. 76**).","No. En C2 el título es el de Graduado en ESO.","No. En C1 el título es el de Bachiller o Técnico.","No. En el Grupo A se exige título universitario de Grado."]},{"id":"au-15-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":11,"enunciado":"Según el artículo 76 del TREBEP, el Título de Graduado en Educación Secundaria Obligatoria nos permite el acceso a Cuerpos o Escalas del Subgrupo:","opciones":["B2.","C1.","B1.","C2."],"bloque":"provision","precepto":"Art. 76 del TREBEP","correcta":3,"justificaciones":["No. El Grupo B no se divide en subgrupos y exige Técnico Superior.","No. C1 exige Bachiller o Técnico.","No. El Grupo B no se divide en subgrupos.","Es esta. El título de Graduado en ESO permite el acceso al Subgrupo C2 (**art. 76**)."]},{"id":"au-15-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":12,"enunciado":"Conforme al TREBEP, los cuerpos y escalas de funcionarios se crean, modifican y suprimen por:","opciones":["Real Decreto del Consejo de Ministros u órgano correspondiente de las comunidades autónomas.","Reglamento del Consejo de Ministros u Órgano de Gobierno de las comunidades autónomas.","Orden Ministerial.","Ley de las Cortes Generales o de las asambleas legislativas de las comunidades autónomas."],"bloque":"provision","precepto":"Art. 75.2 del TREBEP","correcta":3,"justificaciones":["No. Un real decreto no basta: hace falta ley.","No. Un reglamento no basta: hace falta ley.","No. Una orden ministerial no basta: hace falta ley.","Es esta. Ley de las Cortes Generales o de las asambleas legislativas autonómicas (**art. 75.2**)."]},{"id":"au-15-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":13,"enunciado":"De acuerdo con el artículo 76 del TREBEP, el Título de Bachiller o Técnico nos permite el acceso:","opciones":["Al Grupo B.","Al Subgrupo C1.","Al Subgrupo A1.","Al Subgrupo A2."],"bloque":"provision","precepto":"Art. 76 del TREBEP","correcta":1,"justificaciones":["No. El Grupo B exige Técnico Superior.","Es esta. Bachiller o Técnico permite el acceso al Subgrupo C1 (**art. 76**).","No. El Subgrupo A1 exige título universitario de Grado.","No. El Subgrupo A2 exige título universitario de Grado."]},{"id":"au-15-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":14,"enunciado":"Los cuerpos y escalas del personal funcionario de carrera se clasifican, de acuerdo con la titulación exigida para el acceso a los mismos, en los siguientes grupos:","opciones":["Grupo A, Grupo B (dividido en los Subgrupos B1 y B2) y Grupo C (dividido en los Subgrupos C1 y C2).","Grupo A (dividido en los Subgrupos A1 y A2), Grupo B (dividido en los Subgrupos B1 y B2) y Grupo C.","Grupo A, Grupo B y Grupo C (dividido en los Subgrupos C1 y C2).","Grupo A (dividido en los Subgrupos A1 y A2), Grupo B y Grupo C (dividido en los Subgrupos C1 y C2)."],"bloque":"provision","precepto":"Art. 76 del TREBEP","correcta":3,"justificaciones":["No. El Grupo A se divide en A1 y A2, y el B no se divide.","No. El Grupo B no se divide, y el C sí.","No. El Grupo A sí se divide en A1 y A2.","Es esta. Grupo A (A1 y A2), Grupo B y Grupo C (C1 y C2) (**art. 76**)."]},{"id":"au-15-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":15,"enunciado":"Indique cuál de los siguientes grupos de funcionarios públicos no se subdivide en subgrupos:","opciones":["A.","B.","C.","D."],"bloque":"provision","precepto":"Art. 76 del TREBEP","correcta":1,"justificaciones":["No. El Grupo A se divide en A1 y A2.","Es esta. El Grupo B no se divide en subgrupos (**art. 76**).","No. El Grupo C se divide en C1 y C2.","No. No existe un Grupo D en el TREBEP."]},{"id":"au-15-016","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":16,"enunciado":"Conforme al artículo 71 del TREBEP, los contenidos mínimos comunes de los Registros de personal y los criterios que permitan el intercambio homogéneo de la información entre Administraciones se establecerán:","opciones":["Por cada Administración Pública.","Por Real Decreto del Consejo de Ministros.","Mediante convenio de Conferencia Sectorial.","A través de la negociación colectiva."],"bloque":"provision","precepto":"Art. 71.3 del TREBEP","correcta":2,"justificaciones":["No. Son contenidos comunes, así que no los fija cada Administración por separado.","No. No se fijan por real decreto.","Es esta. Mediante convenio de Conferencia Sectorial (**art. 71.3**).","No. No es materia de negociación colectiva."]},{"id":"au-15-017","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":17,"enunciado":"Las Administraciones Públicas podrán aprobar Planes para la ordenación de sus recursos humanos, que incluyan:","opciones":["Previsiones sobre los sistemas de organización del trabajo y modificaciones de estructuras de puestos de trabajo.","Medidas de promoción interna y de formación del personal y de movilidad forzosa.","La previsión de la incorporación de recursos humanos a través de la Oferta de empleo público.","Todas son correctas."],"bloque":"provision","precepto":"Art. 69.2 del TREBEP","correcta":3,"justificaciones":["No. Es correcta (**art. 69.2.b**), pero la opción correcta es la que recoge todas.","No. Es correcta (**art. 69.2.d**), pero la opción correcta es la que recoge todas.","No. Es correcta (**art. 69.2.e**), pero la opción correcta es la que recoge todas.","Es esta. Las tres medidas figuran en el **art. 69.2**."]},{"id":"au-15-018","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":18,"enunciado":"Las necesidades de recursos humanos, con asignación presupuestaria, que deban proveerse mediante incorporación de personal de nuevo ingreso serán objeto de la Oferta de empleo público, lo que comportará la obligación de convocar los correspondientes procesos selectivos para las plazas comprometidas y:","opciones":["Hasta un 10% adicional.","Hasta un 20% adicional.","Hasta un 30% adicional.","Hasta un 40% adicional."],"bloque":"provision","precepto":"Art. 70.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Obliga a convocar las plazas comprometidas y hasta un diez por cien adicional (**art. 70.1**).","No. El adicional es del diez por cien, no del 20.","No. El adicional es del diez por cien, no del 30.","No. El adicional es del diez por cien, no del 40."]},{"id":"au-15-019","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":19,"enunciado":"Respecto a los Registros de personal y la gestión integrada de recursos humanos, cuando las Entidades Locales no cuenten con la suficiente capacidad financiera o técnica:","opciones":["Solo la Administración General del Estado cooperará con aquellas.","Solo las Comunidades Autónomas cooperarán con aquellas.","La Administración General del Estado y las Comunidades Autónomas cooperarán con aquellas.","No será precisa su implantación en el ente local que no posea medios adecuados y suficientes."],"bloque":"provision","precepto":"Art. 71.5 del TREBEP","correcta":2,"justificaciones":["No. También cooperan las comunidades autónomas.","No. También coopera la Administración General del Estado.","Es esta. La Administración General del Estado y las comunidades autónomas cooperan con ellas (**art. 71.5**).","No. El artículo prevé cooperación, no exención de implantarlo."]},{"id":"au-15-020","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 15) - arts. 69 a 77","n":20,"enunciado":"Los puestos de trabajo podrán agruparse en función de sus características para ordenar:","opciones":["La selección.","La formación.","La movilidad.","Todas son correctas."],"bloque":"provision","precepto":"Art. 73.3 del TREBEP","correcta":3,"justificaciones":["No. Es correcta (**art. 73.3**), pero la opción correcta es la que recoge todas.","No. Es correcta (**art. 73.3**), pero la opción correcta es la que recoge todas.","No. Es correcta (**art. 73.3**), pero la opción correcta es la que recoge todas.","Es esta. Pueden agruparse para ordenar la selección, la formación y la movilidad (**art. 73.3**)."]},{"id":"au-16-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":1,"enunciado":"De acuerdo con el artículo 78 del TREBEP, la provisión de puestos de trabajo se llevará a cabo por los procedimientos de:","opciones":["Oposición libre.","Concurso oposición.","Concurso y libre designación con convocatoria pública.","Oposición libre, concurso oposición y, excepcionalmente, concurso."],"bloque":"provision","precepto":"Art. 78.2 del TREBEP","correcta":2,"justificaciones":["No. La oposición es un sistema de selección de personal, no de provisión de puestos.","No. El concurso-oposición es un sistema de selección, no de provisión.","Es esta. Concurso y libre designación con convocatoria pública (**art. 78.2**).","No. Son sistemas selectivos, no de provisión de puestos."]},{"id":"au-16-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":2,"enunciado":"¿Cuál es el procedimiento normal de provisión de puestos de trabajo del personal funcionario de carrera, según lo establecido en el artículo 79 del TREBEP?","opciones":["El concurso.","El concurso-oposición.","La libre designación.","La movilidad entre Administraciones Públicas."],"bloque":"provision","precepto":"Art. 79.1 del TREBEP","correcta":0,"justificaciones":["Es esta. El concurso es el procedimiento normal de provisión (**art. 79.1**).","No. El concurso-oposición es un sistema selectivo.","No. La libre designación no es el procedimiento normal.","No. La movilidad interadministrativa no es el procedimiento normal de provisión."]},{"id":"au-16-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":3,"enunciado":"La provisión de puestos de trabajo de personal funcionario de carrera se llevará a cabo, según el artículo 78 del TREBEP:","opciones":["Mediante procedimientos basados en los principios de igualdad, mérito, capacidad y publicidad.","Por los procedimientos de concurso y de libre designación sin convocatoria pública.","Exclusivamente por los procedimientos de concurso y de libre designación.","Por los sistemas de concurso, concurso-oposición y, excepcionalmente, cuando lo autorice la Ley, mediante concurso."],"bloque":"provision","precepto":"Art. 78 del TREBEP","correcta":0,"justificaciones":["Es esta. Se provee mediante procedimientos basados en igualdad, mérito, capacidad y publicidad (**art. 78.1**).","No. La libre designación es con convocatoria pública.","No. No es exclusivo: las leyes pueden establecer otros procedimientos (**art. 78.3**).","No. Esos son sistemas de selección, no de provisión."]},{"id":"au-16-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":4,"enunciado":"El Texto Refundido de la Ley del Estatuto Básico del Empleado Público considera la movilidad por razón de violencia de género o de violencia sexual:","opciones":["Un proceso de movilidad voluntaria.","Un nombramiento provisional.","Un traslado forzoso.","Un traslado voluntario."],"bloque":"provision","precepto":"Art. 82.1 del TREBEP","correcta":2,"justificaciones":["No. No es movilidad voluntaria.","No. No es un nombramiento provisional.","Es esta. Este traslado tiene la consideración de traslado forzoso (**art. 82.1**).","No. No es un traslado voluntario."]},{"id":"au-16-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":5,"enunciado":"Conforme al artículo 84 del TREBEP, cuando un funcionario de carrera obtenga destino en otra Administración Pública a través de un concurso y, posteriormente, se produzca la supresión de dicho puesto, el funcionario:","opciones":["Deberá solicitar en el plazo máximo de un mes el reingreso al servicio activo en su Administración de origen.","Retornará a la Administración de origen o permanecerá en la Administración de destino, según decida esta última.","Permanecerá en la Administración de destino, que deberá asignarle un puesto de trabajo.","Deberá solicitar en el plazo máximo de dos meses el reingreso al servicio activo en su Administración de origen."],"bloque":"provision","precepto":"Art. 84.3 del TREBEP","correcta":2,"justificaciones":["No. El plazo de un mes para solicitar reingreso es del cese por libre designación, no de la supresión de un puesto de concurso.","No. No lo decide la Administración de destino: permanece en ella.","Es esta. Permanece en la Administración de destino, que debe asignarle un puesto (**art. 84.3**).","No. Dos meses no figura y no tiene que reingresar."]},{"id":"au-16-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":6,"enunciado":"El Texto Refundido de la Ley del Estatuto Básico del Empleado Público considera la movilidad por razón de violencia terrorista:","opciones":["Un proceso de movilidad voluntaria.","Un nombramiento provisional.","Un traslado voluntario.","Un traslado forzoso."],"bloque":"provision","precepto":"Art. 82.2 del TREBEP","correcta":3,"justificaciones":["No. No es movilidad voluntaria.","No. No es un nombramiento provisional.","No. No es un traslado voluntario.","Es esta. Este traslado tiene la consideración de traslado forzoso (**art. 82.2**)."]},{"id":"au-16-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":7,"enunciado":"El sistema de provisión de puestos de trabajo que consiste en la valoración de los méritos y capacidades y, en su caso, aptitudes de los candidatos por órganos colegiados de carácter técnico se denomina:","opciones":["Oposición libre.","Libre designación.","Evaluación del desempeño.","Concurso."],"bloque":"provision","precepto":"Art. 79.1 del TREBEP","correcta":3,"justificaciones":["No. La oposición es un sistema selectivo.","No. La libre designación es la apreciación discrecional de la idoneidad.","No. La evaluación del desempeño no es un sistema de provisión.","Es esta. El concurso consiste en la valoración de méritos y capacidades por órganos colegiados de carácter técnico (**art. 79.1**)."]},{"id":"au-16-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":8,"enunciado":"Conforme al artículo 79 del TREBEP, las leyes de Función Pública que se dicten en desarrollo del presente Estatuto establecerán el plazo mínimo de ocupación de los puestos obtenidos por concurso para poder participar en otros concursos:","opciones":["El cual será, como mínimo, de 1 año.","El cual será, como mínimo, de 2 años.","El cual será, como máximo, de 2 años.","Sin especificar el TREBEP cuál deba ser dicho plazo mínimo de ocupación."],"bloque":"provision","precepto":"Art. 79.2 del TREBEP","correcta":3,"justificaciones":["No. El TREBEP no fija un año.","No. El TREBEP no fija dos años.","No. El TREBEP no fija un máximo de dos años.","Es esta. Son las leyes de Función Pública las que establecerán el plazo, sin que el TREBEP lo especifique (**art. 79.2**)."]},{"id":"au-16-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":9,"enunciado":"La provisión de puestos de trabajo del personal funcionario de carrera en cada Administración Pública se llevará a cabo:","opciones":["Por los procedimientos de concurso y de libre designación con convocatoria pública.","Por los procedimientos de concurso-oposición y de libre designación con convocatoria pública.","Por el procedimiento de libre designación sin convocatoria pública.","Por los procedimientos de concurso y oposición."],"bloque":"provision","precepto":"Art. 78.2 del TREBEP","correcta":0,"justificaciones":["Es esta. Por concurso y libre designación con convocatoria pública (**art. 78.2**).","No. El concurso-oposición no es un procedimiento de provisión.","No. La libre designación es con convocatoria pública.","No. La oposición no es un procedimiento de provisión."]},{"id":"au-16-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":10,"enunciado":"En caso de movilidad de un funcionario de carrera por necesidades del servicio a un departamento distinto de su destino:","opciones":["Se podrán modificar sus condiciones esenciales de trabajo pero se deberán respetar sus retribuciones.","Se deben respetar sus retribuciones y condiciones esenciales de trabajo.","Se podrán modificar tanto las condiciones esenciales de trabajo como sus retribuciones.","Se respetarán sus condiciones esenciales de trabajo pero recibirá la retribución correspondiente al nuevo destino."],"bloque":"provision","precepto":"Art. 81.2 del TREBEP","correcta":1,"justificaciones":["No. También se deben respetar las condiciones esenciales de trabajo.","Es esta. El traslado por necesidades del servicio respeta las retribuciones y las condiciones esenciales de trabajo (**art. 81.2**).","No. No se pueden modificar ni las condiciones ni las retribuciones.","No. No cambia la retribución: se respetan sus retribuciones."]},{"id":"au-16-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":11,"enunciado":"Según el artículo 82 del TREBEP, las mujeres víctimas de violencia de género que se vean obligadas a abandonar el puesto de trabajo en la localidad donde venían prestando servicios tendrán derecho al traslado a otro puesto de análogas características:","opciones":["Propio de su cuerpo, escala o categoría profesional, sin necesidad de que sea vacante de necesaria cobertura.","Propio de su cuerpo, escala o categoría profesional, siempre que sea vacante de necesaria cobertura.","Propio de su cuerpo, escala o categoría profesional, aun cuando dicho puesto no se encontrara vacante.","Propio de su cuerpo, escala o categoría profesional, siempre que se encuentre dentro de la misma Comunidad Autónoma."],"bloque":"provision","precepto":"Art. 82.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Traslado a un puesto propio de su cuerpo, escala o categoría, de análogas características, sin necesidad de que sea vacante de necesaria cobertura (**art. 82.1**).","No. No se exige que sea vacante de necesaria cobertura.","No. La idea es correcta, pero la formulación literal es la de la opción que dice sin necesidad de vacante de necesaria cobertura.","No. No se limita a la misma comunidad autónoma."]},{"id":"au-16-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":12,"enunciado":"Según el TREBEP, en el supuesto de cese del puesto obtenido por libre designación, la Administración de destino podrá acordar la adscripción del funcionario a otro puesto de la misma:","opciones":["En el plazo máximo de treinta días a contar desde el día del cese.","En el plazo máximo de dos meses a contar desde el día del cese.","En el plazo máximo de un mes a contar desde el día siguiente al del cese.","En el plazo máximo de dos meses a contar desde el día siguiente al del cese."],"bloque":"provision","precepto":"Art. 84.3 del TREBEP","correcta":2,"justificaciones":["No. El plazo es de un mes, no de treinta días, y cuenta desde el día siguiente.","No. El plazo es de un mes, no de dos.","Es esta. En el plazo máximo de un mes a contar desde el día siguiente al del cese (**art. 84.3**).","No. El plazo es de un mes, no de dos."]},{"id":"au-16-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":13,"enunciado":"Siguiendo las previsiones recogidas en el TREBEP, tendrán la consideración de traslado forzoso:","opciones":["El traslado del funcionario, su cónyuge o hijos a cargo por motivos de salud o de rehabilitación.","La atribución temporal de funciones.","La comisión de servicios y la movilidad de la funcionaria víctima de violencia de género.","La movilidad de la funcionaria víctima de violencia de género o violencia sexual y de los funcionarios víctimas del terrorismo."],"bloque":"provision","precepto":"Art. 82 del TREBEP","correcta":3,"justificaciones":["No. El traslado por motivos de salud no es forzoso.","No. La atribución temporal de funciones no es traslado forzoso.","No. La comisión de servicios no es traslado forzoso.","Es esta. La movilidad de las víctimas de violencia de género o sexual y de los funcionarios víctimas del terrorismo es traslado forzoso (**art. 82**)."]},{"id":"au-16-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":14,"enunciado":"Conforme al artículo 84 del TREBEP, una vez cesado, sin que se acordado su adscripción a otro puesto en el plazo legalmente establecido, ¿de qué plazo dispone un funcionario que ocupase un puesto de libre designación en otra Administración Pública para solicitar el reingreso al servicio activo en su Administración de origen?","opciones":["Treinta días.","Dos meses.","Quince días.","Un mes."],"bloque":"provision","precepto":"Art. 84.3 del TREBEP","correcta":3,"justificaciones":["No. El plazo es de un mes, no de treinta días.","No. El plazo es de un mes, no de dos.","No. El plazo es de un mes, no de quince días.","Es esta. Debe solicitar el reingreso en el plazo máximo de un mes (**art. 84.3**)."]},{"id":"au-16-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":15,"enunciado":"En relación con la pregunta anterior, de no solicitar en el plazo establecido el reingreso al servicio activo en su Administración de origen, el funcionario será declarado de oficio en la situación administrativa de:","opciones":["Excedencia forzosa.","Excedencia voluntaria por interés particular.","Servicios en otras Administraciones Públicas.","Suspensión de funciones."],"sigueA":"au-16-014","bloque":"provision","precepto":"Art. 84.3 del TREBEP","correcta":1,"justificaciones":["No. No se le declara en excedencia forzosa.","Es esta. Será declarado de oficio en excedencia voluntaria por interés particular (**art. 84.3**).","No. Esa es la situación mientras está en la otra Administración.","No. No se le declara en suspensión de funciones."]},{"id":"au-16-016","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":16,"enunciado":"Según el TREBEP, ¿a quién corresponde aprobar los criterios generales a tener en cuenta para llevar a cabo las homologaciones necesarias para hacer posible la movilidad voluntaria entre Administraciones Públicas?","opciones":["Al Consejo de Ministros.","A las Cortes Generales.","A la Conferencia Sectorial de Administración Pública.","Al Ministerio competente en materia de Función Pública."],"bloque":"provision","precepto":"Art. 84.2 del TREBEP","correcta":2,"justificaciones":["No. No lo aprueba el Consejo de Ministros.","No. No lo aprueban las Cortes Generales.","Es esta. La Conferencia Sectorial de Administración Pública aprueba los criterios generales (**art. 84.2**).","No. No lo aprueba el ministerio."]},{"id":"au-16-017","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":17,"enunciado":"La libre designación con convocatoria pública del personal funcionario de carrera consiste en:","opciones":["La apreciación discrecional por el órgano competente de la idoneidad de los candidatos para el desempeño del puesto.","La valoración de los méritos y capacidades y, en su caso, aptitudes de los candidatos por el órgano competente.","La apreciación reglada por el órgano competente de la idoneidad de los candidatos para el desempeño del puesto.","La superación de un proceso de entrevistas, exposiciones curriculares y otros sistemas subjetivos de valoración de méritos."],"bloque":"provision","precepto":"Art. 80.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Consiste en la apreciación discrecional por el órgano competente de la idoneidad de los candidatos (**art. 80.1**).","No. Eso describe el concurso (**art. 79.1**).","No. Es discrecional, no reglada.","No. No se define por entrevistas o sistemas subjetivos de valoración de méritos."]},{"id":"au-16-018","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":18,"enunciado":"Según el artículo 84 del TREBEP, los funcionarios de carrera que obtengan destino en otra Administración Pública a través de los procedimientos de movilidad quedarán respecto de su Administración de origen en la situación administrativa de:","opciones":["Excedencia voluntaria por prestación de servicios en el sector público.","Servicio en Comunidades Autónomas.","Servicio en otras Administraciones Públicas.","Servicio activo con destino en Administración distinta."],"bloque":"provision","precepto":"Art. 84.3 del TREBEP","correcta":2,"justificaciones":["No. No es excedencia voluntaria.","No. No es servicio en comunidades autónomas.","Es esta. Quedan en servicio en otras Administraciones Públicas (**art. 84.3**).","No. No es servicio activo con destino en otra Administración."]},{"id":"au-16-019","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":19,"enunciado":"Conforme al artículo 78 del TREBEP, las Administraciones Públicas proveerán los puestos de trabajo mediante procedimientos basados en los principios de:","opciones":["Equidad, mérito, capacidad y publicidad.","Igualdad, mérito, capacidad y celeridad.","Igualdad, mérito, capacidad y publicidad.","Igualdad, capacidad, idoneidad y publicidad."],"bloque":"provision","precepto":"Art. 78.1 del TREBEP","correcta":2,"justificaciones":["No. No es equidad, sino igualdad.","No. El último principio es la publicidad, no la celeridad.","Es esta. Igualdad, mérito, capacidad y publicidad (**art. 78.1**).","No. Faltan mérito y la idoneidad no es un principio del artículo."]},{"id":"au-16-020","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 16) - arts. 78 a 84","n":20,"enunciado":"Señale la respuesta correcta en relación con la provisión de puestos de trabajo del personal funcionario de carrera:","opciones":["El concurso y la libre designación son los procedimientos normales de provisión de puestos de trabajo.","Se llevará a cabo, exclusivamente, por los procedimientos de concurso y de libre designación con convocatoria pública.","Un funcionario de carrera que haya obtenido un puesto por concurso no podrá participar en otros durante un plazo de un año.","En caso de urgente e inaplazable necesidad, los puestos de trabajo podrán proveerse con carácter provisional."],"bloque":"provision","precepto":"Art. 81.3 del TREBEP","correcta":3,"justificaciones":["No. El procedimiento normal es el concurso (**art. 79.1**); la libre designación es otro procedimiento.","No. No es exclusivo: las leyes pueden establecer otros procedimientos (**art. 78.3**).","No. El plazo mínimo lo fijan las leyes de Función Pública, no es un año (**art. 79.2**).","Es esta. En caso de urgente e inaplazable necesidad, los puestos pueden proveerse con carácter provisional (**art. 81.3**)."]},{"id":"of-01-001","origen":"oficiales","test":"TREBEP (Oficial 1) - arts. 1 a 7","n":1,"enunciado":"Según su artículo 6 del TREBEP, ¿quiénes están habilitados para desarrollar el Real Decreto Legislativo 5/2015?","opciones":["El TREBEP no necesita desarrollo.","Las Cortes Generales, exclusivamente.","Las Asambleas Legislativas de las Comunidades Autónomas, exclusivamente.","Las Cortes Generales y las Asambleas Legislativas de las Comunidades Autónomas, en el ámbito de sus competencias."],"bloque":"ambito","precepto":"Art. 6 del TREBEP","correcta":3,"justificaciones":["No. El Estatuto sí se desarrolla por leyes de Función Pública (**art. 6**).","No. También lo hacen las asambleas legislativas autonómicas.","No. También lo hacen las Cortes Generales.","Es esta. Las Cortes Generales y las asambleas legislativas de las comunidades autónomas, en el ámbito de sus competencias (**art. 6**)."]},{"id":"of-01-002","origen":"oficiales","test":"TREBEP (Oficial 1) - arts. 1 a 7","n":2,"enunciado":"Según el artículo 4 el texto refundido de la Ley del Estatuto Básico del Empleado Público, las disposiciones de este Estatuto solo se aplicarán directamente cuando así lo disponga su legislación específica al siguiente personal:","opciones":["Personal del Banco de España.","Personal de Universidades Públicas.","Personal que presta sus servicios en Organismos Públicos.","Personal docente."],"bloque":"ambito","precepto":"Art. 4 del TREBEP","correcta":0,"justificaciones":["Es esta. El personal del Banco de España y del Fondo de Garantía de Depósitos está en el **art. 4.h**.","No. Las Universidades Públicas están en el ámbito de aplicación del **art. 2.1.e**.","No. Los organismos públicos están en el ámbito de aplicación del **art. 2.1.d**.","No. El personal docente se rige por su legislación específica y por el Estatuto (**art. 2.3**), no está en el art. 4."]},{"id":"of-01-003","origen":"oficiales","test":"TREBEP (Oficial 1) - arts. 1 a 7","n":3,"enunciado":"Atendiendo al artículo 4 del TREBEP, ¿cuál de los siguientes tipos de personal NO se encuentra sujeto a legislación específica propia en materia de función pública?","opciones":["El personal militar de las Fuerzas Armadas.","El personal del Centro Nacional de Inteligencia.","El personal del Instituto Nacional de Estadística.","El personal retribuido por arancel."],"bloque":"ambito","precepto":"Art. 4 del TREBEP","correcta":2,"justificaciones":["No. El personal militar de las Fuerzas Armadas sí tiene legislación específica (**art. 4.d**).","No. El personal del Centro Nacional de Inteligencia sí la tiene (**art. 4.g**).","Es esta. El personal del Instituto Nacional de Estadística no figura en el **art. 4**.","No. El personal retribuido por arancel sí la tiene (**art. 4.f**)."]},{"id":"of-01-004","origen":"oficiales","test":"TREBEP (Oficial 1) - arts. 1 a 7","n":4,"enunciado":"El artículo 2.2 del TREBEP establece en relación con el personal de investigación que:","opciones":["Se regirá por su legislación específica, excepto para aquellos preceptos que se indique que le son de aplicación directa.","No le es de aplicación el TREBEP en ningún caso.","Le es de aplicación el TREBEP pero se podrán dictar normas singulares para adecuarlo a sus peculiaridades.","Como en los casos del personal docente, se regirá por su legislación específica y en lo no regulado por esta, por el Estatuto."],"bloque":"ambito","precepto":"Art. 2.2 del TREBEP","correcta":2,"justificaciones":["No. Eso se parece al personal docente y de salud (**art. 2.3**), no al investigador.","No. Sí le es de aplicación.","Es esta. Se le aplica, pudiendo dictarse normas singulares para adecuarlo a sus peculiaridades (**art. 2.2**).","No. La regla de legislación específica y Estatuto es la del personal docente y de salud (**art. 2.3**)."]},{"id":"of-01-005","origen":"oficiales","test":"TREBEP (Oficial 1) - arts. 1 a 7","n":5,"enunciado":"El Estatuto Básico del Empleado Público se aplica directamente al personal de las Fuerzas y Cuerpos de Seguridad:","opciones":["En todos los aspectos que la Ley regula.","Cuando así lo disponga su legislación específica.","No se les aplica en ningún supuesto.","Se aplica en todo menos en el régimen disciplinario."],"bloque":"ambito","precepto":"Art. 4.e del TREBEP","correcta":1,"justificaciones":["No. Solo se aplica directamente si lo dispone su legislación específica.","Es esta. Solo cuando así lo disponga su legislación específica (**art. 4.e**).","No. Sí se aplica, cuando lo disponga su legislación específica.","No. No hay excepción del régimen disciplinario: la regla es la del **art. 4**."]},{"id":"of-01-006","origen":"oficiales","test":"TREBEP (Oficial 1) - arts. 1 a 7","n":6,"enunciado":"El TREBEP solo se aplica directamente cuando así lo disponga su legislación específica al siguiente personal:","opciones":["Estatutario de los Servicios de Salud.","De las Universidades Públicas.","De las Agencias vinculadas o dependientes de cualquiera de las Administraciones Públicas.","De las Fuerzas y Cuerpos de Seguridad del Estado."],"bloque":"ambito","precepto":"Art. 4.e del TREBEP","correcta":3,"justificaciones":["No. El personal estatutario se rige por su legislación específica y el Estatuto (**art. 2.3**).","No. Las Universidades Públicas están en el ámbito del **art. 2.1.e**.","No. Las agencias están en el ámbito del **art. 2.1.d**.","Es esta. Las Fuerzas y Cuerpos de Seguridad están en el **art. 4.e**."]},{"id":"of-01-007","origen":"oficiales","test":"TREBEP (Oficial 1) - arts. 1 a 7","n":7,"enunciado":"Según el TREBEP, ¿cuál es la normativa aplicable al personal laboral al servicio de las Administraciones Públicas?","opciones":["El Estatuto de los Trabajadores, exclusivamente.","Las normas laborales convencionalmente aplicables y los preceptos del TREBEP que así lo dispongan, exclusivamente.","La legislación laboral, competencia exclusiva del Estado y de las Comunidades Autónomas.","La legislación laboral, normas convencionalmente aplicables y preceptos del TREBEP que así lo dispongan."],"bloque":"ambito","precepto":"Art. 7 del TREBEP","correcta":3,"justificaciones":["No. No es exclusivamente el Estatuto de los Trabajadores.","No. Falta la legislación laboral y el \"exclusivamente\" es incorrecto.","No. No es el criterio del **art. 7**.","Es esta. Legislación laboral, normas convencionales y los preceptos del Estatuto que así lo dispongan (**art. 7**)."]},{"id":"of-01-008","origen":"oficiales","test":"TREBEP (Oficial 1) - arts. 1 a 7","n":8,"enunciado":"Conforme al artículo 4 del TREBEP, las disposiciones de dicho Estatuto sólo se aplicarán directamente cuando así lo disponga su legislación específica al siguiente personal:","opciones":["Personal funcionario al servicio de la Administración de Justicia.","Personal docente.","Personal de servicios de salud.","Personal de las Universidades Públicas."],"bloque":"ambito","precepto":"Art. 4.c del TREBEP","correcta":0,"justificaciones":["Es esta. El personal al servicio de la Administración de Justicia está en el **art. 4.c**.","No. El personal docente se rige por el **art. 2.3**.","No. El personal de servicios de salud se rige por el **art. 2.3**.","No. Las Universidades Públicas están en el ámbito del **art. 2.1.e**."]},{"id":"of-01-009","origen":"oficiales","test":"TREBEP (Oficial 1) - arts. 1 a 7","n":9,"enunciado":"El TREBEP se aplicará directamente, sin necesidad de que así lo disponga su legislación específica, al siguiente personal:","opciones":["Personal funcionario de las Cortes Generales.","Personal del Centro Nacional de Inteligencia.","Personal de las Universidades Públicas.","Personal funcionario de las Asambleas Legislativas de las Comunidades Autónomas."],"bloque":"ambito","precepto":"Art. 2.1.e del TREBEP","correcta":2,"justificaciones":["No. Las Cortes Generales están en el **art. 4.a**.","No. El Centro Nacional de Inteligencia está en el **art. 4.g**.","Es esta. Las Universidades Públicas están en el ámbito de aplicación directo (**art. 2.1.e**).","No. Las asambleas legislativas autonómicas están en el **art. 4.a**."]},{"id":"of-01-010","origen":"oficiales","test":"TREBEP (Oficial 1) - arts. 1 a 7","n":10,"enunciado":"Conforme al artículo 7 del TREBEP ¿sobre qué materia está previsto que el personal laboral al servicio de las Administraciones públicas se regirá por el presente Estatuto, no siéndole de aplicación, por tanto, las previsiones del Texto Refundido de la Ley del Estatuto de los Trabajadores?","opciones":["Materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica y lactancia.","Materia de representación sindical.","Materia de extinción del contrato.","Materia de infracciones y sanciones."],"bloque":"ambito","precepto":"Art. 7 del TREBEP","correcta":0,"justificaciones":["Es esta. En permisos de nacimiento, adopción, del progenitor diferente de la madre biológica y lactancia se rige por el Estatuto (**art. 7**).","No. La representación sindical no es la materia del **art. 7**.","No. La extinción del contrato no es la materia del **art. 7**.","No. Las infracciones y sanciones no son la materia del **art. 7**."]},{"id":"of-01-011","origen":"oficiales","test":"TREBEP (Oficial 1) - arts. 1 a 7","n":11,"enunciado":"Señale la respuesta INCORRECTA en relación con el ámbito de aplicación del TREBEP:","opciones":["Tiene carácter supletorio para todo el personal de las Administraciones Públicas no incluido en su ámbito de aplicación.","Se aplica al personal funcionario y en lo que proceda al personal laboral al servicio de las Universidades Públicas.","Tiene carácter obligatorio para todo el personal de las Administraciones Públicas incluido en su ámbito de aplicación.","Se aplica sólo al personal funcionario al servicio de las Administraciones de las entidades locales."],"bloque":"ambito","precepto":"Art. 2 del TREBEP","correcta":3,"justificaciones":["Es verdadera, así que no se marca (**art. 2.5**).","Es verdadera, así que no se marca (**art. 2.1**).","Es verdadera, así que no se marca: se aplica al personal incluido en su ámbito.","Esta es la falsa, y por eso es la que hay que marcar. El ámbito no se limita al personal local: incluye la AGE, las comunidades autónomas, los organismos públicos y las Universidades (**art. 2.1**)."]},{"id":"of-01-012","origen":"oficiales","test":"TREBEP (Oficial 1) - arts. 1 a 7","n":12,"enunciado":"Según los artículos 4 y 5 del TREBEP, ¿a qué personal sólo se aplicarán directamente las disposiciones del mismo cuando así lo disponga su legislación específica?","opciones":["Al personal laboral de la Sociedad Estatal Correos y Telégrafos.","Al personal funcionario de la Sociedad Estatal Correos y Telégrafos.","Al personal militar de las Fuerzas Armadas.","Al personal con contrato fijo celebrado con las empresas que colaboran con la Administración General del Estado."],"bloque":"ambito","precepto":"Art. 4.d del TREBEP","correcta":2,"justificaciones":["No. El personal laboral de Correos se rige por la legislación laboral (**art. 5**).","No. El personal funcionario de Correos se rige por sus normas específicas y supletoriamente por el Estatuto (**art. 5**).","Es esta. El personal militar de las Fuerzas Armadas está en el **art. 4.d**.","No. Ese personal no es personal de las Administraciones Públicas."]},{"id":"of-01-013","origen":"oficiales","test":"TREBEP (Oficial 1) - arts. 1 a 7","n":13,"enunciado":"Señale la respuesta correcta en relación con el ámbito de aplicación del texto refundido de la Ley del Estatuto Básico del Empleado Público:","opciones":["Tiene carácter supletorio para el personal funcionario al servicio de las Administraciones de las entidades locales.","Se aplica siempre al personal funcionario del Tribunal Constitucional.","Se aplica siempre al personal militar de las Fuerzas Armadas.","Se aplica al personal funcionario y en lo que proceda al personal laboral al servicio de las Universidades Públicas."],"bloque":"ambito","precepto":"Art. 2.1.e del TREBEP","correcta":3,"justificaciones":["No. Para el personal local el Estatuto forma parte de la legislación aplicable, no es supletorio (**art. 3.1**).","No. El personal del Tribunal Constitucional está en el **art. 4.b**: solo si lo dispone su legislación.","No. El personal militar está en el **art. 4.d**: solo si lo dispone su legislación.","Es esta. Se aplica al personal funcionario y, en lo que proceda, al laboral de las Universidades Públicas (**art. 2.1.e**)."]},{"id":"of-02-001","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":1,"enunciado":"Señale cómo se clasifican los empleados públicos de acuerdo con el Texto Refundido del Estatuto Básico del Empleado Público:","opciones":["Funcionarios de carrera, personal laboral y personal estatutario.","Funcionarios de carrera, funcionarios interinos y personal estatutario.","Funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual.","Funcionarios de carrera, funcionarios interinos, personal laboral, personal eventual y personal estatutario."],"bloque":"clases","precepto":"Art. 8.2 del TREBEP","correcta":2,"justificaciones":["No. Faltan interinos y eventual, y el personal estatutario no es una clase.","No. Faltan personal laboral y eventual, y sobra el estatutario.","Es esta. Funcionarios de carrera, interinos, personal laboral y personal eventual (**art. 8.2**).","No. El personal estatutario no es una clase del **art. 8.2**."]},{"id":"of-02-002","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":2,"enunciado":"El TREBEP define a los funcionarios interinos como los que, por razones expresamente justificadas de necesidad y urgencia, son nombrados como tales para el desempeño de funciones propias de funcionarios de carrera, cuando se de alguna de las siguientes circunstancias:","opciones":["La existencia de plazas vacantes cuando no sea posible su cobertura por funcionarios de carrera.","La sustitución permanente de los titulares.","La ejecución de programas de carácter temporal, que no podrán tener una duración superior a 2 años.","El exceso o acumulación de tareas por plazo máximo de 9 meses, dentro de un periodo de 12 meses."],"bloque":"clases","precepto":"Art. 10.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Plazas vacantes cuando no sea posible su cobertura por funcionarios de carrera (**art. 10.1.a**).","No. La sustitución es transitoria, no permanente (**art. 10.1.b**).","No. Los programas temporales no superan tres años, ampliables doce meses más (**art. 10.1.c**).","No. El plazo es de nueve meses dentro de un periodo de dieciocho (**art. 10.1.d**)."]},{"id":"of-02-003","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":3,"enunciado":"De acuerdo con el Capítulo I del Real Decreto Legislativo 5/2015, de 30 de octubre, por el que se aprueba el Texto Refundido del Estatuto Básico del Empleado Público, el funcionario de carrera es:","opciones":["Quien, en virtud de contrato de trabajo formalizado por escrito presta servicios retribuidos para las Administraciones Públicas.","Quien, en virtud de nombramiento legal, está vinculado a una Administración Pública por una relación laboral para el desempeño de servicios profesionales retribuidos de carácter permanente.","Quien, en virtud de nombramiento legal, está vinculado a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente.","Quien desarrolla funciones directivas profesionales en las Administraciones Públicas."],"bloque":"clases","precepto":"Art. 9.1 del TREBEP","correcta":2,"justificaciones":["No. Eso define al personal laboral (**art. 11.1**).","No. La relación del funcionario de carrera es estatutaria, no laboral.","Es esta. Nombramiento legal, relación estatutaria regulada por el Derecho Administrativo y servicios de carácter permanente (**art. 9.1**).","No. Eso describe al personal directivo (**art. 13**)."]},{"id":"of-02-004","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":4,"enunciado":"De acuerdo con el artículo 11 del TREBEP, el personal laboral puede ser:","opciones":["Fijo, por tiempo indefinido o temporal.","Interino o fijo.","Eventual, fijo o temporal.","De carrera, indefinido o temporal."],"bloque":"clases","precepto":"Art. 11.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Fijo, por tiempo indefinido o temporal (**art. 11.1**).","No. Interino es una clase de funcionario, no de personal laboral.","No. Eventual es una clase de personal distinta.","No. De carrera es una clase de funcionario."]},{"id":"of-02-005","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":5,"enunciado":"Según el TREBEP, ¿cuál es el plazo máximo por el que podrán nombrarse funcionarios interinos por exceso o acumulación de tareas?","opciones":["Tres años.","Seis meses dentro de un periodo de doce meses.","Nueve meses dentro de un periodo de dieciocho meses.","Tres años, ampliables hasta doce meses más por las leyes de Función Pública que se dicten en desarrollo del TREBEP."],"bloque":"clases","precepto":"Art. 10.1.d del TREBEP","correcta":2,"justificaciones":["No. Tres años es el máximo de las vacantes y de los programas temporales.","No. Es de nueve meses, no seis.","Es esta. Nueve meses dentro de un periodo de dieciocho (**art. 10.1.d**).","No. Esa es la duración de los programas temporales, no del exceso de tareas."]},{"id":"of-02-006","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":6,"enunciado":"Si los funcionarios interinos hubieran sido nombrados por la existencia de plazas vacantes cuya cobertura por funcionarios de carrera no hubiera sido posible, transcurrido el plazo máximo establecido para su ocupación por personal interino:","opciones":["La Administración formalizará de oficio la finalización de la relación de interinidad, sin derecho a compensación.","Las plazas deberán ser objeto de cobertura necesariamente mediante el sistema de provisión de puestos por concurso.","Se producirá el fin de la relación de interinidad y la vacante deberá ser ocupada, en todo caso, por funcionario de carrera.","Los funcionarios interinos podrán permanecer excepcionalmente en la plaza ocupada temporalmente si se hubiera publicado la convocatoria para su provisión, dando lugar su cese a compensación económica."],"bloque":"clases","precepto":"Art. 10.4 del TREBEP","correcta":2,"ojo":"El art. 10.4 añade una excepción: si el proceso selectivo queda desierto, se puede hacer otro nombramiento interino. Por eso el en todo caso de la opción no es del todo exacto.","revisar":"Respondida con el art. 10.4 vigente. Es la opción que más se acerca, aunque lleva en todo caso y la ley admite la excepción del proceso desierto.","justificaciones":["No. Esa es la forma de cese del apartado 3, no el efecto de agotar los tres años.","No. La cobertura puede ser por provisión o movilidad, no solo por concurso.","Es esta. Transcurridos tres años se produce el fin de la relación de interinidad y la vacante solo podrá ser ocupada por personal funcionario de carrera (**art. 10.4**).","No. Permanecer excepcionalmente hasta resolver la convocatoria es sin compensación económica (**art. 10.4**)."]},{"id":"of-02-007","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":7,"enunciado":"De acuerdo con el Texto Refundido del Estatuto Básico del Empleado Público, señale quién podrá desarrollar el régimen jurídico específico del personal directivo:","opciones":["Las Cortes Generales.","El Gobierno y los órganos de gobierno de las Comunidades Autónomas.","El Ministro de Administraciones Públicas en el ámbito de la Administración General del Estado.","Las Asambleas Legislativas de las Comunidades Autónomas."],"bloque":"clases","precepto":"Art. 13 del TREBEP","correcta":1,"justificaciones":["No. Lo establecen el Gobierno y los órganos de gobierno autonómicos.","Es esta. El Gobierno y los órganos de gobierno de las comunidades autónomas (**art. 13**).","No. No lo desarrolla el ministro.","No. Lo desarrollan los órganos de gobierno, no las asambleas legislativas."]},{"id":"of-02-008","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":8,"enunciado":"Señale la afirmación correcta en relación con el cese del personal eventual:","opciones":["Tendrá lugar cuando cese la autoridad que lo nombró.","Tendrá lugar cuando cese la autoridad que propuso su nombramiento.","Tendrá lugar cuando concluya la legislatura durante la que fue nombrado.","Tendrá lugar, en todo caso, cuando se produzca el de la autoridad a la que se preste la función de confianza o asesoramiento."],"bloque":"clases","precepto":"Art. 12.3 del TREBEP","correcta":3,"justificaciones":["No. Cesa cuando cesa la autoridad a la que se presta la función, no la que lo nombró.","No. No depende de la autoridad que propuso el nombramiento.","No. No se vincula a la legislatura.","Es esta. Cesa, en todo caso, cuando cesa la autoridad a la que se presta la función de confianza o asesoramiento (**art. 12.3**)."]},{"id":"of-02-009","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":9,"enunciado":"De acuerdo con el TREBEP, el personal laboral podrá ser en función de la duración del contrato:","opciones":["Fijo o temporal, exclusivamente.","Fijo, por tiempo indefinido o temporal.","Fijo, fijo discontinuo o temporal.","Fijo, por tiempo indefinido, fijo discontinuo o temporal."],"bloque":"clases","precepto":"Art. 11.1 del TREBEP","correcta":1,"justificaciones":["No. Falta el contrato por tiempo indefinido.","Es esta. Fijo, por tiempo indefinido o temporal (**art. 11.1**).","No. El fijo discontinuo no figura y falta el indefinido.","No. El fijo discontinuo no figura en el artículo."]},{"id":"of-02-010","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":10,"enunciado":"Según el TREBEP, son funcionarios de carrera:","opciones":["Los nombrados libremente por el Ministro correspondiente.","Los que, en virtud de nombramiento legal, desempeñan servicios de carácter general.","Los que, en virtud de nombramiento legal, desempeñan servicios profesionales retribuidos de carácter permanente.","Los que, en virtud de nombramiento provisional, desempeñan servicios de carácter general."],"bloque":"clases","precepto":"Art. 9.1 del TREBEP","correcta":2,"justificaciones":["No. El nombramiento libre es característico del personal eventual.","No. No es solo servicios de carácter general: son servicios profesionales retribuidos de carácter permanente.","Es esta. Nombramiento legal y servicios profesionales retribuidos de carácter permanente (**art. 9.1**).","No. El nombramiento es legal, no provisional."]},{"id":"of-02-011","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":11,"enunciado":"Conforme al TREBEP, y en relación con el personal eventual:","opciones":["El cese solamente tendrá lugar cuando se produzca el de la autoridad a la que se preste la función de confianza.","El personal eventual solo realiza funciones expresamente calificadas de confianza y asesoramiento especial.","El nombramiento y cese del personal eventual se realizará mediante el procedimiento de libre designación.","La condición de personal eventual serán mérito para el acceso a la Función Pública o para la promoción interna."],"bloque":"clases","precepto":"Art. 12 del TREBEP","correcta":1,"justificaciones":["No. Además del cese de la autoridad, el cese es libre (**art. 12.3**).","Es esta. Solo realiza funciones expresamente calificadas de confianza o asesoramiento especial (**art. 12.1**).","No. El nombramiento y cese son libres, no por libre designación con convocatoria.","No. La condición de eventual no puede constituir mérito (**art. 12.4**)."]},{"id":"of-02-012","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":12,"enunciado":"Según el TREBEP, es posible el nombramiento de funcionarios interinos:","opciones":["Cuando existan plazas vacantes que puedan ser cubiertas por funcionarios de carrera.","Para la ejecución de programas de carácter temporal, que no podrán tener una duración superior a tres años.","Para realizar funciones expresamente calificadas como de confianza o asesoramiento especial.","Para la ejecución de programas de carácter temporal, que no podrán tener una duración superior a cinco años."],"bloque":"clases","precepto":"Art. 10.1.c del TREBEP","correcta":1,"justificaciones":["No. Las vacantes interinas son cuando no sea posible su cobertura por funcionarios de carrera.","Es esta. Programas temporales de no más de tres años, ampliables doce meses (**art. 10.1.c**).","No. Esas son funciones del personal eventual (**art. 12.1**).","No. El máximo es de tres años, no cinco."]},{"id":"of-02-013","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":13,"enunciado":"El artículo 13 del texto refundido de la Ley del Estatuto Básico del Empleado Público regula el personal directivo profesional que presta servicios en las Administraciones Públicas. Señale la respuesta correcta en relación con este tipo de personal:","opciones":["Es considerado empleado público, de acuerdo con la clasificación prevista en su artículo 8.2.","Su designación atenderá a principios igualdad, mérito y capacidad.","La determinación de sus condiciones de empleo tendrá la consideración de materia objeto de negociación colectiva.","Cuando reúna la condición de personal laboral estará sometido a la relación laboral de carácter especial de alta dirección."],"bloque":"clases","precepto":"Art. 13.4 del TREBEP","correcta":3,"justificaciones":["No. El personal directivo no está en la clasificación del **art. 8.2**.","No. Su designación atiende a mérito y capacidad e idoneidad, con publicidad y concurrencia (**art. 13.2**).","No. Sus condiciones de empleo no son materia de negociación colectiva (**art. 13.4**).","Es esta. Si es personal laboral, se somete a la relación laboral especial de alta dirección (**art. 13.4**)."]},{"id":"of-02-014","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":14,"enunciado":"De acuerdo con el artículo 12 del TREBEP, el personal eventual:","opciones":["Es una categoría de personal laboral que desempeña funciones de especial confianza.","Es una clase de empleados públicos que desempeña funciones propias del personal funcionario.","Es una categoría de funcionarios que desempeña funciones de directivo público.","Es una clase de empleados públicos que desempeña funciones de confianza o asesoramiento especial."],"bloque":"clases","precepto":"Art. 12.1 del TREBEP","correcta":3,"justificaciones":["No. No es una categoría de personal laboral.","No. No desempeña funciones propias de funcionarios.","No. No es una categoría de funcionarios ni de directivos.","Es esta. Es una clase de empleados públicos que desempeña funciones de confianza o asesoramiento especial (**art. 12.1**)."]},{"id":"of-02-015","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":15,"enunciado":"De acuerdo con el TREBEP, el personal laboral puede ser:","opciones":["Discontinuo.","Eventual.","Interino.","Temporal."],"bloque":"clases","precepto":"Art. 11.1 del TREBEP","correcta":3,"justificaciones":["No. El discontinuo no figura entre las duraciones del contrato.","No. Eventual es otra clase de empleado público.","No. Interino es una clase de funcionario.","Es esta. Temporal (**art. 11.1**)."]},{"id":"of-02-016","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":16,"enunciado":"Señale la respuesta correcta en relación con las diferentes clases de empleados públicos:","opciones":["El personal eventual es nombrado por razones expresamente justificadas de necesidad y urgencia.","El personal laboral puede ocupar cualquier tipo de puestos de trabajo dentro de la Administración pública.","Los funcionarios o funcionarias en prácticas son una de las clases de empleados públicos.","El personal eventual cesará, en todo caso, cuando se produzca el de la autoridad a la que presta la función de confianza."],"bloque":"clases","precepto":"Art. 12.3 del TREBEP","correcta":3,"justificaciones":["No. Eso describe a los interinos, no a los eventuales.","No. Hay funciones reservadas a funcionarios (**art. 9.2**).","No. Los funcionarios en prácticas no son una clase del **art. 8.2**.","Es esta. El personal eventual cesa, en todo caso, cuando cesa la autoridad a la que presta la función (**art. 12.3**)."]},{"id":"of-02-017","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":17,"enunciado":"Conforme al artículo 10 del TREBEP, son funcionarios interinos los que, por razones expresamente justificadas de necesidad y urgencia, son nombrados como tales con carácter temporal para el desempeño de funciones propias de funcionarios de carrera, cuando se dé alguna de las siguientes circunstancias:","opciones":["La existencia de plazas vacantes, cuando no sea posible su cobertura por funcionarios de carrera, por un máximo de un año.","La sustitución transitoria de los titulares, durante el tiempo estrictamente necesario.","La ejecución de programas de carácter temporal, que no podrán tener una duración superior a cinco años.","El exceso o acumulación de tareas por plazo máximo de doce meses, dentro de un periodo de dieciocho meses."],"bloque":"clases","precepto":"Art. 10.1.b del TREBEP","correcta":1,"justificaciones":["No. El máximo para vacantes es de tres años.","Es esta. La sustitución transitoria de los titulares, durante el tiempo estrictamente necesario (**art. 10.1.b**).","No. El máximo es de tres años, ampliable doce meses, no cinco.","No. Son nueve meses dentro de dieciocho."]},{"id":"of-02-018","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":18,"enunciado":"El Sr. Pérez presta servicios de colaboración y asesoramiento especial al Secretario de Estado de Infraestructuras, Transportes y Vivienda, en virtud de nombramiento de carácter no permanente. ¿Cuál es su condición de empleado público?","opciones":["Personal laboral de carácter temporal.","Personal eventual.","Funcionario de carrera.","Personal directivo."],"bloque":"clases","precepto":"Art. 12.1 del TREBEP","correcta":1,"justificaciones":["No. Un nombramiento de colaboración y asesoramiento especial es de personal eventual.","Es esta. Presta asesoramiento especial en virtud de nombramiento no permanente: personal eventual (**art. 12.1**).","No. Un funcionario de carrera tiene carácter permanente.","No. El personal directivo desarrolla funciones directivas profesionales."]},{"id":"of-02-019","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":19,"enunciado":"De conformidad con el artículo 8 del TREBEP, NO se encuentra dentro de la clasificación de empleado público, el:","opciones":["Personal directivo profesional.","Personal eventual.","Personal laboral.","Funcionario interino."],"bloque":"clases","precepto":"Art. 8.2 del TREBEP","correcta":0,"justificaciones":["Es esta. El personal directivo profesional no figura en la clasificación del **art. 8.2**; se regula en el art. 13.","No. El personal eventual figura en el **art. 8.2.d**.","No. El personal laboral figura en el **art. 8.2.c**.","No. Los funcionarios interinos figuran en el **art. 8.2.b**."]},{"id":"of-02-020","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":20,"enunciado":"Según el TREBEP, ¿cuál de los siguientes contratos de personal laboral está expresamente reconocido?","opciones":["El contrato de trabajo para la formación y el aprendizaje.","El contrato de trabajo en prácticas.","El contrato de trabajo por tiempo indefinido.","El contrato de grupo."],"bloque":"clases","precepto":"Art. 11.1 del TREBEP","correcta":2,"justificaciones":["No. El contrato para la formación y el aprendizaje no se menciona.","No. El contrato en prácticas no se menciona.","Es esta. Por tiempo indefinido es una de las duraciones previstas (**art. 11.1**).","No. El contrato de grupo no se menciona."]},{"id":"of-02-021","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":21,"enunciado":"De conformidad con el artículo 10 del TREBEP, el nombramiento de personal funcionario interino nombrado para la ejecución de programas de carácter temporal NO podrá tener una duración superior a:","opciones":["Seis meses, ampliable hasta doce meses más por las leyes de Función Pública que se dicten en desarrollo de este Estatuto.","Doce meses, ampliable hasta doce meses más por las leyes de Función Pública que se dicten en desarrollo de este Estatuto.","Tres años, ampliable hasta doce meses más por las leyes de Función Pública que se dicten en desarrollo de este Estatuto.","Dos años, ampliable hasta doce meses más por las leyes de Función Pública que se dicten en desarrollo de este Estatuto."],"bloque":"clases","precepto":"Art. 10.1.c del TREBEP","correcta":2,"justificaciones":["No. El plazo es de tres años, no seis meses.","No. El plazo es de tres años, no doce meses.","Es esta. Tres años, ampliables hasta doce meses más (**art. 10.1.c**).","No. El plazo es de tres años, no dos."]},{"id":"of-02-022","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":22,"enunciado":"De acuerdo con el TREBEP, el personal eventual es aquel que:","opciones":["Ocupa plazas vacantes cuando no sea posible su cobertura por funcionarios de carrera.","Ejecuta programas de carácter temporal, que no podrán tener una duración superior a tres años.","Realiza funciones que impliquen la participación directa o indirecta en el ejercicio de las potestades públicas.","Realiza funciones expresamente calificadas como de asesoramiento especial."],"bloque":"clases","precepto":"Art. 12.1 del TREBEP","correcta":3,"justificaciones":["No. Eso describe a los interinos por vacante.","No. Eso describe a los interinos por programas temporales.","No. Las potestades públicas corresponden a funcionarios (**art. 9.2**).","Es esta. Realiza funciones expresamente calificadas de confianza o asesoramiento especial (**art. 12.1**)."]},{"id":"of-02-023","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":23,"enunciado":"Conforme al TREBEP, señale la respuesta correcta en cuanto a los funcionarios interinos se refiere:","opciones":["Son nombrados por razones de necesidad, no así de urgencia.","Sus funciones son diferentes a las que desempeña un funcionario de carrera.","Dada la necesidad, su selección se realizará por procedimientos ágiles sin sujeción a los principios de mérito y publicidad.","Les será aplicable, en cuanto sea adecuado a la naturaleza de su condición, el régimen general de los funcionarios de carrera."],"bloque":"clases","precepto":"Art. 10.5 del TREBEP","correcta":3,"justificaciones":["No. Son nombrados por razones de necesidad y urgencia, ambas (**art. 10.1**).","No. Desempeñan funciones propias de funcionarios de carrera.","No. Su selección se rige por igualdad, mérito, capacidad, publicidad y celeridad (**art. 10.2**).","Es esta. Les será aplicable el régimen general de los funcionarios de carrera en cuanto sea adecuado a su condición (**art. 10.5**)."]},{"id":"of-02-024","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":24,"enunciado":"Según dispone el Estatuto Básico del Empleado Público, el nombramiento y cese del personal eventual:","opciones":["Serán libres.","El nombramiento lo será tras un proceso selectivo y el cese se regirá por lo establecido para los funcionarios de carrera.","Tanto el nombramiento como el cese se regirán por lo establecido para los funcionarios de carrera.","El nombramiento será libre y el cese exigirá resolución motivada y explicativa de las razones del mismo."],"bloque":"clases","precepto":"Art. 12.3 del TREBEP","correcta":0,"justificaciones":["Es esta. El nombramiento y cese son libres (**art. 12.3**).","No. No hay proceso selectivo y el cese no se rige por el de los funcionarios.","No. No se rigen por lo establecido para los funcionarios de carrera.","No. El cese también es libre, sin motivación exigida."]},{"id":"of-02-025","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":25,"enunciado":"Según el TREBEP, señale la respuesta correcta respecto a los empleados públicos:","opciones":["Las funciones que impliquen participación directa en potestades públicas sólo podrán ser ejercidas por funcionarios de carrera.","Son funcionarios de carrera quienes, en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para desempeñar servicios retribuidos de carácter permanente.","Son empleados públicos quienes desempeñan funciones retribuidas en las Administraciones Públicas al servicio de intereses estatales o autonómicos.","Al personal funcionario interino le será aplicable en su integridad el régimen general del personal funcionario de carrera."],"bloque":"clases","precepto":"Art. 9.1 del TREBEP","correcta":1,"justificaciones":["No. Las potestades públicas corresponden a funcionarios públicos, no solo a los de carrera (**art. 9.2**).","Es esta. Es la definición del funcionario de carrera (**art. 9.1**).","No. Es al servicio de los intereses generales, no de intereses estatales o autonómicos (**art. 8.1**).","No. Solo en cuanto sea adecuado a su condición temporal (**art. 10.5**)."]},{"id":"of-02-026","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":26,"enunciado":"Según el artículo 10 del Estatuto Básico del Empleado Público, los procedimientos de selección del personal funcionario interino serán:","opciones":["Públicos, rigiéndose en todo caso por los principios de igualdad, mérito, capacidad, publicidad y celeridad.","Públicos, rigiéndose en todo caso por los principios de celeridad y eficacia.","Abiertos, rigiéndose en todo caso por los principios de publicidad, mérito y transparencia.","Rápidos, rigiéndose en todo caso por los principios de publicidad, celeridad y eficiencia."],"bloque":"clases","precepto":"Art. 10.2 del TREBEP","correcta":0,"justificaciones":["Es esta. Públicos, con igualdad, mérito, capacidad, publicidad y celeridad (**art. 10.2**).","No. Faltan igualdad, mérito, capacidad y publicidad.","No. Faltan igualdad, capacidad y celeridad.","No. No se limitan a rapidez: se rigen por los principios del **art. 10.2**."]},{"id":"of-02-027","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":27,"enunciado":"Conforme al TREBEP, ¿cuál de las siguientes circunstancias permitiría nombrar a funcionarios interinos?","opciones":["La sustitución transitoria de los titulares, durante el tiempo estrictamente necesario.","Cuando se asuman por mandato legal nuevas competencias o funciones y no se cuente con el personal funcionario suficiente.","Para la realización de trabajos considerados urgentes, por un máximo de seis meses ampliable a un año.","Cuando, por motivo de una reorganización ministerial, se pongan en marcha unidades administrativas nuevas."],"bloque":"clases","precepto":"Art. 10.1.b del TREBEP","correcta":0,"justificaciones":["Es esta. La sustitución transitoria de los titulares (**art. 10.1.b**).","No. Las nuevas competencias no figuran entre las circunstancias del artículo.","No. No existe esa circunstancia, ni ese plazo.","No. La creación de unidades por reorganización no figura."]},{"id":"of-02-028","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":28,"enunciado":"¿Cuál de las siguientes afirmaciones es cierta en relación con el personal directivo de la Administración, según el TREBEP?","opciones":["Su nombramiento se produce mediante el procedimiento de libre designación entre funcionarios de carrera del Subgrupo A1.","Cesa, en cualquier caso, cuando cesa la autoridad que lo nombró.","Cuando se trate de personal laboral, estará sometido a la relación laboral especial de alta dirección.","La determinación de sus condiciones de trabajo es objeto de negociación colectiva."],"bloque":"clases","precepto":"Art. 13.4 del TREBEP","correcta":2,"justificaciones":["No. El Estatuto no exige libre designación entre funcionarios A1.","No. Su cese no se vincula al de la autoridad: eso es el personal eventual.","Es esta. Cuando es laboral, se somete a la relación laboral de alta dirección (**art. 13.4**).","No. Sus condiciones no son materia de negociación colectiva (**art. 13.4**)."]},{"id":"of-02-029","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":29,"enunciado":"Según el artículo 10 del texto refundido de la Ley del Estatuto Básico del Empleado Público, ¿en qué circunstancia se puede nombrar a un funcionario interino?","opciones":["Cuando existan plazas vacantes, y no sea posible su cobertura por funcionarios de carrera, por un máximo de dos años.","Por el exceso o acumulación de tareas por plazo máximo de tres meses, dentro de un periodo de doce meses.","Para la sustitución transitoria de los titulares, durante el tiempo estrictamente necesario.","Para la ejecución de programas de carácter estructural."],"bloque":"clases","precepto":"Art. 10.1.b del TREBEP","correcta":2,"justificaciones":["No. El máximo para vacantes es de tres años.","No. Son nueve meses dentro de dieciocho.","Es esta. La sustitución transitoria de los titulares (**art. 10.1.b**).","No. Son programas de carácter temporal, no estructural."]},{"id":"of-02-030","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":30,"enunciado":"De acuerdo con el artículo 8 del texto refundido de la Ley del Estatuto Básico del Empleado Público, los empleados públicos se clasifican en:","opciones":["Funcionarios de carrera; funcionarios interinos; personal laboral, ya sea fijo, por tiempo indefinido o temporal y personal eventual.","Funcionarios de carrera; personal laboral, ya sea fijo, por tiempo indefinido o temporal, personal eventual y personal directivo.","Funcionarios de carrera; funcionarios interinos; personal laboral; personal directivo y personal eventual.","Funcionarios de carrera; funcionarios interinos; personal laboral, ya sea fijo, por tiempo indefinido o temporal y personal directivo."],"bloque":"clases","precepto":"Art. 8.2 del TREBEP","correcta":0,"justificaciones":["Es esta. Funcionarios de carrera, interinos, personal laboral (fijo, indefinido o temporal) y eventual (**art. 8.2**).","No. Faltan los interinos y sobra el personal directivo.","No. El personal directivo no está en la clasificación.","No. Falta el personal eventual y sobra el directivo."]},{"id":"of-02-031","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":31,"enunciado":"¿Cuál de las siguientes circunstancias NO está prevista en el texto refundido de la Ley del Estatuto Básico del Empleado Público en relación con el nombramiento de los funcionarios interinos?","opciones":["La existencia de plazas vacantes cuando no sea posible su cobertura por funcionarios de carrera, por un máximo de tres años.","La cobertura transitoria de plazas de nueva creación para personal funcionario de carrera, únicamente durante el tiempo en el que las personas aprobadas realizan el curso selectivo.","La sustitución transitoria de los titulares, durante el tiempo estrictamente necesario.","La ejecución de programas de carácter temporal, que no podrán tener una duración superior a tres años, ampliable hasta doce meses más por las leyes de Función Pública."],"bloque":"clases","precepto":"Art. 10.1 del TREBEP","correcta":1,"justificaciones":["No. Está prevista, con máximo de tres años (**art. 10.1.a**).","Es esta. La cobertura transitoria durante el curso selectivo no figura en el **art. 10.1**.","No. Está prevista (**art. 10.1.b**).","No. Está prevista (**art. 10.1.c**)."]},{"id":"of-02-032","origen":"oficiales","test":"TREBEP (Oficial 2) - arts. 8 a 13","n":32,"enunciado":"De entre las clases de empleados públicos que se indica a continuación, ¿cuál de ellos realiza solo funciones expresamente calificadas como de confianza o asesoramiento especial, siendo retribuido con cargo a los créditos presupuestarios consignados para este fin?","opciones":["Funcionarios interinos.","Personal eventual.","Personal laboral.","Funcionarios de carrera."],"bloque":"clases","precepto":"Art. 12.1 del TREBEP","correcta":1,"justificaciones":["No. Los interinos desempeñan funciones propias de funcionarios de carrera.","Es esta. El personal eventual realiza solo funciones de confianza o asesoramiento especial (**art. 12.1**).","No. El personal laboral no tiene esa definición.","No. Los funcionarios de carrera tienen servicios de carácter permanente."]},{"id":"of-03-001","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":1,"enunciado":"Según el TREBEP, ¿cuál es la modalidad de carrera profesional que consiste en el ascenso en la estructura de puestos de trabajo por los procedimientos de provisión?","opciones":["La carrera horizontal.","La carrera vertical.","La promoción interna vertical.","La promoción interna horizontal."],"bloque":"derechos","precepto":"Art. 16.3.b del TREBEP","correcta":1,"justificaciones":["No. La carrera horizontal es la progresión de grado, categoría o escalón sin cambiar de puesto (**art. 16.3.a**).","Es esta. La carrera vertical es el ascenso en la estructura de puestos por los procedimientos de provisión (**art. 16.3.b**).","No. La promoción interna vertical es el ascenso de un cuerpo o escala de un Subgrupo a otro superior (**art. 16.3.c**).","No. La promoción interna horizontal es el acceso a cuerpos o escalas del mismo Subgrupo (**art. 16.3.d**)."]},{"id":"of-03-002","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":2,"enunciado":"Señale la respuesta correcta, de acuerdo con el TREBEP, respecto a la carrera profesional de los funcionarios:","opciones":["La carrera horizontal consiste en el ascenso a través de la estructura de puestos de trabajo.","La promoción interna vertical consiste en el acceso a Cuerpos de un mismo Subgrupo profesional.","La carrera horizontal consiste en la progresión de grado, categoría o escalón sin necesidad de cambiar de puesto de trabajo.","La carrera vertical consiste en el ascenso desde un Cuerpo o Escala de un Subgrupo profesional a otro superior."],"bloque":"derechos","precepto":"Art. 16.3.a del TREBEP","correcta":2,"justificaciones":["No. Eso describe la carrera vertical.","No. Eso describe la promoción interna horizontal.","Es esta. La carrera horizontal es la progresión de grado, categoría o escalón sin cambiar de puesto (**art. 16.3.a**).","No. Eso describe la promoción interna vertical."]},{"id":"of-03-003","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":3,"enunciado":"De acuerdo con el TREBEP, el acceso a Cuerpos o Escalas del mismo Subgrupo profesional se denomina:","opciones":["Carrera interna horizontal.","Progresión horizontal.","Promoción interna horizontal.","Promoción horizontal."],"bloque":"derechos","precepto":"Art. 16.3.d del TREBEP","correcta":2,"justificaciones":["No. \"Carrera interna horizontal\" no existe en el artículo.","No. \"Progresión horizontal\" no existe en el artículo.","Es esta. Promoción interna horizontal (**art. 16.3.d**).","No. \"Promoción horizontal\" no es la denominación exacta."]},{"id":"of-03-004","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":4,"enunciado":"Según el artículo 16.3 del TREBEP, ¿en qué consiste la carrera horizontal de los funcionarios públicos?","opciones":["En la progresión de grado, categoría, escalón u otros conceptos análogos, sin necesidad de cambiar de puesto de trabajo.","En el ascenso en la estructura de puestos de trabajo por los procedimientos de provisión de puestos de trabajo.","En el ascenso desde un cuerpo o escala de un Subgrupo, o Grupo de clasificación profesional, a otro superior.","En el acceso a cuerpos o escalas del mismo Subgrupo profesional."],"bloque":"derechos","precepto":"Art. 16.3.a del TREBEP","correcta":0,"justificaciones":["Es esta. Progresión de grado, categoría, escalón u otros conceptos análogos sin cambiar de puesto (**art. 16.3.a**).","No. Eso es la carrera vertical.","No. Eso es la promoción interna vertical.","No. Eso es la promoción interna horizontal."]},{"id":"of-03-005","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":5,"enunciado":"Según el TREBEP, el ascenso desde un cuerpo o escala de un Subgrupo, o Grupo de clasificación profesional en el supuesto de que este no tenga Subgrupo, a otro superior, constituye la:","opciones":["Promoción profesional vertical.","Carrera profesional vertical.","Promoción interna vertical.","Carrera profesional interna."],"bloque":"derechos","precepto":"Art. 16.3.c del TREBEP","correcta":2,"justificaciones":["No. \"Promoción profesional vertical\" no es la denominación del artículo.","No. La carrera vertical es el ascenso en la estructura de puestos.","Es esta. Promoción interna vertical (**art. 16.3.c**).","No. \"Carrera profesional interna\" no es una modalidad del artículo."]},{"id":"of-03-006","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":6,"enunciado":"¿Cuál de los siguientes es un requisito exigido por el TREBEP para participar en procesos de promoción interna?","opciones":["Tener una antigüedad de, al menos, un año de servicio activo en el inferior Subgrupo, o Grupo de clasificación profesional.","Tener una antigüedad de, al menos, dos años de servicio activo en el inferior Subgrupo, o Grupo de clasificación profesional.","Tener una antigüedad de, al menos, dos años de servicio activo en cualquier otro Cuerpo de cualquier Administración.","Tener una antigüedad de, al menos, cinco años de servicio activo en el inferior Subgrupo o Grupo de clasificación profesional."],"bloque":"derechos","precepto":"Art. 18.2 del TREBEP","correcta":1,"justificaciones":["No. Se exigen dos años, no uno.","Es esta. Al menos dos años de servicio activo en el inferior Subgrupo o Grupo (**art. 18.2**).","No. Los dos años son en el inferior Subgrupo o Grupo, no en cualquier otro cuerpo.","No. Se exigen dos años, no cinco."]},{"id":"of-03-007","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":7,"enunciado":"La promoción interna de los funcionarios:","opciones":["Está prevista para el personal eventual o interino con más de dos años de servicio.","Se realizará mediante la evaluación del desempeño por el superior jerárquico.","Se realizará mediante procesos selectivos que garanticen los principios constitucionales de igualdad, mérito y capacidad.","Supone la concreción del derecho a la carrera horizontal."],"bloque":"derechos","precepto":"Art. 18.1 del TREBEP","correcta":2,"justificaciones":["No. Está prevista para funcionarios de carrera.","No. Se realiza mediante procesos selectivos, no mediante evaluación del superior.","Es esta. Se realiza mediante procesos selectivos que garanticen igualdad, mérito y capacidad (**art. 18.1**).","No. No se identifica con la carrera horizontal."]},{"id":"of-03-008","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":8,"enunciado":"Los empleados públicos tienen los siguientes derechos individuales que se ejercen de forma colectiva:","opciones":["A la libre asociación profesional.","A participar en la consecución de los objetivos atribuidos a su unidad.","A recibir protección eficaz en materia de seguridad y salud en el trabajo.","A la libertad sindical."],"bloque":"derechos","precepto":"Art. 15.a del TREBEP","correcta":3,"justificaciones":["No. La libre asociación profesional es un derecho individual (**art. 14.p**).","No. Participar en la consecución de los objetivos es un derecho individual (**art. 14.e**).","No. La protección en seguridad y salud es un derecho individual (**art. 14.l**).","Es esta. La libertad sindical es un derecho individual de ejercicio colectivo (**art. 15.a**)."]},{"id":"of-03-009","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":9,"enunciado":"El artículo 16 del TREBEP incluye expresamente entre los conceptos entre los que se puede progresar para conformar la carrera horizontal:","opciones":["La progresión de nivel.","La progresión de subgrupo.","La progresión de grado.","La progresión de clasificación."],"bloque":"derechos","precepto":"Art. 16.3.a del TREBEP","correcta":2,"justificaciones":["No. La progresión de nivel no figura.","No. La progresión de subgrupo no figura.","Es esta. Grado, categoría, escalón u otros conceptos análogos (**art. 16.3.a**).","No. La progresión de clasificación no figura."]},{"id":"of-03-010","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":10,"enunciado":"Según lo establecido en el TREBEP, se habla de carrera vertical cuando:","opciones":["Se produce un ascenso desde un cuerpo o escala de un Subgrupo a otro superior.","Se asciende de grado, categoría, escalón u otros conceptos análogos, sin necesidad de cambiar de puesto de trabajo.","Se accede a cuerpos o escalas del mismo Subgrupo profesional de acuerdo con lo dispuesto en el artículo 18 del TREBEP.","Se produce el ascenso en la estructura de puestos, mediante los sistemas de concurso o libre designación."],"bloque":"derechos","precepto":"Art. 16.3.b del TREBEP","correcta":3,"justificaciones":["No. Eso es la promoción interna vertical.","No. Eso es la carrera horizontal.","No. Eso es la promoción interna horizontal.","Es esta. La carrera vertical es el ascenso en la estructura de puestos mediante los procedimientos de provisión: concurso o libre designación (**art. 16.3.b**)."]},{"id":"of-03-011","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":11,"enunciado":"El artículo 14 del texto refundido del Estatuto Básico del Empleado Público contempla como un derecho de carácter individual del empleado público:","opciones":["La libertad de expresión dentro de los límites del ordenamiento jurídico.","La inviolabilidad en su puesto de trabajo y a la protección de sus pertenencias y enseres personales.","La defensa jurídica en los procedimientos que se sigan ante cualquier orden jurisdiccional.","La movilidad en su condición de funcionario de carrera."],"bloque":"derechos","precepto":"Art. 14.k del TREBEP","correcta":0,"justificaciones":["Es esta. La libertad de expresión dentro de los límites del ordenamiento jurídico es un derecho individual (**art. 14.k**).","No. Esa inviolabilidad no figura en el art. 14.","No. El derecho es a la defensa jurídica y protección de la Administración por el ejercicio legítimo de sus funciones, no a cualquier defensa (**art. 14.f**).","No. El derecho es a la inamovilidad en la condición de funcionario de carrera, no a la movilidad (**art. 14.a**)."]},{"id":"of-03-012","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":12,"enunciado":"De acuerdo con el TREBEP, los empleados públicos tienen los siguientes derechos individuales que se ejercen de forma colectiva:","opciones":["A la libre asociación profesional.","A la participación en la consecución de los objetivos atribuidos a su unidad.","A la libertad sindical.","A la formación continua y a la actualización permanente de sus conocimientos."],"bloque":"derechos","precepto":"Art. 15.a del TREBEP","correcta":2,"justificaciones":["No. La libre asociación profesional es un derecho individual (**art. 14.p**).","No. Es un derecho individual (**art. 14.e**).","Es esta. La libertad sindical (**art. 15.a**).","No. La formación continua es un derecho individual (**art. 14.g**)."]},{"id":"of-03-013","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":13,"enunciado":"Señale cuál de los siguientes NO es un derecho individual de los empleados públicos:","opciones":["A la inamovilidad en el puesto de trabajo.","A participar en la consecución de los objetivos atribuidos a la unidad donde preste sus servicios.","A la libertad de expresión dentro de los límites del ordenamiento jurídico.","A la libre asociación profesional."],"bloque":"derechos","precepto":"Art. 14.a del TREBEP","correcta":0,"justificaciones":["Es esta. El derecho es a la inamovilidad en la condición de funcionario de carrera, no en el puesto de trabajo (**art. 14.a**).","No. Es un derecho individual (**art. 14.e**).","No. Es un derecho individual (**art. 14.k**).","No. Es un derecho individual (**art. 14.p**)."]},{"id":"of-03-014","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":14,"enunciado":"Según el TREBEP, ¿qué antigüedad deben poseer los funcionarios en el subgrupo o grupo de clasificación profesional inferior para poder participar en los procesos selectivos de promoción interna?","opciones":["Al menos 1 año de servicio activo.","Al menos 2 años de servicio activo.","Al menos 3 años de servicio activo.","Al menos 5 años de servicio activo."],"bloque":"derechos","precepto":"Art. 18.2 del TREBEP","correcta":1,"justificaciones":["No. Son dos años, no uno.","Es esta. Al menos dos años de servicio activo (**art. 18.2**).","No. Son dos años, no tres.","No. Son dos años, no cinco."]},{"id":"of-03-015","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":15,"enunciado":"De conformidad con el artículo 15 del TREBEP, ¿cuál de los siguientes derechos individuales se ejerce de forma colectiva?","opciones":["El derecho a la libre asociación profesional.","El derecho al ejercicio de huelga.","El derecho a la formación continua.","El derecho a participar en la consecución de los objetivos de su unidad."],"bloque":"derechos","precepto":"Art. 15.c del TREBEP","correcta":1,"justificaciones":["No. La libre asociación profesional es un derecho individual (**art. 14.p**).","Es esta. El ejercicio de la huelga (**art. 15.c**).","No. La formación continua es un derecho individual (**art. 14.g**).","No. Participar en la consecución de los objetivos es un derecho individual (**art. 14.e**)."]},{"id":"of-03-016","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":16,"enunciado":"De acuerdo con el TREBEP, los empleados públicos tienen reconocido como derecho individual de ejercicio colectivo:","opciones":["La libre asociación profesional.","La progresión en la carrera profesional.","La negociación colectiva y la participación en la determinación de las condiciones de trabajo.","La libertad de expresión dentro de los límites del ordenamiento jurídico."],"bloque":"derechos","precepto":"Art. 15.b del TREBEP","correcta":2,"justificaciones":["No. La libre asociación profesional es un derecho individual (**art. 14.p**).","No. La progresión en la carrera es un derecho individual (**art. 14.c**).","Es esta. La negociación colectiva y la participación en la determinación de las condiciones de trabajo (**art. 15.b**).","No. La libertad de expresión es un derecho individual (**art. 14.k**)."]},{"id":"of-03-017","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":17,"enunciado":"Según el TREBEP, ¿cuál es un derecho individual ejercido colectivamente por los empleados públicos?","opciones":["Derecho a la libre asociación profesional.","Derecho a la libertad de expresión dentro de los límites del ordenamiento jurídico.","Derecho a la formación continua.","Derecho a la libertad sindical."],"bloque":"derechos","precepto":"Art. 15.a del TREBEP","correcta":3,"justificaciones":["No. La libre asociación profesional es un derecho individual (**art. 14.p**).","No. La libertad de expresión es un derecho individual (**art. 14.k**).","No. La formación continua es un derecho individual (**art. 14.g**).","Es esta. La libertad sindical (**art. 15.a**)."]},{"id":"of-03-018","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":18,"enunciado":"¿Cuál de los siguientes NO es reconocido en el TREBEP como un derecho individual de los empleados públicos?","opciones":["Derecho a la inamovilidad en el puesto de trabajo.","Derecho a la intimidad en el uso de dispositivos digitales puestos a su disposición.","Derecho a recibir protección eficaz en materia de seguridad y salud en el trabajo.","Derecho a la libertad de expresión dentro de los límites del ordenamiento jurídico."],"bloque":"derechos","precepto":"Art. 14.a del TREBEP","correcta":0,"justificaciones":["Es esta. El derecho es a la inamovilidad en la condición de funcionario de carrera, no en el puesto (**art. 14.a**).","No. Sí es un derecho individual (**art. 14.j bis**).","No. Sí es un derecho individual (**art. 14.l**).","No. Sí es un derecho individual (**art. 14.k**)."]},{"id":"of-03-019","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":19,"enunciado":"El TREBEP establece que para poder participar en procesos de promoción interna los funcionarios deberán poseer, entre otros requisitos, una antigüedad en el Subgrupo inferior, o Grupo de clasificación profesional de, al menos:","opciones":["Depende del Subgrupo o Grupo al que se pretenda acceder.","Tres años continuados en el puesto desde el que se presenta a la promoción interna.","Dos años de servicio activo.","Tres años de servicio activo."],"bloque":"derechos","precepto":"Art. 18.2 del TREBEP","correcta":2,"justificaciones":["No. La antigüedad exigida no depende del Subgrupo al que se acceda.","No. No se exigen tres años continuados en el puesto.","Es esta. Dos años de servicio activo (**art. 18.2**).","No. Son dos años, no tres."]},{"id":"of-03-020","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":20,"enunciado":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, ¿qué derechos individuales se ejercen de forma colectiva?","opciones":["Libertad sindical, negociación colectiva, ejercicio de huelga, planteamiento de conflictos colectivos y reunión","Libertad sindical, libre asociación profesional y ejercicio de huelga.","Libertad sindical, libertad de expresión dentro de los límites del ordenamiento jurídico, negociación colectiva y ejercicio de huelga.","Negociación colectiva, ejercicio de huelga y y libre asociación profesional."],"bloque":"derechos","precepto":"Art. 15 del TREBEP","correcta":0,"justificaciones":["Es esta. Libertad sindical, negociación colectiva, huelga, conflictos colectivos y reunión (**art. 15**).","No. Faltan derechos, y la libre asociación profesional es un derecho individual.","No. La libertad de expresión es un derecho individual.","No. Faltan derechos, y la libre asociación profesional es un derecho individual."]},{"id":"of-03-021","origen":"oficiales","test":"TREBEP (Oficial 3) - arts. 14 a 20","n":21,"enunciado":"Según el artículo 18 del texto refundido de la Ley del Estatuto Básico del Empleado Público, los requisitos para la promoción interna de los funcionarios de carrera son:","opciones":["Poseer los requisitos para el ingreso, tener una antigüedad de, al menos, dos años de servicio activo en el inferior Subgrupo, o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo y superar las correspondientes pruebas selectivas.","Poseer los requisitos para el ingreso, tener una antigüedad de, al menos, tres años de servicio activo en el inferior Subgrupo, o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo y superar las correspondientes pruebas selectivas.","Poseer los requisitos para el ingreso, tener una antigüedad de, al menos, dos años de servicio activo en el inferior Subgrupo, o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo y participar en las correspondientes pruebas selectivas.","Poseer los requisitos para el ingreso, tener una antigüedad de, al menos, tres años de servicio activo en el inferior Subgrupo, o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo y participar en las correspondientes pruebas selectivas."],"bloque":"derechos","precepto":"Art. 18.2 del TREBEP","correcta":0,"justificaciones":["Es esta. Requisitos de ingreso, dos años de servicio activo en el inferior Subgrupo y superar las pruebas selectivas (**art. 18.2**).","No. Son dos años, no tres.","No. No basta participar: hay que superar las pruebas selectivas.","No. Son dos años y hay que superar las pruebas."]},{"id":"of-04-001","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":1,"enunciado":"De acuerdo con el TREBEP, las retribuciones básicas de los funcionarios están integradas por:","opciones":["El sueldo y los trienios.","El sueldo, los trienios y el complemento de destino.","El sueldo y los complementos que retribuyen el rendimiento o los resultados alcanzados por el funcionario.","El sueldo, exclusivamente."],"bloque":"retribuciones","precepto":"Art. 23 del TREBEP","correcta":0,"justificaciones":["Es esta. Las retribuciones básicas son el sueldo y los trienios, única y exclusivamente (**art. 23**).","No. El complemento de destino es una retribución complementaria.","No. Los complementos de rendimiento son retribuciones complementarias (**art. 24.c**).","No. Los trienios también son retribución básica."]},{"id":"of-04-002","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":2,"enunciado":"Forman parte de las retribuciones de los funcionarios públicos:","opciones":["Las dietas.","Las gratificaciones extraordinarias.","Las asistencias por colaboración en actividades de formación y perfeccionamiento.","Las indemnizaciones por traslado de residencia."],"bloque":"retribuciones","precepto":"Art. 24.d del TREBEP","correcta":1,"justificaciones":["No. Las dietas son indemnizaciones por razón del servicio, no retribuciones (**art. 28**).","Es esta. Las gratificaciones por servicios extraordinarios son retribuciones complementarias (**art. 24.d**).","No. Las asistencias son indemnizaciones por razón del servicio (**art. 28**).","No. Las indemnizaciones por traslado son indemnizaciones por razón del servicio (**art. 28**)."]},{"id":"of-04-003","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":3,"enunciado":"Según el artículo 27 del TREBEP, ¿cuáles son las retribuciones del personal laboral?","opciones":["Retribuciones básicas y complementarias.","Las establecidas en la Ley de Presupuestos Generales del Estado de cada año.","Las retribuciones que se determinen por la Comisión Interministerial de Retribuciones.","Las que se determinen de acuerdo con la legislación laboral, el convenio colectivo que sea aplicable y el contrato de trabajo."],"bloque":"retribuciones","precepto":"Art. 27 del TREBEP","correcta":3,"justificaciones":["No. Básicas y complementarias son las de los funcionarios de carrera (**art. 22**).","No. Los presupuestos fijan los incrementos globales, pero no determinan las retribuciones del personal laboral.","No. No lo fija una Comisión Interministerial.","Es esta. Legislación laboral, convenio colectivo y contrato de trabajo (**art. 27**)."]},{"id":"of-04-004","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":4,"enunciado":"Señale la afirmación correcta en relación con las retribuciones de los funcionarios públicos, según el TREBEP:","opciones":["La cuantía y estructura de las retribuciones complementarias se establecerán en la Ley de Presupuestos Generales del Estado.","Las retribuciones básicas son el sueldo y el complemento de destino.","Quienes ejerciten el derecho de huelga devengarán y percibirán las retribuciones correspondientes.","La parte de jornada no realizada dará lugar a la deducción proporcional de haberes, que no tendrá carácter sancionador."],"bloque":"retribuciones","precepto":"Art. 30.1 del TREBEP","correcta":3,"justificaciones":["No. La cuantía y estructura de las complementarias las establecen las leyes de cada Administración (**art. 24**).","No. Las básicas son el sueldo y los trienios (**art. 23**).","No. Quienes ejercitan la huelga no devengan ni perciben retribuciones por ese tiempo (**art. 30.2**).","Es esta. La parte de jornada no realizada da lugar a deducción proporcional de haberes, sin carácter sancionador (**art. 30.1**)."]},{"id":"of-04-005","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":5,"enunciado":"Señale la afirmación correcta en relación con la regulación de las retribuciones de los funcionarios que se recoge en los artículos 22 a 24 del TREBEP:","opciones":["Las retribuciones básicas de los funcionarios están integradas por el sueldo, los trienios y las pagas extraordinarias.","La cuantía de las retribuciones complementarias de los funcionarios se establecerá por Ley.","Las retribuciones básicas retribuyen al funcionario atendiendo a las condiciones en las que se desempeña el trabajo.","Las pagas extraordinarias son retribuciones complementarias de los funcionarios públicos."],"bloque":"retribuciones","precepto":"Art. 24 del TREBEP","correcta":1,"justificaciones":["No. Las básicas son solo sueldo y trienios (**art. 23**).","Es esta. La cuantía y estructura de las complementarias se establecen por las leyes de cada Administración (**art. 24**).","No. Esa es la función de las complementarias, que retribuyen las características del puesto (**art. 22.3**).","No. Las pagas extraordinarias no son una clase de retribución complementaria."]},{"id":"of-04-006","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":6,"enunciado":"De acuerdo con el texto refundido de la Ley del Estatuto Básico del Empleado Público, ¿cuál de los siguientes factores NO se tendrá en cuenta para establecer la cuantía y estructura de las retribuciones complementarias de los funcionarios?","opciones":["El grado de interés, iniciativa o esfuerzo con que el funcionario desempeña su trabajo y el rendimiento o resultados obtenidos.","Los ingresos que hayan percibido las Administraciones Públicas como contraprestación de cualquier servicio.","La especial dificultad técnica, responsabilidad, dedicación, incompatibilidad exigible para el desempeño de determinados puestos de trabajo y las condiciones en que se desarrolla el trabajo.","Los servicios extraordinarios prestados fuera de la jornada normal de trabajo."],"bloque":"retribuciones","precepto":"Art. 22.5 del TREBEP","correcta":1,"justificaciones":["No. Sí se tiene en cuenta (**art. 24.c**).","Es esta. No se pueden percibir participaciones en ingresos de la Administración como contraprestación de servicios (**art. 22.5**); no es un factor del **art. 24**.","No. Sí se tiene en cuenta (**art. 24.b**).","No. Sí se tiene en cuenta (**art. 24.d**)."]},{"id":"of-04-007","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":7,"enunciado":"Según el TREBEP, las cantidades destinadas a financiar aportaciones a planes de pensiones o contratos de seguros tendrán a todos los efectos la consideración de:","opciones":["Retribución complementaria.","Retribución extraordinaria.","Retribución en especie.","Retribución diferida."],"bloque":"retribuciones","precepto":"Art. 29 del TREBEP","correcta":3,"justificaciones":["No. No se consideran retribución complementaria.","No. No se consideran retribución extraordinaria.","No. No se consideran retribución en especie.","Es esta. Tienen la consideración de retribución diferida (**art. 29**)."]},{"id":"of-04-008","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":8,"enunciado":"Según el TREBEP, el sueldo del personal funcionario se asigna en función de:","opciones":["La especial dificultad técnica, responsabilidad, dedicación e incompatibilidad para el desempeño del puesto de trabajo.","El Subgrupo o Grupo de clasificación profesional.","El grado de interés, iniciativa o esfuerzo con que el funcionario desempeña su trabajo y el rendimiento o resultados obtenidos.","El desempeño, rendimiento o resultados alcanzados por el funcionario."],"bloque":"retribuciones","precepto":"Art. 23.a del TREBEP","correcta":1,"justificaciones":["No. Eso retribuye las complementarias (**art. 24.b**).","Es esta. El sueldo se asigna a cada Subgrupo o Grupo de clasificación profesional (**art. 23.a**).","No. Eso retribuye las complementarias (**art. 24.c**).","No. Eso retribuye las complementarias (**art. 22.3**)."]},{"id":"of-04-009","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":9,"enunciado":"De acuerdo con los artículos 23 y 24 del TREBEP, ¿cuál de los siguientes NO es retribución complementaria?","opciones":["Trienios.","Complemento de destino.","Complemento específico.","Productividad."],"bloque":"retribuciones","precepto":"Art. 23 del TREBEP","correcta":0,"justificaciones":["Es esta. Los trienios son retribución básica (**art. 23.b**).","No. El complemento de destino es complementario.","No. El complemento específico es complementario.","No. La productividad es complementaria (**art. 24.c**)."]},{"id":"of-04-010","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":10,"enunciado":"Según el artículo 26 del TREBEP, las retribuciones de los funcionarios en prácticas comprenderán como mínimo:","opciones":["Las del sueldo del Subgrupo o Grupo, en que aspiren a ingresar.","Las retribuciones complementarias del Subgrupo o Grupo, en que aspiren a ingresar.","El sueldo y las retribuciones complementarias del Subgrupo o Grupo, en que aspiren a ingresar.","Las retribuciones básicas del Subgrupo o Grupo, en que aspiren a ingresar."],"bloque":"retribuciones","precepto":"Art. 26 del TREBEP","correcta":0,"justificaciones":["Es esta. Como mínimo, el sueldo del Subgrupo o Grupo al que aspiren a ingresar (**art. 26**).","No. No se fija un mínimo de complementarias.","No. El mínimo es el sueldo, sin complementarias.","No. El mínimo es el sueldo, sin los trienios."]},{"id":"of-04-011","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":11,"enunciado":"De conformidad con el TREBEP y respecto a los derechos retributivos, los trienios son:","opciones":["Una retribución complementaria.","Una retribución básica.","Una paga extraordinaria.","Una indemnización."],"bloque":"retribuciones","precepto":"Art. 23.b del TREBEP","correcta":1,"justificaciones":["No. Los trienios son retribución básica.","Es esta. Los trienios son retribución básica (**art. 23.b**).","No. Una paga extraordinaria es otra cosa.","No. No son una indemnización."],"dup":"of-04-011"},{"id":"of-04-012","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":12,"enunciado":"Según el artículo 24 del TREBEP, señale cuál de los siguientes conceptos NO forma parte de las retribuciones complementarias de los funcionarios:","opciones":["El complemente de destino.","El complemento específico.","El complemento de productividad.","Los trienios."],"bloque":"retribuciones","precepto":"Art. 23.b del TREBEP","correcta":3,"justificaciones":["No. El complemento de destino es complementario.","No. El complemento específico es complementario.","No. La productividad es complementaria.","Es esta. Los trienios son retribución básica (**art. 23.b**)."]},{"id":"of-04-013","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":13,"enunciado":"En las retribuciones de los funcionarios públicos:","opciones":["El sueldo y los trienios dependen del Grupo o Subgrupo de clasificación profesional al que pertenece su cuerpo o escala.","El complemento de productividad se establece en las leyes anuales de presupuestos .","El complemento específico se establece en las leyes anuales de presupuestos.","Las gratificaciones por servicios extraordinarios se fijan en atención a la valía personal y la consecución de resultados."],"bloque":"retribuciones","precepto":"Art. 23 del TREBEP","correcta":0,"justificaciones":["Es esta. El sueldo se asigna por Subgrupo o Grupo, y los trienios son una cantidad igual para cada uno (**art. 23**).","No. Las complementarias las fijan las leyes de cada Administración, no las leyes de presupuestos (**art. 24**).","No. Las complementarias las fijan las leyes de cada Administración (**art. 24**).","No. Las gratificaciones retribuyen servicios extraordinarios fuera de jornada, no la valía personal (**art. 24.d**)."]},{"id":"of-04-014","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":14,"enunciado":"De conformidad con el TREBEP y respecto a los derechos retributivos, los trienios son:","opciones":["Una retribución complementaria.","Una retribución básica.","Una paga extraordinaria.","Una indemnización."],"bloque":"retribuciones","precepto":"Art. 23.b del TREBEP","correcta":1,"justificaciones":["No. Los trienios son retribución básica.","Es esta. Los trienios son retribución básica (**art. 23.b**).","No. Una paga extraordinaria es otra cosa.","No. No son una indemnización."],"dup":"of-04-011"},{"id":"of-04-015","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":15,"enunciado":"El artículo 24 del TREBEP indica una serie de factores a que podrán atender las correspondientes leyes de cada Administración Pública para establecer la cuantía y estructura de las retribuciones complementarias de los funcionarios. Entre estos factores NO incluye expresamente:","opciones":["El grado de esfuerzo con que el funcionario desempeña su trabajo","Los servicios extraordinarios prestados fuera de la jornada ordinaria de trabajo.","La incompatibilidad exigible.","La especial peligrosidad del puesto."],"bloque":"retribuciones","precepto":"Art. 24 del TREBEP","correcta":3,"justificaciones":["No. Sí lo incluye (**art. 24.c**).","No. Sí lo incluye (**art. 24.d**).","No. Sí lo incluye (**art. 24.b**).","Es esta. La especial peligrosidad no figura expresamente entre los factores del **art. 24**."]},{"id":"of-04-016","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":16,"enunciado":"Según el artículo 23 del TREBEP, las retribuciones básicas estarán integradas por:","opciones":["Sueldo, trienios y pagas extraordinarias.","Sueldo y trienios, única y exclusivamente.","Sueldo, trienios y complementos.","Sueldo y complementos."],"bloque":"retribuciones","precepto":"Art. 23 del TREBEP","correcta":1,"justificaciones":["No. Las pagas extraordinarias no son un concepto básico propio.","Es esta. Sueldo y trienios, única y exclusivamente (**art. 23**).","No. Los complementos no son retribución básica.","No. Faltan los trienios y los complementos no son básicos."]},{"id":"of-04-017","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":17,"enunciado":"Según el artículo 22 del TREBEP, ¿cómo se clasifican las retribuciones de los funcionarios?","opciones":["Retribuciones administrativas y laborales.","Retribuciones básicas y complementarias.","Retribuciones dinerarias o en especie.","Sueldo y Trienios."],"bloque":"retribuciones","precepto":"Art. 22.1 del TREBEP","correcta":1,"justificaciones":["No. Esa no es la clasificación del **art. 22.1**.","Es esta. Básicas y complementarias (**art. 22.1**).","No. Esa no es la clasificación del artículo.","No. Sueldo y trienios son las retribuciones básicas."]},{"id":"of-04-018","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":18,"enunciado":"Según lo establecido en el TREBEP, respecto a los trienios del personal funcionario interino:","opciones":["Se reconocerán los trienios correspondientes a los servicios prestados antes de la entrada en vigor del presente Estatuto que tendrán efectos retributivos únicamente a partir de la entrada en vigor del mismo.","Solo se reconocerán los trienios correspondientes a servicios prestados a partir de la entrada en vigor del presente Estatuto.","Se reconocerán los trienios correspondientes a los servicios prestados antes de la entrada en vigor del presente Estatuto que tendrán efectos retributivos desde la fecha de cumplimiento del primer trienio y sucesivos.","No se reconocerán los trienios correspondientes a los servicios prestados antes de la entrada en vigor del presente Estatuto."],"bloque":"retribuciones","precepto":"Art. 25.2 del TREBEP","correcta":0,"justificaciones":["Es esta. Se reconocen los trienios de servicios anteriores, con efectos retributivos solo desde la entrada en vigor del Estatuto (**art. 25.2**).","No. Se reconocen también los de servicios anteriores.","No. Los efectos retributivos son solo desde la entrada en vigor.","No. Sí se reconocen los de servicios anteriores."]},{"id":"of-04-019","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":19,"enunciado":"Según el artículo 22 del texto refundido de la Ley de Estatuto Básico del Empleado Público, ¿cuántas pagas extraordinarias, y de qué importe, tienen los funcionarios de carrera?","opciones":["Dos pagas extraordinarias al año, cada una por el importe de una mensualidad de las retribuciones básicas.","Dos pagas extraordinarias al año, de idéntico importe al de la mensualidad ordinaria.","Tres pagas extraordinarias al año, cada una por el importe de una mensualidad de las retribuciones básicas.","Dos pagas extraordinarias al año, cada una por el importe de una mensualidad de las retribuciones básicas y de la totalidad de las retribuciones complementarias, salvo aquellas que retribuyan el grado de interés, iniciativa o esfuerzo con que el funcionario desempeña su trabajo y el rendimiento o resultados obtenidos, y las que retribuyan los servicios extraordinarios prestados fuera de la jornada normal de trabajo."],"bloque":"retribuciones","precepto":"Art. 22.4 del TREBEP","correcta":3,"justificaciones":["No. Incluyen también las complementarias, salvo las de los apartados c) y d) del art. 24.","No. No es solo la mensualidad ordinaria: hay excepciones en las complementarias.","No. Son dos pagas, no tres.","Es esta. Dos pagas, cada una de una mensualidad de básicas y de las complementarias, salvo las de rendimiento y servicios extraordinarios (**art. 22.4**)."]},{"id":"of-04-020","origen":"oficiales","test":"TREBEP (Oficial 4) - arts. 21 a 30","n":20,"enunciado":"Indique la respuesta correcta, de conformidad con el artículo 21 del texto refundido de la Ley del Estatuto Básico del Empleado Público:","opciones":["Las cuantías de las retribuciones complementarias y el incremento de las cuantías globales de las retribuciones básicas de los funcionarios y del personal laboral deberán reflejarse para cada ejercicio presupuestario en la correspondiente ley de presupuestos.","Las cuantías de las retribuciones complementarias y el incremento de las cuantías globales de las retribuciones básicas de los funcionarios y del personal laboral deberán reflejarse para cada ejercicio presupuestario en la correspondiente Orden del Ministerio de Hacienda sobre la confección de nóminas anuales.","Las cuantías de las retribuciones básicas y el incremento de las cuantías globales de las retribuciones complementarias de los funcionarios, así como el incremento de la masa salarial del personal laboral deberán reflejarse para cada ejercicio presupuestario en la correspondiente ley de presupuestos.","Las cuantías de las retribuciones básicas y complementarias de los funcionarios y su repercusión en su masa salarial deberán reflejarse para cada ejercicio presupuestario en la correspondiente ley de presupuestos."],"bloque":"retribuciones","precepto":"Art. 21.1 del TREBEP","correcta":2,"justificaciones":["No. Invierte básicas y complementarias: la ley fija las cuantías de las básicas y el incremento de las complementarias.","No. No es una orden ministerial: es la ley de presupuestos.","Es esta. Las cuantías de las básicas y el incremento global de las complementarias, y la masa salarial del personal laboral, en la ley de presupuestos (**art. 21.1**).","No. Las cuantías de las complementarias no se fijan en la ley de presupuestos."]},{"id":"of-05-001","origen":"oficiales","test":"TREBEP (Oficial 5) - arts. 31 a 38","n":1,"enunciado":"En relación con la negociación colectiva de los funcionarios públicos, el artículo 34 del TREBEP establece que, dependiendo de las Mesas Generales de Negociación y por acuerdo de las mismas, podrán constituirse:","opciones":["Mesas Especiales.","Mesas Sectoriales.","Mesas Especializadas.","Mesas Delegadas."],"bloque":"negociacion","precepto":"Art. 34.4 del TREBEP","correcta":1,"justificaciones":["No. Las Mesas Especiales no existen en el artículo.","Es esta. Dependiendo de las Mesas Generales pueden constituirse Mesas Sectoriales (**art. 34.4**).","No. Las Mesas Especializadas no existen en el artículo.","No. Las Mesas Delegadas no existen en el artículo."]},{"id":"of-05-002","origen":"oficiales","test":"TREBEP (Oficial 5) - arts. 31 a 38","n":2,"enunciado":"Según el Texto Refundido del Estatuto Básico del Empleado Público NO es objeto de negociación colectiva:","opciones":["Los planes de Previsión Social complementaria.","Los criterios generales de Acción Social.","Los poderes de dirección y control propios de la relación jerárquica.","Los criterios generales sobre Oferta de Empleo Público."],"bloque":"negociacion","precepto":"Art. 37.2.d del TREBEP","correcta":2,"justificaciones":["No. Sí es objeto de negociación (**art. 37.1.e**).","No. Sí es objeto de negociación (**art. 37.1.i**).","Es esta. Los poderes de dirección y control propios de la relación jerárquica están excluidos (**art. 37.2.d**).","No. Sí es objeto de negociación (**art. 37.1.l**)."]},{"id":"of-05-003","origen":"oficiales","test":"TREBEP (Oficial 5) - arts. 31 a 38","n":3,"enunciado":"Según el TREBEP, queda excluida de la obligatoriedad de negociación colectiva:","opciones":["La determinación y aplicación de las retribuciones complementarias de los funcionarios.","La determinación de las condiciones de trabajo del personal directivo.","Los criterios generales sobre oferta empleo público.","Las normas que fijen los mecanismos generales de evaluación del desempeño."],"bloque":"negociacion","precepto":"Art. 37.2.c del TREBEP","correcta":1,"justificaciones":["No. Es objeto de negociación (**art. 37.1.b**).","Es esta. La determinación de condiciones de trabajo del personal directivo está excluida (**art. 37.2.c**).","No. Es objeto de negociación (**art. 37.1.l**).","No. Es objeto de negociación (**art. 37.1.d**)."]},{"id":"of-05-004","origen":"oficiales","test":"TREBEP (Oficial 5) - arts. 31 a 38","n":4,"enunciado":"Según el artículo 35 del TREBEP, y respecto a la composición de las Mesas de Negociación, ninguna de las partes negociadoras podrá superar el número de:","opciones":["Diez miembros.","Quince miembros.","Veinte miembros.","Treinta miembros."],"bloque":"negociacion","precepto":"Art. 35.4 del TREBEP","correcta":1,"justificaciones":["No. El máximo es quince, no diez.","Es esta. Ninguna de las partes puede superar quince miembros (**art. 35.4**).","No. El máximo es quince, no veinte.","No. El máximo es quince, no treinta."]},{"id":"of-05-005","origen":"oficiales","test":"TREBEP (Oficial 5) - arts. 31 a 38","n":5,"enunciado":"De acuerdo con el TREBEP, quedará excluida de la obligatoriedad de la negociación colectiva:","opciones":["La regulación del ejercicio de los derechos de los ciudadanos y de los usuarios de los servicios públicos.","Los criterios generales sobre oferta de empleo público.","La determinación y aplicación de las retribuciones complementarias de los funcionarios.","Las normas que fijen los mecanismos generales de evaluación del desempeño."],"bloque":"negociacion","precepto":"Art. 37.2.b del TREBEP","correcta":0,"justificaciones":["Es esta. La regulación del ejercicio de los derechos de los ciudadanos y usuarios está excluida (**art. 37.2.b**).","No. Es objeto de negociación (**art. 37.1.l**).","No. Es objeto de negociación (**art. 37.1.b**).","No. Es objeto de negociación (**art. 37.1.d**)."]},{"id":"of-05-006","origen":"oficiales","test":"TREBEP (Oficial 5) - arts. 31 a 38","n":6,"enunciado":"Son materia objeto de negociación según el TREBEP:","opciones":["Los criterios generales de acción social.","La determinación de condiciones de trabajo del personal directivo.","Los poderes de dirección y control propios de la relación jerárquica.","Todas las relacionadas con la prevención de riesgos laborales."],"bloque":"negociacion","precepto":"Art. 37.1.i del TREBEP","correcta":0,"justificaciones":["Es esta. Los criterios generales de acción social (**art. 37.1.i**).","No. Las condiciones del personal directivo están excluidas (**art. 37.2.c**).","No. Los poderes de dirección y control están excluidos (**art. 37.2.d**).","No. Solo las materias que establezca la normativa de prevención de riesgos laborales (**art. 37.1.j**)."]},{"id":"of-05-007","origen":"oficiales","test":"TREBEP (Oficial 5) - arts. 31 a 38","n":7,"enunciado":"Conforme al TREBEP, los Pactos y Acuerdos alcanzados en el seno de las Mesas de Negociación:","opciones":["Se aplican directamente al personal del ámbito correspondiente de la Mesa.","Solo se aplican directamente los Pactos, ya que los Acuerdos requieren para su validez y eficacia, en todo caso, la aprobación expresa por Ley de las Cortes Generales o Asambleas Legislativas de las Comunidades Autónomas.","Solo se aplican directamente los Acuerdos salvo que versen sobre materias sometidas a reserva de Ley.","Ambos se aplican directamente, pero en el caso de Acuerdos tiene que haber habido ratificación y afectar a temas que puedan ser decididos definitivamente por los órganos de gobierno."],"bloque":"negociacion","precepto":"Art. 38 del TREBEP","correcta":3,"justificaciones":["No. Los Acuerdos requieren aprobación expresa y formal del órgano de gobierno (**art. 38.3**).","No. Los Acuerdos no requieren siempre una ley: solo si versan sobre reserva de ley.","No. Los Acuerdos también se aplican directamente cuando están ratificados y versan sobre materias que decide el órgano de gobierno.","Es esta. Los Pactos se aplican directamente; los Acuerdos, si están ratificados y afectan a temas que decide el órgano de gobierno (**art. 38.2 y 38.3**)."]},{"id":"of-05-008","origen":"oficiales","test":"TREBEP (Oficial 5) - arts. 31 a 38","n":8,"enunciado":"¿Cuál de las siguientes materias NO ha de ser objeto de negociación según el artículo 37 del TREBEP?","opciones":["La aplicación del incremento de las retribuciones del personal al servicio de las Administraciones Públicas que se establezca en la Ley de Presupuestos Generales del Estado y de las Comunidades Autónomas.","Los planes de Previsión Social Complementaria.","Los criterios generales para la determinación de prestaciones sociales y pensiones de clases pasivas.","La determinación de condiciones de trabajo del personal directivo."],"bloque":"negociacion","precepto":"Art. 37.2.c del TREBEP","correcta":3,"justificaciones":["No. Sí es objeto de negociación (**art. 37.1.a**).","No. Sí es objeto de negociación (**art. 37.1.e**).","No. Sí es objeto de negociación (**art. 37.1.g**).","Es esta. Las condiciones del personal directivo están excluidas (**art. 37.2.c**)."]},{"id":"of-05-009","origen":"oficiales","test":"TREBEP (Oficial 5) - arts. 31 a 38","n":9,"enunciado":"Según el TREBEP, los instrumentos de negociación celebrados sobre materias que se correspondan estrictamente con el ámbito competencia del órgano que lo suscriba y se apliquen directamente al personal del ámbito correspondiente, son:","opciones":["Acuerdos.","Pactos.","Convenios.","Conciertos."],"bloque":"negociacion","precepto":"Art. 38.2 del TREBEP","correcta":1,"justificaciones":["No. Los Acuerdos versan sobre materias de los órganos de gobierno.","Es esta. Los Pactos se celebran sobre materias del ámbito del órgano que los suscribe y se aplican directamente (**art. 38.2**).","No. Los Convenios no son el instrumento del artículo.","No. Los Conciertos no son el instrumento del artículo."]},{"id":"of-05-010","origen":"oficiales","test":"TREBEP (Oficial 5) - arts. 31 a 38","n":10,"enunciado":"De acuerdo con el artículo 37.2 del Texto Refundido de la Ley del Estatuto Básico del Empleado Público queda EXCLUIDA de la obligatoriedad de la negociación colectiva la siguiente materia:","opciones":["Las referidas a calendario laboral, vacaciones, permisos, movilidad funcional y geográfica de los empleados públicos.","Las que afecten a las condiciones de trabajo de los funcionarios.","La regulación y determinación concreta, en cada caso, de los procedimientos de acceso al empleo público.","La aplicación del incremento de las retribuciones del personal al servicio de las Administraciones Públicas que se establezca en la Ley de Presupuestos Generales del Estado y de las Comunidades Autónomas."],"bloque":"negociacion","precepto":"Art. 37.2.e del TREBEP","correcta":2,"justificaciones":["No. Es objeto de negociación (**art. 37.1.m**).","No. Es objeto de negociación (**art. 37.1**).","Es esta. La regulación concreta de los procedimientos de acceso al empleo público está excluida (**art. 37.2.e**).","No. Es objeto de negociación (**art. 37.1.a**)."]},{"id":"of-05-011","origen":"oficiales","test":"TREBEP (Oficial 5) - arts. 31 a 38","n":11,"enunciado":"De acuerdo con el artículo 33.1 del TREBEP, ¿a cuál de estos principios está sujeta la negociación colectiva de las condiciones de trabajo de los funcionarios públicos?","opciones":["Al principio de jerarquía.","Al principio de seguridad jurídica.","Al principio de cobertura presupuestaria.","Al principio de voluntariedad."],"bloque":"negociacion","precepto":"Art. 33.1 del TREBEP","correcta":2,"justificaciones":["No. La jerarquía no es uno de los principios del **art. 33.1**.","No. La seguridad jurídica no es uno de ellos.","Es esta. Cobertura presupuestaria, junto con legalidad, obligatoriedad, buena fe, publicidad y transparencia (**art. 33.1**).","No. La voluntariedad no es uno de ellos: la negociación es obligatoria."]},{"id":"of-05-012","origen":"oficiales","test":"TREBEP (Oficial 5) - arts. 31 a 38","n":12,"enunciado":"El TREBEP establece que serán objeto obligado de negociación las materias siguientes:","opciones":["Los poderes de dirección y control propios de la relación jerárquica.","La determinación y aplicación de las retribuciones complementarias de los funcionarios.","La regulación y determinación concreta, en cada caso, de los sistemas de promoción profesional.","La regulación del ejercicio de los derechos de los ciudadanos y de los usuarios de los servicios públicos"],"bloque":"negociacion","precepto":"Art. 37.1.b del TREBEP","correcta":1,"justificaciones":["No. Están excluidos (**art. 37.2.d**).","Es esta. La determinación y aplicación de las retribuciones complementarias (**art. 37.1.b**).","No. La regulación concreta de la promoción profesional está excluida (**art. 37.2.e**).","No. Está excluida (**art. 37.2.b**)."]},{"id":"of-05-013","origen":"oficiales","test":"TREBEP (Oficial 5) - arts. 31 a 38","n":13,"enunciado":"Según el TREBEP, ¿qué materia queda excluida de la obligatoriedad de la negociación colectiva?","opciones":["La determinación y aplicación de las retribuciones complementarias del personal funcionario.","Las normas que fijen los criterios y mecanismos generales en materia de evaluación del desempeño.","La regulación y determinación concreta, en cada caso, de los sistemas, criterios y procedimientos de acceso al empleo público.","Los planes de Previsión Social Complementaria."],"bloque":"negociacion","precepto":"Art. 37.2.e del TREBEP","correcta":2,"justificaciones":["No. Es objeto de negociación (**art. 37.1.b**).","No. Es objeto de negociación (**art. 37.1.d**).","Es esta. La regulación concreta de los sistemas y procedimientos de acceso al empleo público está excluida (**art. 37.2.e**).","No. Es objeto de negociación (**art. 37.1.e**)."]},{"id":"of-05-014","origen":"oficiales","test":"TREBEP (Oficial 5) - arts. 31 a 38","n":14,"enunciado":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, ¿qué se entiende por negociación colectiva?","opciones":["El derecho a participar, a través de las organizaciones sindicales, en los órganos de control y seguimiento de las entidades u organismos que legalmente se determine.","El derecho a elegir representantes y constituir órganos unitarios a través de los cuales se instrumente la interlocución entre las Administraciones Públicas y sus empleados.","El derecho a negociar la determinación de condiciones de trabajo de los empleados de la Administración Pública.","El derecho a negociar la determinación de condiciones de trabajo de, únicamente, el personal laboral de la Administración Pública."],"bloque":"negociacion","precepto":"Art. 31.2 del TREBEP","correcta":2,"justificaciones":["No. Eso es la participación institucional (**art. 31.4**).","No. Eso es la representación (**art. 31.3**).","Es esta. El derecho a negociar la determinación de condiciones de trabajo de los empleados de la Administración Pública (**art. 31.2**).","No. No es solo del personal laboral."]},{"id":"of-06-001","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":1,"enunciado":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, los miembros de la Junta de Personal dispondrán, en el ejercicio de su función representativa, de las siguientes garantías y derechos:","opciones":["El acceso y libre circulación por las dependencias del ministerio sin ningún límite horario.","La audiencia en los expedientes disciplinarios a que pudieran ser sometidos sus miembros durante el tiempo de su mandato y durante los 2 años inmediatamente posteriores.","La distribución libre de las publicaciones que se refieran a cuestiones profesionales y sindicales.","No ser trasladados ni sancionados por causas relacionadas con el ejercicio de su mandato representativo, ni durante la vigencia del mismo, ni en los 2 años siguientes a su extinción."],"bloque":"representacion","precepto":"Art. 41.1.b del TREBEP","correcta":2,"justificaciones":["No. El acceso y libre circulación es dentro de los horarios habituales de trabajo, no sin límite horario (**art. 41.1.a**).","No. La audiencia en expedientes disciplinarios es durante el mandato y el año posterior, no dos (**art. 41.1.c**).","Es esta. La distribución libre de publicaciones sobre cuestiones profesionales y sindicales (**art. 41.1.b**).","No. La protección frente a traslados y sanciones es durante el mandato y el año siguiente, no dos (**art. 41.1.e**)."]},{"id":"of-06-002","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":2,"enunciado":"Conforme al Texto Refundido del Estatuto Básico del Empleado Público, señale la afirmación correcta en relación a la elección de los Delegados de Personal:","opciones":["Se eligen mediante listas cerradas y sistema proporcional.","Se eligen mediante listas abiertas y sistema mayoritario.","Se eligen mediante listas abiertas y sistema proporcional.","Se eligen mediante listas cerradas y sistema proporcional corregido."],"bloque":"representacion","precepto":"Art. 44.d del TREBEP","correcta":1,"justificaciones":["No. Los Delegados se eligen por listas abiertas, y el sistema es mayoritario.","Es esta. Listas abiertas y sistema mayoritario (**art. 44.d**).","No. Las listas son abiertas, pero el sistema es mayoritario, no proporcional.","No. Esa es la fórmula de las Juntas de Personal."]},{"id":"of-06-003","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":3,"enunciado":"Según el artículo 46 del texto refundido de la Ley del Estatuto Básico del Empleado Público, ¿quiénes de los siguientes NO están legitimados para convocar una reunión en el centro de trabajo en ejercicio del derecho de reunión?","opciones":["Las Juntas de Personal.","Los Comités de Empresa.","Los empleados públicos de las Administraciones respectivas en número no inferior al 40 % del colectivo convocado.","Los Delegados de Prevención."],"bloque":"representacion","precepto":"Art. 46.1 del TREBEP","correcta":3,"justificaciones":["No. Las Juntas de Personal sí están legitimadas (**art. 46.1.b**).","No. Los Comités de Empresa sí están legitimados (**art. 46.1.c**).","No. Los empleados públicos sí, si son al menos el 40 por 100 (**art. 46.1.d**).","Es esta. Los Delegados de Prevención no figuran entre los legitimados del **art. 46.1**."]},{"id":"of-06-004","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":4,"enunciado":"De acuerdo con el artículo 39 del TREBEP, ¿cuáles son los órganos específicos de representación de los funcionarios?","opciones":["Los Delegados de Personal y los Comités de Empresa.","Los Delegados Sindicales y los Comités de Empresa.","Los Delegados de Personal y las Juntas de Personal.","Las Mesa General de Negociación de la Administración General del Estado."],"bloque":"representacion","precepto":"Art. 39.1 del TREBEP","correcta":2,"justificaciones":["No. Los Comités de Empresa son del personal laboral.","No. Los Delegados Sindicales y los Comités de Empresa no son los órganos específicos de funcionarios.","Es esta. Los Delegados de Personal y las Juntas de Personal (**art. 39.1**).","No. Las Mesas de Negociación son órganos de negociación, no de representación."]},{"id":"of-06-005","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":5,"enunciado":"Según el TREBEP, están legitimados para convocar una reunión, además de las Organizaciones Sindicales y de las personas o colectivos citados en el artículo 46, los empleados públicos de las Administraciones respectivas:","opciones":["En número no inferior al 20 por 100 del colectivo convocado.","En número no inferior al 30 por 100 del colectivo convocado.","En número no inferior al 40 por 100 del colectivo convocado.","En número no inferior al 50 por 100 del colectivo convocado."],"bloque":"representacion","precepto":"Art. 46.1.d del TREBEP","correcta":2,"justificaciones":["No. El mínimo es el 40 por 100, no el 20.","No. El mínimo es el 40 por 100, no el 30.","Es esta. En número no inferior al 40 por 100 del colectivo convocado (**art. 46.1.d**).","No. El mínimo es el 40 por 100, no el 50."]},{"id":"of-06-006","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":6,"enunciado":"Según el TREBEP, en relación con los órganos de representación de los funcionarios públicos:","opciones":["El mandato de los miembros de las Juntas de Personal y de los Delegados de Personal será de 2 años, prorrogables por otros 2.","El mandato de los miembros de las Juntas de Personal y de los Delegados de Personal será de 4 años pudiendo ser reelegidos.","El mandato de los miembros de las Juntas de Personal se entenderá prorrogado si se hubieran promovido nuevas elecciones.","Los miembros de las Juntas de Personal y los Delegados de Personal no podrán ser reelegidos."],"bloque":"representacion","precepto":"Art. 42 del TREBEP","correcta":1,"justificaciones":["No. El mandato es de cuatro años, no de dos.","Es esta. Cuatro años, pudiendo ser reelegidos (**art. 42**).","No. Se prorroga si no se hubiesen promovido nuevas elecciones, no si se han promovido.","No. Sí pueden ser reelegidos."]},{"id":"of-06-007","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":7,"enunciado":"Según el TREBEP, es una de las funciones de las Juntas de Personal y los Delegados de Personal:","opciones":["Vigilar el cumplimiento de las normas vigentes en materia de condiciones de trabajo.","Acordar la regulación y determinación de forma concreta, en cada caso, de los sistemas de acceso al empleo público.","Negociar las normas que fijen los criterios y mecanismos generales en materia de evaluación del desempeño.","Negociar los criterios generales de los planes y fondos para la formación y la promoción interna."],"bloque":"representacion","precepto":"Art. 40.1.e del TREBEP","correcta":0,"justificaciones":["Es esta. Vigilar el cumplimiento de las normas vigentes en materia de condiciones de trabajo (**art. 40.1.e**).","No. Esa regulación está excluida de la negociación (**art. 37.2.e**) y no es función de las Juntas.","No. Negociar es función de las Mesas de Negociación, no de las Juntas.","No. Negociar es función de las Mesas de Negociación, no de las Juntas."]},{"id":"of-06-008","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":8,"enunciado":"Un Delegado de Personal, en el ejercicio de su función representativa, dispondrá de un crédito de horas mensuales retribuidas y dentro de la jornada laboral, de acuerdo con la siguiente escala:","opciones":["Hasta 100 funcionarios: 20 horas.","De 101 a 250 funcionarios: 30 horas.","De 501 a 750 funcionarios: 30 horas.","De 751 en adelante: 40 horas."],"bloque":"representacion","precepto":"Art. 41.1.d del TREBEP","correcta":3,"justificaciones":["No. Hasta 100 funcionarios son 15 horas, no 20.","No. De 101 a 250 son 20 horas, no 30.","No. De 501 a 750 son 35 horas, no 30.","Es esta. De 751 en adelante son 40 horas (**art. 41.1.d**)."]},{"id":"of-06-009","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":9,"enunciado":"Conforme al TREBEP, en materia de órganos de representación, en las unidades electorales donde el número de funcionarios sea igual o superior a 6 e inferior a 50, su representación corresponderá:","opciones":["A la Junta de Personal más cercana de la misma provincia.","A los Delegados de Personal.","Al Comité de Empresa.","Al trabajador que designe por elección la Junta de Personal provincial."],"bloque":"representacion","precepto":"Art. 39.2 del TREBEP","correcta":1,"justificaciones":["No. No corresponde a otra Junta de Personal.","Es esta. A los Delegados de Personal (**art. 39.2**).","No. El Comité de Empresa es del personal laboral.","No. No se designa a un trabajador por la Junta provincial."]},{"id":"of-06-010","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":10,"enunciado":"Según el artículo 43 del TREBEP, ¿quiénes podrán promover la celebración de elecciones a Delegados y Juntas de Personal?","opciones":["Los funcionarios de la unidad electoral, lo que exigirá acuerdo adoptado por unanimidad.","Los sindicatos que hayan obtenido al menos un porcentaje del 5 por 100 de los representantes.","Los sindicatos que, sin ser más representativos, hayan conseguido al menos el 15 por 100 de los representantes en el conjunto de las Administraciones Públicas.","Los sindicatos más representativos a nivel de Comunidad Autónoma, si la unidad electoral se ubica en su ámbito geográfico."],"bloque":"representacion","precepto":"Art. 43.1 del TREBEP","correcta":3,"justificaciones":["No. Los funcionarios lo hacen por acuerdo mayoritario, no unánime (**art. 43.1.e**).","No. El porcentaje es del 10 por 100, no del 5 (**art. 43.1.d**).","No. El porcentaje es del 10 por 100, no del 15 (**art. 43.1.c**).","Es esta. Los sindicatos más representativos a nivel de comunidad autónoma, si la unidad está en su ámbito (**art. 43.1.b**)."]},{"id":"of-06-011","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":11,"enunciado":"Según el artículo 39 del TREBEP, en unidades electorales donde el número de funcionarios esté comprendido entre 101 y 250 funcionarios, el órgano de representación de estos corresponderá:","opciones":["Al Comité de empresa.","A los Delegados de Personal.","A la Junta de Personal.","A los Delegados de Prevención."],"bloque":"representacion","precepto":"Art. 39.3 del TREBEP","correcta":2,"justificaciones":["No. El Comité de Empresa es del personal laboral.","No. Los Delegados de Personal son para unidades de 6 a 49 funcionarios.","Es esta. Con 101 a 250 funcionarios hay Junta de Personal, que se constituye desde 50 (**art. 39.3**).","No. Los Delegados de Prevención no son órganos de representación del art. 39."]},{"id":"of-06-012","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":12,"enunciado":"De conformidad con el TREBEP, y en coherencia con lo establecido en el Estatuto de los Trabajadores, una Unidad electoral integrada por 550 funcionarios, estará representada por una Junta de Personal compuesta por:","opciones":["5 representantes.","9 representantes.","13 representantes.","17 representantes."],"bloque":"representacion","precepto":"Art. 39.5 del TREBEP","correcta":3,"justificaciones":["No. Cinco representantes es el tramo de 50 a 100.","No. Nueve es el tramo de 101 a 250.","No. Trece es el tramo de 251 a 500.","Es esta. Con 550 funcionarios se está en el tramo de 501 a 750, con 17 representantes (**art. 39.5**)."]},{"id":"of-06-013","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":13,"enunciado":"De conformidad con el TREBEP, respecto a los órganos de representación de los funcionarios y funcionarias, ¿cuál es el plazo del mandato de los Delegados de Personal?","opciones":["Cuatro años improrrogables.","Cuatro años, pudiendo ser reelegidos.","Cinco años improrrogables.","Cinco años, pudiendo ser reelegidos."],"bloque":"representacion","precepto":"Art. 42 del TREBEP","correcta":1,"justificaciones":["No. Sí pueden ser reelegidos, y el mandato se prorroga si no hay nuevas elecciones.","Es esta. Cuatro años, pudiendo ser reelegidos (**art. 42**).","No. El mandato es de cuatro años, no cinco.","No. El mandato es de cuatro años, no cinco."]},{"id":"of-06-014","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":14,"enunciado":"Según el TREBEP, y en relación con los derechos de negociación colectiva, representación y participación institucional, señale la afirmación correcta:","opciones":["Las Juntas de Personal representan al personal laboral de cada organización.","Las Juntas de Personal representan al personal funcionario y laboral de los Departamentos Ministeriales.","Las Mesas de Negociación se constituyen allí donde no hay Juntas de Personal o Comités de Empresa.","Los Delegados de Personal se eligen por un mandato de cuatro años."],"bloque":"representacion","precepto":"Art. 42 del TREBEP","correcta":3,"justificaciones":["No. Las Juntas de Personal representan a los funcionarios, no al personal laboral.","No. Representan al personal funcionario, no al laboral.","No. Las Mesas de Negociación se constituyen para la negociación, no sustituyen a la representación.","Es esta. El mandato de los Delegados de Personal es de cuatro años (**art. 42**)."]},{"id":"of-06-015","origen":"oficiales","test":"TREBEP (Oficial 6) - arts. 39 a 46","n":15,"enunciado":"Conforme al texto refundido de la Ley del Estatuto Básico del Empleado Público, ¿cuáles son los órganos específicos de representación del personal funcionario al servicio de la Administración General del Estado?","opciones":["Los Comités de Empresa y los Delegados de Personal.","Los Comités de Empresa.","Juntas de Personal y Delegados de Personal.","Mesas de Negociación."],"bloque":"representacion","precepto":"Art. 39.1 del TREBEP","correcta":2,"justificaciones":["No. Los Comités de Empresa son del personal laboral.","No. Los Comités de Empresa son del personal laboral.","Es esta. Las Juntas de Personal y los Delegados de Personal (**art. 39.1**).","No. Las Mesas de Negociación no son órganos de representación."]},{"id":"of-07-001","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":1,"enunciado":"Conforme al TREBEP, los funcionarios públicos tendrán derecho a disfrutar, como mínimo, durante cada año natural, de unas vacaciones retribuidas de:","opciones":["Treinta días hábiles, o de los días que correspondan proporcionalmente si el tiempo de servicio durante el año fue menor.","Treinta y dos días hábiles, o de los días que correspondan proporcionalmente si el tiempo de servicio durante el año fue menor.","Veinte días hábiles, o de los días que correspondan proporcionalmente si el tiempo de servicio durante el año fue menor.","Veintidós días hábiles, o de los días que correspondan proporcionalmente si el tiempo de servicio durante el año fue menor."],"bloque":"jornada","precepto":"Art. 50.1 del TREBEP","correcta":3,"justificaciones":["No. Son veintidós días hábiles, no treinta.","No. Son veintidós días hábiles, no treinta y dos.","No. Son veintidós días hábiles, no veinte.","Es esta. Veintidós días hábiles, o los proporcionales si el servicio fue menor (**art. 50.1**)."]},{"id":"of-07-002","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":2,"enunciado":"¿Cuál de los siguientes es un permiso del que puede disfrutar D. Alfredo según el artículo 48 del TREBEP?","opciones":["Por traslado de domicilio sin cambio de residencia, 2 días.","Para concurrir a exámenes finales y demás pruebas definitivas de aptitud, un tiempo máximo de 4 horas.","Por enfermedad grave de un familiar dentro del primer grado de afinidad, 5 días hábiles.","6 días al año para el cumplimiento de un deber inexcusable de carácter público o personal."],"bloque":"jornada","precepto":"Art. 48.a del TREBEP","correcta":2,"justificaciones":["No. El traslado sin cambio de residencia da un día, no dos (**art. 48.b**).","No. Para exámenes finales el permiso dura los días de su celebración (**art. 48.d**).","Es esta. Enfermedad grave de un familiar de primer grado por afinidad, cinco días hábiles (**art. 48.a**).","No. Los asuntos particulares son seis días al año (**art. 48.k**); el deber inexcusable es el tiempo indispensable (**art. 48.j**)."]},{"id":"of-07-003","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":3,"enunciado":"¿Qué permisos podrá disfrutar D. Manuel por el nacimiento de su hijo?","opciones":["Un permiso de 19 semanas, de las que las seis primeras serán de descanso obligatorio.","Un permiso de lactancia por hijo menor de 18 meses.","Un permiso de 19 semanas, que habrá de ser en todo caso simultáneo al de la madre biológica.","Un permiso de 18 semanas, de las que las 10 primeras serán de descanso obligatorio."],"bloque":"jornada","precepto":"Art. 49.c del TREBEP","correcta":0,"justificaciones":["Es esta. El progenitor diferente de la madre biológica tiene 19 semanas, de las que las seis primeras son obligatorias (**art. 49.c**).","No. La lactancia es para hijos menores de doce meses (**art. 48.f**).","No. No tiene que ser simultáneo al de la madre.","No. Son 19 semanas, con seis obligatorias, no 18 con diez."]},{"id":"of-07-004","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":4,"enunciado":"El día 15 de junio Dª Flor Jiménez, funcionaria de carrera, solicitó un permiso de tres días por la hospitalización de un tío, hermano de su padre, en distinta localidad. ¿Es posible autorizar a la Sra. Jiménez el permiso que solicita?","opciones":["No, porque al tratarse del hermano de su padre se considera un familiar de segundo grado de consanguinidad.","Sí, pero se deberían autorizar cuatro días hábiles por tratarse de un familiar de segundo grado.","Sí, pero se deberían autorizar cinco días hábiles, por ser un familiar de primer grado.","En ningún caso, porque se trata de un pariente de tercer grado de consanguinidad."],"bloque":"jornada","precepto":"Art. 48.a del TREBEP","correcta":3,"justificaciones":["No. El hermano del padre es tío: pariente de tercer grado de consanguinidad, no de segundo.","No. No es un familiar de segundo grado.","No. No es un familiar de primer grado.","Es esta. Un tío es pariente de tercer grado, y el permiso solo cubre hasta el segundo (**art. 48.a**)."]},{"id":"of-07-005","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":5,"enunciado":"La mujer del hermano de uno de los funcionarios adscritos a su Unidad sufrió un accidente de tráfico con pronóstico grave, en la misma localidad. ¿Qué permiso le correspondería a este funcionario por el accidente de su cuñada?","opciones":["Dos días hábiles.","Tres días hábiles.","Cuatro días hábiles.","No le corresponde ningún permiso por esta situación."],"bloque":"jornada","precepto":"Art. 48.a del TREBEP","correcta":2,"justificaciones":["No. Son cuatro días hábiles, no dos.","No. Son cuatro días hábiles, no tres.","Es esta. La cuñada es familiar de segundo grado por afinidad: cuatro días hábiles (**art. 48.a**).","No. Sí le corresponde: es un familiar de segundo grado por afinidad."]},{"id":"of-07-006","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":6,"enunciado":"Según el TREBEP, ¿a cuántos días asciende el permiso que podría disfrutar un funcionario de carrera, destinado en el exterior, en caso de enfermedad grave de un familiar de primer grado de consanguinidad?","opciones":["3 días hábiles.","3 días naturales.","5 días hábiles.","5 días naturales."],"bloque":"jornada","precepto":"Art. 48.a del TREBEP","correcta":2,"justificaciones":["No. Son cinco días hábiles, no tres.","No. Son cinco días hábiles, no tres naturales.","Es esta. Cinco días hábiles para un familiar de primer grado (**art. 48.a**).","No. Son días hábiles, no naturales."]},{"id":"of-07-007","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":7,"enunciado":"De acuerdo con el artículo 48 del TREBEP, cuando el suceso se produzca en distinta localidad, los funcionarios públicos tienen derecho a un permiso de:","opciones":["Dos días hábiles, por fallecimiento de un familiar dentro del primer grado de consanguinidad o afinidad.","Tres días hábiles, por fallecimiento de un familiar dentro del segundo grado de consanguinidad o afinidad.","Cuatro días hábiles, por fallecimiento de un familiar dentro del segundo grado de consanguinidad o afinidad.","Cinco días hábiles, por fallecimiento de un familiar dentro del segundo grado de consanguinidad o afinidad."],"bloque":"jornada","precepto":"Art. 48.a del TREBEP","correcta":2,"justificaciones":["No. En primer grado, en distinta localidad, son cinco días hábiles.","No. En segundo grado, en distinta localidad, son cuatro, no tres.","Es esta. Cuatro días hábiles por fallecimiento de un familiar de segundo grado en distinta localidad (**art. 48.a**).","No. En segundo grado son cuatro días, no cinco."]},{"id":"of-07-008","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":8,"enunciado":"Una funcionaria se pone en contacto con la Unidad de Personal para indicar que el tío de su marido, que convive con ellos en el mismo domicilio y que requiere el cuidado efectivo de aquella, ha sido sometido a una operación quirúrgica ambulatoria y debe permanecer unos días de reposo en casa. ¿Tendría derecho a un permiso en relación con esta circunstancia?","opciones":["No, porque es un familiar de tercer grado.","Sí, tendría derecho a un permiso de 4 días hábiles.","No, porque la normativa no contempla permisos para situaciones de intervenciones quirúrgicas sin hospitalización.","Sí, tendría derecho a un permiso de 5 días hábiles."],"bloque":"jornada","precepto":"Art. 48.a del TREBEP","correcta":3,"justificaciones":["No. Aunque sea de tercer grado, convive con ella y requiere su cuidado, que también da derecho.","No. Son cinco días hábiles, no cuatro.","No. Sí se contempla la intervención quirúrgica sin hospitalización con reposo domiciliario.","Es esta. Cualquier persona que conviva con la funcionaria y requiera su cuidado efectivo da derecho a cinco días hábiles (**art. 48.a**)."]},{"id":"of-07-009","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":9,"enunciado":"Un funcionario debe desplazarse a Rusia para un proceso de adopción internacional. Según el TREBEP, ¿le corresponde algún permiso por este viaje?","opciones":["Sí, de hasta dos meses de duración, percibiendo las retribuciones íntegras.","Sí, de hasta un mes de duración, percibiendo las retribuciones íntegras.","Sí, de hasta un mes de duración, percibiendo exclusivamente las retribuciones básicas.","Sí, de hasta dos meses de duración, percibiendo exclusivamente las retribuciones básicas."],"bloque":"jornada","precepto":"Art. 49.b del TREBEP","correcta":3,"justificaciones":["No. Se perciben exclusivamente las retribuciones básicas, no las íntegras.","No. La duración es de hasta dos meses, y solo las retribuciones básicas.","No. La duración es de hasta dos meses, no uno.","Es esta. Hasta dos meses, con retribuciones básicas exclusivamente (**art. 49.b**)."]},{"id":"of-07-010","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":10,"enunciado":"Según el TREBEP, un funcionario tendrá derecho a reducir su jornada hasta un 50% por razones de enfermedad muy grave de un familiar de primer grado y por un periodo máximo de un mes. Durante el mismo percibirá:","opciones":["Sus retribuciones íntegras.","Las retribuciones básicas.","Las retribuciones proporcionales a su reducción de jornada.","Las retribuciones básicas y el 75 por cien de las retribuciones complementarias."],"bloque":"jornada","precepto":"Art. 48.i del TREBEP","correcta":0,"justificaciones":["Es esta. La reducción es con carácter retribuido: retribuciones íntegras (**art. 48.i**).","No. No se limita a las básicas.","No. No es proporcional a la reducción: es retribuida.","No. No existe ese 75 por ciento."]},{"id":"of-07-011","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":11,"enunciado":"Según el artículo 48 del TREBEP, ¿cuántos días de permiso corresponden a un funcionario de carrera por traslado de domicilio sin cambio de residencia?","opciones":["Dos días.","Cinco días.","Tres días.","Un día."],"bloque":"jornada","precepto":"Art. 48.b del TREBEP","correcta":3,"justificaciones":["No. Es un día, no dos.","No. Es un día, no cinco.","No. Es un día, no tres.","Es esta. Un día (**art. 48.b**)."]},{"id":"of-07-012","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":12,"enunciado":"De acuerdo con el TREBEP, la prestación del servicio mediante teletrabajo:","opciones":["Responderá a un porcentaje determinado de acuerdo con el número de empleados públicos de la unidad administrativa.","Habrá de ser expresamente autorizada y será compatible con la modalidad presencial.","Tendrá carácter forzoso de acuerdo con los criterios que se establezcan para su desarrollo.","Como regla general, podrá suponer como máximo hasta el cincuenta por ciento de la jornada laboral en términos semanales."],"bloque":"jornada","precepto":"Art. 47 bis.2 del TREBEP","correcta":1,"justificaciones":["No. El teletrabajo no responde a un porcentaje por número de empleados.","Es esta. Habrá de ser expresamente autorizada y será compatible con la modalidad presencial (**art. 47 bis.2**).","No. Tiene carácter voluntario y reversible, no forzoso.","No. El artículo no fija un máximo del cincuenta por ciento."]},{"id":"of-07-013","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":13,"enunciado":"Según el TREBEP, ¿pueden sustituirse las vacaciones anuales de un funcionario por una compensación económica?","opciones":["No, en ningún caso.","Sí, cuando no fuera posible su disfrute en el año natural, por necesidades de servicio debidamente motivadas.","Sí, en casos de conclusión de la relación de servicio por causas ajenas a la voluntad de los funcionarios.","Sí, en casos de incapacidad temporal que sobreviniera una vez iniciado el disfrute vacacional."],"bloque":"jornada","precepto":"Art. 50.3 del TREBEP","correcta":2,"justificaciones":["No. Hay una excepción: la conclusión de la relación de servicios por causas ajenas a la voluntad.","No. Las necesidades de servicio no permiten sustituirlas por dinero.","Es esta. En la conclusión de la relación de servicios por causas ajenas a su voluntad se puede solicitar compensación económica (**art. 50.3**).","No. La incapacidad temporal permite disfrutarlas después, no cobrarlas (**art. 50.2**)."]},{"id":"of-07-014","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":14,"enunciado":"Según el artículo 48 del TREBEP, los funcionarios públicos disponen de un permiso por fallecimiento de un familiar:","opciones":["Dentro del primer grado de consanguinidad o afinidad, de 2 días hábiles cuando el suceso se produzca en la misma localidad, y 4 días hábiles cuando sea en distinta localidad.","Dentro del segundo grado de consanguinidad o afinidad, de 3 días hábiles cuando el suceso se produzca en la misma localidad, y 5 días hábiles cuando sea en distinta localidad.","Dentro del primer grado de consanguinidad o afinidad, de 3 días hábiles cuando el suceso se produzca en la misma localidad, y 5 días hábiles cuando sea en distinta localidad.","Dentro del primer grado de consanguinidad pero no de afinidad, de 3 días hábiles cuando el suceso se produzca en la misma localidad, y 5 días hábiles cuando sea en distinta localidad."],"bloque":"jornada","precepto":"Art. 48.a del TREBEP","correcta":2,"justificaciones":["No. En primer grado son tres días en la misma localidad y cinco en otra.","No. En segundo grado son dos días en la misma localidad y cuatro en otra.","Es esta. Primer grado de consanguinidad o afinidad: tres días hábiles en la misma localidad y cinco en distinta (**art. 48.a**).","No. El primer grado incluye la afinidad."]},{"id":"of-07-015","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":15,"enunciado":"Según el TREBEP, ¿a cuál de estos permisos podría acogerse una funcionaria por razón de violencia de género?","opciones":["Reducción de la jornada, siempre con disminución proporcional de retribuciones.","Reducción de la jornada, percibiendo las retribuciones íntegras si su jornada se reduce en dos tercios o menos.","Reducción de la jornada, percibiendo las retribuciones básicas si su jornada se reduce en dos tercios o menos.","Reducción de la jornada, percibiendo las retribuciones íntegras si reduce su jornada en un tercio o menos."],"bloque":"jornada","precepto":"Art. 49.d del TREBEP","correcta":3,"justificaciones":["No. Mantiene las retribuciones íntegras si reduce un tercio o menos.","No. El umbral es un tercio, no dos tercios.","No. El umbral es un tercio y las retribuciones son íntegras, no solo las básicas.","Es esta. Reducción de jornada con retribuciones íntegras si reduce un tercio o menos (**art. 49.d**)."]},{"id":"of-07-016","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":16,"enunciado":"Según el artículo 50 del TREBEP, ¿qué ocurre cuando a un funcionario que ha iniciado el periodo vacacional le sobreviene una situación de incapacidad temporal?","opciones":["El periodo vacacional no se interrumpe, seguirá disfrutando sus vacaciones hasta que finalicen según su solicitud.","El periodo vacacional se podrá disfrutar, aunque haya terminado el año natural a que correspondan, siempre que no hayan transcurrido más de dieciocho meses a partir del final del año en que se hayan originado.","Se interrumpe el periodo vacacional y el tiempo que le reste sólo lo podrá disfrutar dentro del año natural a que correspondan.","Se interrumpe el periodo vacacional pudiéndose disfrutar en cualquier momento, aunque haya terminado el año natural a que correspondan."],"bloque":"jornada","precepto":"Art. 50.2 del TREBEP","correcta":1,"justificaciones":["No. Se puede disfrutar después, no hay que seguir.","Es esta. Se podrán disfrutar aunque haya terminado el año natural, sin superar los dieciocho meses desde el final del año en que se originó (**art. 50.2**).","No. No queda limitado al año natural.","No. No es en cualquier momento: hay un límite de dieciocho meses."]},{"id":"of-07-017","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":17,"enunciado":"Señale la afirmación FALSA. De acuerdo con el Estatuto Básico del Empleado Público, son permisos por motivos de conciliación de la vida personal, familiar y laboral y por razón de violencia de género:","opciones":["Permiso por adopción o acogimiento.","Permiso del progenitor diferente de la madre biológica por nacimiento.","Permiso por razón de violencia de género sobre los empleados públicos.","Permiso por nacimiento para la madre biológica."],"bloque":"jornada","precepto":"Art. 49.d del TREBEP","correcta":2,"justificaciones":["Es verdadera, así que no se marca (**art. 49.b**).","Es verdadera, así que no se marca (**art. 49.c**).","Esta es la falsa, y por eso es la que hay que marcar. El permiso es de las funcionarias víctimas de violencia de género o sexual, no de los empleados públicos en general (**art. 49.d**).","Es verdadera, así que no se marca (**art. 49.a**)."]},{"id":"of-07-018","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":18,"enunciado":"Según el TREBEP, cuando las situaciones de permiso de maternidad, incapacidad temporal, riesgo durante las lactancia o riesgo durante el embarazo impidan iniciar el disfrute de las vacaciones dentro del año natural al que correspondan, o una vez iniciado el periodo vacacional sobreviniera una de dichas situaciones, el periodo vacacional se podrá disfrutar, aunque haya terminado el año natural a que correspondan y siempre que no hayan transcurrido:","opciones":["Más de doce meses a partir del final del año en que se hayan originado.","Más de dieciocho meses a partir del final del año en que se hayan originado.","Doce meses desde la fecha en que fue autorizado el disfrute del permiso o licencia interrumpido.","Los veintidós días hábiles correspondientes al periodo de vacaciones legalmente reconocido."],"bloque":"jornada","precepto":"Art. 50.2 del TREBEP","correcta":1,"justificaciones":["No. El plazo es de dieciocho meses, no doce.","Es esta. No más de dieciocho meses desde el final del año en que se originó (**art. 50.2**).","No. No se cuenta desde la autorización del permiso.","No. Los veintidós días son la duración de las vacaciones, no el plazo."]},{"id":"of-07-019","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":19,"enunciado":"¿Cuántos días de permiso por asuntos particulares tendrá al año un funcionario de nuevo ingreso?","opciones":["Tres días.","Cinco días.","Ocho días.","Seis días."],"bloque":"jornada","precepto":"Art. 48.k del TREBEP","correcta":3,"justificaciones":["No. Son seis días, no tres.","No. Son seis días, no cinco.","No. Son seis días, no ocho.","Es esta. Seis días al año (**art. 48.k**)."]},{"id":"of-07-020","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":20,"enunciado":"¿Cuántos días de permiso tendrá María Ibáñez por la reforma de su nuevo domicilio según el artículo 48 del Estatuto Básico del Empleado Público?","opciones":["En el Estatuto Básico del Empleado Público no existe ningún tipo de permiso para la reforma del domicilio.","Por reforma del domicilio, tres días.","Por reforma del domicilio, un día por cada año de antigüedad.","Por reforma del domicilio, cinco días, no aplicándose en caso de que no vaya a residir en la vivienda reformada."],"bloque":"jornada","precepto":"Art. 48 del TREBEP","correcta":0,"justificaciones":["Es esta. El art. 48 no prevé permiso por reforma del domicilio.","No. No existe ese permiso de tres días.","No. No existe ese permiso.","No. No existe ese permiso de cinco días."]},{"id":"of-07-021","origen":"oficiales","test":"TREBEP (Oficial 7) - arts. 41 a 51","n":21,"enunciado":"De acuerdo con el artículo 47 bis del texto refundido de la Ley del Estatuto Básico del Empleado Público, el personal público que preste sus servicios mediante teletrabajo:","opciones":["Tendrá una adaptación de los deberes y derechos, individuales y colectivos, del resto del personal que preste sus servicios en modalidad presencial, sin incluir en todo caso la normativa de prevención de riesgos laborales que resulte aplicable.","Tendrá los mismos deberes y derechos, individuales y colectivos, que el resto del personal que preste sus servicios en modalidad presencial, incluyendo la normativa de prevención de riesgos laborales que resulte aplicable, salvo aquellos que sean inherentes a la realización de la prestación del servicio de manera presencial.","Tendrá deberes y derechos, individuales y colectivos, diferentes a los del resto del personal que preste sus servicios en modalidad presencial.","Tendrá los mismos deberes y derechos que el resto del personal que preste sus servicios en modalidad presencial, incluyendo la normativa de prevención de riesgos laborales que resulte aplicable, salvo aquellos que sean inherentes a la realización de la prestación del servicio de manera presencial y excluyendo los derechos de tipo colectivo."],"bloque":"jornada","precepto":"Art. 47 bis.3 del TREBEP","correcta":1,"justificaciones":["No. Tiene los mismos deberes y derechos, y la normativa de prevención de riesgos se incluye.","Es esta. Los mismos deberes y derechos, individuales y colectivos, incluida la prevención de riesgos, salvo los inherentes a la presencialidad (**art. 47 bis.3**).","No. No son diferentes.","No. No se excluyen los derechos colectivos."]},{"id":"of-08-001","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":1,"enunciado":"Según artículo 62 del TREBEP, ¿cuál es el orden correcto en el cumplimiento sucesivo de requisitos para adquirir la condición de funcionario de carrera?","opciones":["Superación del proceso selectivo, nombramiento, acto de acatamiento de la CE y toma de posesión.","Superación del proceso selectivo, acto de acatamiento de la CE, y toma de posesión.","Superación del proceso selectivo, nombramiento y acto de acatamiento de la CE.","Superación del proceso selectivo, toma de posesión, nombramiento y acto de acatamiento de la CE."],"bloque":"acceso","precepto":"Art. 62.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Superación del proceso selectivo, nombramiento, acatamiento de la Constitución y toma de posesión (**art. 62.1**).","No. Falta el nombramiento.","No. Falta la toma de posesión.","No. La toma de posesión es el último requisito."]},{"id":"of-08-002","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":2,"enunciado":"De acuerdo con lo establecido en el Texto Refundido del Estatuto Básico del Empleado Público, señale la afirmación correcta en relación con el acceso al empleo público de las personas con discapacidad:","opciones":["En las convocatorias se reservará un cupo no inferior al 7% de las vacantes para ser cubiertas entre personas con discapacidad.","En las convocatorias se reservará un cupo del 7% de las vacantes para ser cubiertas entre personas con discapacidad.","En las ofertas de empleo público se reservará un cupo no inferior al 7% de las vacantes para ser cubiertas entre personas con discapacidad.","En las ofertas de empleo público se reservará un cupo no superior al 7% de las vacantes para ser cubiertas entre personas con discapacidad."],"bloque":"acceso","precepto":"Art. 59.1 del TREBEP","correcta":2,"justificaciones":["No. El cupo se reserva en las ofertas de empleo público, no en las convocatorias.","No. No es un cupo fijo, sino no inferior, y es en las ofertas.","Es esta. En las ofertas de empleo público, un cupo no inferior al siete por ciento (**art. 59.1**).","No. Es un mínimo, no un máximo."]},{"id":"of-08-003","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":3,"enunciado":"Señale la afirmación correcta. Conforme al TREBEP, los órganos de selección de los procesos selectivos para el acceso al empleo público se caracterizan por:","opciones":["Estar constituidos por un número impar de miembros no inferior a tres.","Tener una composición que tiende a la paridad entre la mujer y el hombre.","Estar presididos por personal de designación política.","Contar con algún miembro que actúe en representación de las organizaciones sindicales."],"bloque":"acceso","precepto":"Art. 60.1 del TREBEP","correcta":1,"justificaciones":["No. El artículo no fija un número impar ni un mínimo de tres.","Es esta. Se tenderá a la paridad entre mujer y hombre (**art. 60.1**).","No. El personal de designación política no puede formar parte (**art. 60.2**).","No. La pertenencia es a título individual, no en representación (**art. 60.3**)."]},{"id":"of-08-004","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":4,"enunciado":"Señale la afirmación correcta. Según el TREBEP, un nacional de otro Estado Miembro de la Unión Europea:","opciones":["No puede ser empleado público.","Solo puede ser personal eventual.","Solo puede ser personal laboral.","Puede ser personal funcionario."],"bloque":"acceso","precepto":"Art. 57.1 del TREBEP","correcta":3,"justificaciones":["No. Puede ser empleado público.","No. No se limita al personal eventual.","No. No solo laboral: también funcionario.","Es esta. Puede acceder como personal funcionario, con las excepciones del poder público (**art. 57.1**)."]},{"id":"of-08-005","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":5,"enunciado":"Según el TREBEP, en las Ofertas de Empleo Público se reservará para ser cubierto con personas con discapacidad:","opciones":["Un cupo no inferior al 5%, de modo que al menos un 2% de las plazas ofertadas sean para ser cubiertas por personas con discapacidad intelectual y el resto para personas que acrediten cualquier otro tipo de discapacidad.","Un cupo no inferior al 9%, de modo que al menos un 2% de las plazas ofertadas sean para ser cubiertas por personas con discapacidad intelectual y un 7% para personas que acrediten cualquier otro tipo de discapacidad.","Un cupo no inferior al 3% de modo que al menos un 2% de las plazas ofertadas sean para ser cubiertas por personas con discapacidad intelectual y el resto para personas que acrediten cualquier otro tipo de discapacidad.","Un cupo no inferior al 7%, de modo que al menos un 2% de las plazas ofertadas sean para ser cubiertas por personas con discapacidad intelectual y el resto para personas que acrediten cualquier otro tipo de discapacidad."],"bloque":"acceso","precepto":"Art. 59.1 del TREBEP","correcta":3,"justificaciones":["No. El cupo es del siete por ciento, no del cinco.","No. El cupo es del siete por ciento, no del nueve.","No. El cupo es del siete por ciento, no del tres.","Es esta. No inferior al siete por ciento, con al menos un dos por ciento para discapacidad intelectual (**art. 59.1**)."]},{"id":"of-08-006","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":6,"enunciado":"Según el TREBEP, señale la respuesta correcta en relación con los órganos de selección:","opciones":["No podrá formar parte el personal con menos de cinco años de antigüedad como funcionario de carrera.","La pertenencia a los mismos podrá, en determinados supuestos, ostentarse en representación o por cuenta de alguien.","No podrán formar parte los funcionarios interinos.","No podrá formar parte el personal funcionario que haya obtenido la prolongación de la permanencia en el servicio activo."],"bloque":"acceso","precepto":"Art. 60.2 del TREBEP","correcta":2,"justificaciones":["No. El artículo no exige cinco años de antigüedad.","No. Es siempre a título individual (**art. 60.3**).","Es esta. No pueden formar parte los funcionarios interinos (**art. 60.2**).","No. La prolongación del servicio activo no es causa de exclusión."]},{"id":"of-08-007","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":7,"enunciado":"Según el artículo 57 del TREBEP, podrá eximirse del requisito de la nacionalidad por razones de interés general para el acceso a la condición de personal funcionario:","opciones":["Por resolución de la Secretaria de Estado de Función Pública.","Por acuerdo de los órganos de gobierno de las Administraciones Públicas.","Por ley de las Cortes Generales o de las Asambleas Legislativas de las Comunidades Autónomas.","Por orden del Ministerio de Hacienda y Administraciones Públicas."],"bloque":"acceso","precepto":"Art. 57.5 del TREBEP","correcta":2,"justificaciones":["No. Una resolución no basta: hace falta ley.","No. Un acuerdo no basta: hace falta ley.","Es esta. Por ley de las Cortes Generales o de las asambleas legislativas autonómicas (**art. 57.5**).","No. Una orden ministerial no basta: hace falta ley."]},{"id":"of-08-008","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":8,"enunciado":"De acuerdo con el Real Decreto Legislativo 5/2015, de 30 de octubre, podrá establecerse otra edad máxima, distinta de la edad de jubilación forzosa, para el acceso al empleo público:","opciones":["Solo por ley.","Solo en virtud de Real Decreto aprobado por el Gobierno de la Nación.","Mediante orden del Ministro que convoque el proceso selectivo.","Mediante resolución del Subsecretario del Ministerio que convoque el proceso selectivo."],"bloque":"acceso","precepto":"Art. 56.1.c del TREBEP","correcta":0,"justificaciones":["Es esta. Solo por ley (**art. 56.1.c**).","No. Un real decreto no basta: hace falta ley.","No. Una orden ministerial no basta.","No. Una resolución no basta."]},{"id":"of-08-009","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":9,"enunciado":"El TREBEP establece para los procesos selectivos que:","opciones":["Los órganos de selección tendrán carácter unipersonal o colegiado.","El Departamento al que esté adscrito el Cuerpo correspondiente designará la mitad de miembros del órgano de selección.","Los órganos de selección se nombrarán para cada proceso selectivo y tendrán duración anual.","Las pruebas podrán consistir en la comprobación de los conocimientos y la capacidad analítica de los aspirantes."],"bloque":"acceso","precepto":"Art. 61.2 del TREBEP","correcta":3,"justificaciones":["No. Los órganos de selección son colegiados (**art. 60.1**).","No. El Estatuto no prevé esa designación de la mitad por el departamento.","No. El Estatuto no fija que se nombren cada año.","Es esta. Las pruebas pueden consistir en la comprobación de conocimientos y capacidad analítica, oral o escrita (**art. 61.2**)."]},{"id":"of-08-010","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":10,"enunciado":"Una de las medidas adoptadas por el Ministerio es la convocatoria de un proceso selectivo de un Cuerpo de funcionarios adscrito al mismo. El Subsecretario es propuesto para formar parte del Órgano de Selección. ¿Puede formar parte de él?","opciones":["Sí, al ser funcionario de carrera.","No, por ser un alto cargo.","Sí, por ser funcionario de carrera del Cuerpo que se convoca.","No, por ser personal eventual."],"bloque":"acceso","precepto":"Art. 60.2 del TREBEP","correcta":1,"justificaciones":["No. Aunque sea funcionario, el personal de designación política no puede formar parte.","Es esta. Un Subsecretario es un alto cargo de designación política (**art. 60.2**).","No. Ser del Cuerpo convocado no cambia la exclusión.","No. No es personal eventual, pero igualmente no puede formar parte."]},{"id":"of-08-011","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":11,"enunciado":"Según el TREBEP, la edad mínima y la edad máxima de acceso al empleo público es, respectivamente:","opciones":["16 años cumplidos y no exceder, en su caso, de la edad máxima de jubilación forzosa.","18 años cumplidos, sin que exista ninguna edad máxima de acceso.","16 años, siendo la edad máxima 60 años.","No existe límite de ningún tipo, sino tener la titulación y superar el proceso selectivo correspondiente."],"bloque":"acceso","precepto":"Art. 56.1.c del TREBEP","correcta":0,"justificaciones":["Es esta. Dieciséis años cumplidos y no exceder de la edad máxima de jubilación forzosa (**art. 56.1.c**).","No. La edad mínima es dieciséis, y sí hay máximo: la jubilación forzosa.","No. El máximo es la jubilación forzosa, no 60 años.","No. Hay límites de edad."]},{"id":"of-08-012","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":12,"enunciado":"Según el TREBEP, los extranjeros con residencia legal en España pueden acceder a las Administraciones Públicas en igualdad de condiciones que los españoles:","opciones":["Como personal laboral.","Como funcionarios interinos y como personal laboral temporal.","Como funcionarios de carrera.","Como funcionarios de carrera y personal eventual."],"bloque":"acceso","precepto":"Art. 57.4 del TREBEP","correcta":0,"justificaciones":["Es esta. Pueden acceder como personal laboral en igualdad de condiciones (**art. 57.4**).","No. No se prevé el acceso como funcionarios interinos.","No. Como funcionarios de carrera, solo los nacionales de la Unión Europea y asimilados.","No. No como funcionarios de carrera ni como personal eventual."]},{"id":"of-08-013","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":13,"enunciado":"Señale la respuesta correcta, según el artículo 60 del TREBEP, en relación a los órganos de selección:","opciones":["La pertenencia será siempre a título individual, salvo los miembros suplentes que actuarán en representación de los titulares.","La pertenencia será siempre a título individual, no pudiendo ostentarse esta en representación o por cuenta de nadie.","Serán colegiados y la pertenencia a los mismos será siempre a título colectivo.","Estarán formados por personal funcionario, laboral o eventual."],"bloque":"acceso","precepto":"Art. 60.3 del TREBEP","correcta":1,"justificaciones":["No. No hay excepción para los suplentes.","Es esta. Siempre a título individual, sin ostentarse en representación o por cuenta de nadie (**art. 60.3**).","No. La pertenencia no es a título colectivo.","No. No pueden formar parte el personal eventual ni otros excluidos (**art. 60.2**)."]},{"id":"of-08-014","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":14,"enunciado":"En los términos del artículo 61.6 del TREBEP, ¿cuándo podrá aplicarse como sistema selectivo de funcionarios de carrera, con carácter excepcional, el sistema de concurso consistente únicamente en la valoración de méritos?","opciones":["Solo en virtud de lo que establezca al efecto la convocatoria correspondiente.","Solo en virtud de las disposiciones al efecto de la Oferta de Empleo Público correspondiente.","Solo en virtud de norma legal o reglamentaria.","Solo en virtud de ley."],"bloque":"acceso","precepto":"Art. 61.6 del TREBEP","correcta":3,"justificaciones":["No. No basta la convocatoria: hace falta ley.","No. No basta la oferta de empleo público: hace falta ley.","No. No basta una norma reglamentaria: hace falta ley.","Es esta. Solo en virtud de ley (**art. 61.6**)."]},{"id":"of-08-015","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":15,"enunciado":"Según el TREBEP, ¿cuál de los siguientes colectivos de personal al servicio de las Administraciones públicas puede formar parte de un órgano de selección en procesos selectivos de personal laboral?","opciones":["Personal de designación política.","Personal eventual.","Personal funcionario interino.","Personal laboral."],"bloque":"acceso","precepto":"Art. 60.2 del TREBEP","correcta":3,"justificaciones":["No. El personal de designación política no puede formar parte.","No. El personal eventual no puede formar parte.","No. Los funcionarios interinos no pueden formar parte.","Es esta. El personal laboral no figura entre los excluidos del **art. 60.2**."]},{"id":"of-08-016","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":16,"enunciado":"De acuerdo con el TREBEP, la posibilidad de establecimiento para el acceso al empleo público de otra edad máxima, distinta de la edad de jubilación forzosa, solo podrá realizarse:","opciones":["Por ley.","Por el real decreto que apruebe la oferta de empleo público.","Mediante las bases de la convocatoria.","Por orden ministerial del departamento al que esté adscrito el cuerpo o escala que se convoque."],"bloque":"acceso","precepto":"Art. 56.1.c del TREBEP","correcta":0,"justificaciones":["Es esta. Solo por ley (**art. 56.1.c**).","No. Un real decreto no basta: hace falta ley.","No. Las bases de la convocatoria no bastan.","No. Una orden ministerial no basta."]},{"id":"of-08-017","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":17,"enunciado":"Señale la respuesta INCORRECTA respecto a los requisitos que se deben cumplir, según el artículo 62 del Estatuto Básico del Empleado Público, para adquirir la condición de funcionario de carrera:","opciones":["Toma de posesión dentro del plazo que se establezca.","Acto de acatamiento de la Constitución y del Estatuto de Autonomía de la Comunidad Autónoma donde resida el aspirante.","Superación del proceso selectivo.","Nombramiento por el órgano o autoridad competente, que será publicado en el Diario Oficial correspondiente."],"bloque":"acceso","precepto":"Art. 62.1.c del TREBEP","correcta":1,"justificaciones":["Es verdadera, así que no se marca (**art. 62.1.d**).","Esta es la falsa, y por eso es la que hay que marcar. El acatamiento es del Estatuto de Autonomía correspondiente, no del de la comunidad donde resida el aspirante (**art. 62.1.c**).","Es verdadera, así que no se marca (**art. 62.1.a**).","Es verdadera, así que no se marca (**art. 62.1.b**)."]},{"id":"of-08-018","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":18,"enunciado":"De acuerdo a lo regulado en el TREBEP, en relación a las personas con discapacidad en las Ofertas de Empleo Público:","opciones":["Se reservará un cupo no inferior al cinco por ciento de las vacantes para ser cubiertas entre personas con discapacidad.","Se reservará un cupo no inferior al siete por ciento de las vacantes para ser cubiertas entre personas con discapacidad.","Se reservará un cupo no superior al diez por ciento de las vacantes para ser cubiertas entre personas con discapacidad.","Se reservará un cupo superior al nueve por ciento de las vacantes para ser cubiertas entre personas con discapacidad."],"bloque":"acceso","precepto":"Art. 59.1 del TREBEP","correcta":1,"justificaciones":["No. El cupo es del siete por ciento, no del cinco.","Es esta. No inferior al siete por ciento (**art. 59.1**).","No. Es un mínimo, no un máximo, y la cifra es siete.","No. La cifra es siete por ciento, no más del nueve."]},{"id":"of-08-019","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":19,"enunciado":"De acuerdo con el artículo 53 del texto refundido de la Ley del Estatuto Básico del Empleado Público, dentro del Código de conducta de los empleados públicos, es un principio ético:","opciones":["Desempeñar las tareas correspondientes a su puesto de trabajo de forma diligente y cumpliendo la jornada y el horario establecidos.","No aceptar ningún trato de favor o situación que implique privilegio o ventaja injustificada, por parte de personas físicas o entidades privadas.","Administrar los recursos y bienes públicos con austeridad, y no utilizar los mismos en provecho propio o de personas allegadas. Tendrán, asimismo, el deber de velar por su conservación.","Garantizar la atención al ciudadano en la lengua que lo solicite."],"bloque":"deberes","precepto":"Art. 53.7 del TREBEP","correcta":1,"justificaciones":["No. Es un principio de conducta (**art. 54.2**).","Es esta. No aceptar trato de favor o privilegio es un principio ético (**art. 53.7**).","No. Es un principio de conducta (**art. 54.5**).","No. Es un principio de conducta (**art. 54.11**)."]},{"id":"of-08-020","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":20,"enunciado":"Según el artículo 62 del texto refundido de la Ley del Estatuto Básico del Empleado Público, ¿cuál de los siguientes requisitos es necesario cumplir para adquirir la condición de funcionario de carrera?","opciones":["Toma de posesión dentro de los tres días posteriores al nombramiento.","Acto de acatamiento de la Constitución y, en su caso, del Estatuto de Autonomía correspondiente y del resto del Ordenamiento Jurídico.","Superación del proceso selectivo, aunque en ese momento no se reúna la titulación requerida en la convocatoria.","Toma de posesión al día siguiente de haber sido nombrado."],"bloque":"acceso","precepto":"Art. 62.1.c del TREBEP","correcta":1,"justificaciones":["No. La toma de posesión es dentro del plazo que se establezca, no en tres días.","Es esta. Acto de acatamiento de la Constitución, del Estatuto de Autonomía correspondiente y del resto del ordenamiento (**art. 62.1.c**).","No. Hay que acreditar los requisitos de la convocatoria, incluida la titulación (**art. 62.2**).","No. La toma de posesión no es al día siguiente, sino dentro del plazo que se establezca."]},{"id":"of-08-021","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":21,"enunciado":"El artículo 61 del texto refundido de la Ley del Estatuto Básico del Empleado Público, establece que los sistemas selectivos de personal laboral fijo serán:","opciones":["Los de concurso oposición o entrevista.","Los de concurso oposición o concurso de valoración de méritos con entrevista.","Los de oposición o concurso oposición con entrevista.","Los de oposición, concurso oposición o concurso de valoración de méritos."],"bloque":"acceso","precepto":"Art. 61.7 del TREBEP","correcta":3,"justificaciones":["No. Falta la oposición y la entrevista no es un sistema.","No. Falta la oposición y el concurso no lleva entrevista obligatoria.","No. Falta el concurso de valoración de méritos.","Es esta. Oposición, concurso-oposición o concurso de valoración de méritos (**art. 61.7**)."]},{"id":"of-08-022","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":22,"enunciado":"De acuerdo con el artículo 59 del texto refundido de la Ley del Estatuto Básico del Empleado Público, ¿qué porcentaje de plazas debe reservarse en las ofertas de empleo público para personas que acrediten discapacidad intelectual?","opciones":["Al menos el 2%.","Al menos el 3%.","Al menos el 5%.","Al menos el 7%."],"bloque":"acceso","precepto":"Art. 59.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Al menos el dos por ciento (**art. 59.1**).","No. El mínimo es el dos por ciento, no el tres.","No. El mínimo es el dos por ciento, no el cinco.","No. El siete por ciento es el cupo total de discapacidad."]},{"id":"of-08-023","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":23,"enunciado":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, ¿cuál de estos requisitos es necesario reunir para poder participar en los procesos selectivos de acceso al empleo público?","opciones":["Tener cumplidos dieciséis años y no exceder, en su caso, de la edad mínima de jubilación forzosa.","Tener cumplidos dieciséis años y no exceder, en su caso, de la edad máxima de jubilación forzosa.","Tener cumplidos dieciocho años y no exceder, en su caso, de la edad máxima de jubilación forzosa..","En el caso de ser nacional de otro Estado, no hallarse inhabilitado o en situación equivalente ni haber sido sometido a sanción pecuniaria o equivalente que impida, en el Estado español, en los mismos términos el acceso al empleo público."],"bloque":"acceso","precepto":"Art. 56.1.c del TREBEP","correcta":1,"justificaciones":["No. Es la edad máxima de jubilación forzosa, no la mínima.","Es esta. Dieciséis años cumplidos y no exceder, en su caso, de la edad máxima de jubilación forzosa (**art. 56.1.c**).","No. La edad mínima es dieciséis, no dieciocho.","No. Habla de sanción disciplinaria o equivalente, no pecuniaria, y en el Estado de origen (**art. 56.1.d**)."]},{"id":"of-08-024","origen":"oficiales","test":"TREBEP (Oficial 8) - arts. 52 a 62","n":24,"enunciado":"Según el artículo 60 del texto refundido de la Ley del Estatuto Básico del Empleado Público, los órganos de selección son:","opciones":["Individualistas.","Solidarios.","Mancomunados.","Colegiados."],"bloque":"acceso","precepto":"Art. 60.1 del TREBEP","correcta":3,"justificaciones":["No. No son individualistas.","No. No son solidarios.","No. No son mancomunados.","Es esta. Los órganos de selección son colegiados (**art. 60.1**)."]},{"id":"of-10-004","origen":"oficiales","test":"TREBEP (Oficial 10) - arts. 69 a 84","n":4,"enunciado":"¿Qué instrumento de planificación de los recursos humanos en las Administraciones Públicas tiene como objetivo establecer las necesidades de recursos humanos para proveer mediante la incorporación de personal de nuevo ingreso?","opciones":["Los Planes de ordenación de los recursos humanos.","Las Relaciones de puestos de trabajo.","Los Registros de personal.","La Oferta de empleo público."],"bloque":"provision","precepto":"Art. 70.1 del TREBEP","correcta":3,"justificaciones":["No. Los planes de ordenación son más amplios (**art. 69.2**).","No. Las relaciones de puestos estructuran la organización (**art. 74**).","No. Los registros recogen datos del personal.","Es esta. Las necesidades que se proveen con personal de nuevo ingreso son objeto de la Oferta de empleo público (**art. 70.1**)."],"dup":"au-15-008"},{"id":"vo-02-011","origen":"votaciones","test":"TREBEP (Votación Clase 2)","n":11,"enunciado":"Para el seguimiento de los Pactos y Acuerdos se establecerán, con la composición y funciones que las partes determinen:","opciones":["Mesas Generales de Negociación.","Organizaciones sindicales.","Comisiones Paritarias.","Mesas Sectoriales."],"bloque":"negociacion","precepto":"Art. 38.5 del TREBEP","correcta":2,"justificaciones":["No. Las Mesas Generales son donde se negocia.","No. Las organizaciones sindicales son una de las partes.","Es esta. El **art. 38.5** establece Comisiones Paritarias de seguimiento.","No. Las Mesas Sectoriales negocian, no hacen el seguimiento."],"dup":"au-05-009"}]});
